--
-- 数据库： `crmneimao`
--

DELIMITER $$
--
-- 函数
--
CREATE DEFINER=`root`@`localhost` FUNCTION `only_digits` (`str` VARCHAR(255)) RETURNS VARCHAR(255) CHARSET utf8mb4 DETERMINISTIC NO SQL BEGIN
    DECLARE i   INT DEFAULT 1;
    DECLARE len INT;
    DECLARE result VARCHAR(255) DEFAULT '';
    DECLARE ch  CHAR(1);

    SET len = CHAR_LENGTH(str);
    WHILE i <= len DO
        SET ch = SUBSTRING(str, i, 1);
        IF ch BETWEEN '0' AND '9' THEN
            SET result = CONCAT(result, ch);
        END IF;
        SET i = i + 1;
    END WHILE;

    RETURN result;
END$$

DELIMITER ;

