--
-- 表的结构 `admin`
--

CREATE TABLE `admin` (
  `admin_id` int(11) NOT NULL COMMENT '管理员ID',
  `username` varchar(20) NOT NULL COMMENT '管理员用户名',
  `pwd` varchar(70) NOT NULL COMMENT '管理员密码',
  `group_id` mediumint(8) DEFAULT NULL COMMENT '分组ID',
  `email` varchar(30) DEFAULT NULL COMMENT '邮箱',
  `realname` varchar(10) DEFAULT NULL COMMENT '真实姓名',
  `tel` varchar(30) DEFAULT NULL COMMENT '电话号码',
  `ip` varchar(20) DEFAULT NULL COMMENT 'IP地址',
  `add_time` int(11) DEFAULT NULL COMMENT '添加时间',
  `mdemail` varchar(50) DEFAULT '0' COMMENT '传递修改密码参数加密',
  `is_open` tinyint(2) DEFAULT '0' COMMENT '审核状态',
  `avatar` varchar(120) DEFAULT '' COMMENT '头像',
  `mubiao` float(100,0) DEFAULT NULL COMMENT '当月目标业绩',
  `ticheng` float(10,0) DEFAULT NULL COMMENT '提成点%',
  `curgetnum` int(11) DEFAULT '0' COMMENT '当前用户使用抢的次数',
  `curmaxnum` int(11) DEFAULT NULL COMMENT '用户当前抢的最大值',
  `parent_id` int(11) DEFAULT NULL COMMENT '直属主管admin_id（可选）',
  `team_name` varchar(50) DEFAULT NULL COMMENT '所属团队名称（展示用）',
  `org` varchar(10) DEFAULT '' COMMENT '所属组织(admin,1s,2s,3s)',
  `channel` varchar(30) DEFAULT '' COMMENT '渠道',
  `operation_ports` varchar(500) DEFAULT NULL COMMENT '运营端口（多个店铺名称用逗号分隔）',
  `position` tinyint(1) DEFAULT '0' COMMENT '1-运营总监/2-运营主管',
  `inquiry_id` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '询盘来源id',
  `port_id` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '运营端口id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='后台管理员' ROW_FORMAT=DYNAMIC;

