  `as_id` tinyint(5) NOT NULL,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '广告位名称',
  `sort` int(11) NOT NULL COMMENT '广告位排序'
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='广告分类' ROW_FORMAT=DYNAMIC;

