--
-- 表的结构 `crm_client_hangye`
--

CREATE TABLE `crm_client_hangye` (
  `id` int(11) NOT NULL,
  `hy_name` varchar(255) DEFAULT NULL,
  `add_time` bigint(20) DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- 表的结构 `crm_client_order`
--

CREATE TABLE `crm_client_order` (
  `id` int(11) NOT NULL COMMENT '主键id',
  `order_no` varchar(100) NOT NULL COMMENT '订单编号',
  `contact` varchar(100) DEFAULT '' COMMENT '联系方式',
  `order_type` int(11) DEFAULT '1' COMMENT '订单类型(1新单,2返单)',
  `return_count` int(10) UNSIGNED DEFAULT '0' COMMENT '返单次数',
  `cphone` varchar(100) DEFAULT NULL COMMENT '客户手机号',
  `pr_user` varchar(100) NOT NULL COMMENT '负责人名称',
  `pr_user_id` int(11) UNSIGNED DEFAULT NULL COMMENT '负责人ID(admin.admin_id)',
  `cname` varchar(100) NOT NULL COMMENT '客户名称',
  `customer_type_flag` tinyint(1) NOT NULL DEFAULT '0' COMMENT '用户属性：0=公司，1=个人',
  `country` varchar(255) DEFAULT NULL COMMENT '发货详细地址',
  `source` varchar(100) DEFAULT '' COMMENT '询盘来源',
  `source_port` varchar(255) NOT NULL COMMENT '询盘来源端口',
  `team_name` varchar(100) DEFAULT '' COMMENT '团队名称',
  `customer_type` varchar(100) DEFAULT '' COMMENT '客户性质',
  `product_name` varchar(100) DEFAULT '' COMMENT '产品名称',
  `product_supplier` varchar(255) DEFAULT NULL COMMENT '产品供应商',
  `order_time` datetime DEFAULT NULL COMMENT '订单成交时间',
  `money` decimal(10,2) NOT NULL COMMENT '订单金额',
  `ticheng` decimal(10,2) DEFAULT '0.00' COMMENT '提成金额',
  `profit` decimal(10,2) DEFAULT '0.00' COMMENT '利润',
  `margin_rate` decimal(10,2) DEFAULT '0.00' COMMENT '利润率',
  `status` varchar(20) NOT NULL DEFAULT '1' COMMENT '业绩状态 1 待审核 2 审核不通过 3 审核通过',
  `remark` varchar(255) DEFAULT '' COMMENT '备注',
  `create_time` datetime NOT NULL COMMENT '添加时间',
  `first_create_time` datetime DEFAULT NULL COMMENT '首次创建/首次提交时间(不变)',
  `at_user` varchar(100) NOT NULL COMMENT '创建人',
  `at_user_id` int(11) UNSIGNED DEFAULT NULL COMMENT '创建人ID(admin.admin_id)',
  `ut_time` datetime DEFAULT NULL COMMENT '更新时间',
  `oper_user` varchar(30) DEFAULT '' COMMENT '所属运营',
  `client_company` varchar(255) DEFAULT NULL COMMENT '客户公司',
  `province` varchar(50) DEFAULT NULL COMMENT '省份',
  `city` varchar(50) DEFAULT NULL COMMENT '城市',
  `joint_person` varchar(255) DEFAULT NULL COMMENT '协同人',
  `amount_received` varchar(255) DEFAULT NULL COMMENT '已收款金额',
  `split_remarks` varchar(255) DEFAULT NULL COMMENT '分成备注',
  `sales_commission` varchar(255) DEFAULT NULL COMMENT '佣金',
  `tax_amount` varchar(255) DEFAULT NULL COMMENT '税费金额',
  `debugging_cost` varchar(255) DEFAULT NULL COMMENT '调试费',
  `invoice_amount` varchar(255) DEFAULT NULL COMMENT '开票金额',
  `invoice_type` varchar(20) DEFAULT NULL COMMENT '票种性质：普票、专票、不开票',
  `shipping_cost` varchar(255) DEFAULT NULL COMMENT '估算运费',
  `bank_account` varchar(255) DEFAULT NULL COMMENT '收款账户',
  `bank_account_name` varchar(255) DEFAULT NULL COMMENT '收款账户名称（下单时快照）',
  `wechat_receipt_image` text COMMENT '客户微信回执图（多图JSON数组）',
  `inquiry_assign_image` varchar(255) DEFAULT NULL COMMENT '产品询盘分配图',
  `check_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核状态：0草稿、1待审核、2审核通过、3审核不通过',
  `audit_user_id` int(11) DEFAULT NULL COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核意见'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户订单表';

