(198, 70572, 98, '在WhatsApp上沟通的，说是政府招标，推荐了1*4一体机和一个烘干机，说是和团队商量一下\n第二次要全自动的烘干机，报价46000.但是指定要AGICO牌子，回复说可以在机器上印上这个logo', 1753149258),
(199, 68429, 142, '7.11下午客户询问有没有冷饮机，于是找厂家联系，客户说要100台，但必须确认德国的制冷剂标准，沟通后客户说他会搜索当地的制冷剂标准，7.14问情况怎样但未回复.', 1753167539),
(200, 55355, 142, '客户的经理在度假，大概十天左右，客户7.7号说下周日打电话交流,7.20号', 1753167596),
(201, 69129, 142, '7.13日沟通发送核桃脱壳机视频图片，14日回复没有问题，客户住在南方非布鲁方丹。运到德班港客户回复OK。于是制作报价单，告诉客户我如果急着需要可以提前发货，但客户回复最早要明年六月，下一个丰收季节。\n14号晚问他以前使用机器没，客户回复第一次使用，于是询问是否要开个公司，客户回复不是，只是为他的山核桃提高附加值，', 1753167691),
