(204, 68500, 142, '撞单', 1753167860),
(205, 66539, 142, '7.7 日产品信息都要已经沟通好，客户需要注册企业，大概一个月。这个客户意向可以但大部分时间都在断网状态。客户也很诚实说他们国家官僚主义严重，注册企业需要很多时间很多钱，我告诉他别急，我会耐心等待。中间也一直联系。', 1753167904),
