(211, 72051, 138, '客户要50kg/h的，给客户推荐了两款小型豆腐机，视频，从阿里转邮件转WA，报价了，等待回复。', 1753340561),
(212, 72001, 138, '①给客户发了图片，视频。报价了，客户要色选机和分级机，分别发了视频。\n②7.24确认好了客户需要分级的种类，非常多，和厂家沟通后给客户推荐报价，正在等回复。', 1753340583),
(213, 66513, 138, '7.17联系上了，说自己没钱，叔叔妻子不同意，不放心在中国买。7.20联系上，一直分享生活，已经不抗拒聊天，打算在当地买，正在营销劝说中。\n②7.24给客户大降价，运费由小柜转拼箱，便宜5200，但是客户还是坚持说他叔叔要在当地买，不是他自己出钱购买餐车，还在营销中。', 1753340611),
(214, 71320, 138, '②7.24推荐客户买棉花糖和爆米花机，给了500折扣，客户说没钱，营销客户付500意向金，正在等回复。', 1753340643),
(215, 69374, 138, '7.21联系上，还要木薯脱皮机，正在报价中。客户要很多机器，需求不清晰，\n7.24给客户推荐先买腰果和木薯脱壳机，给了500折扣，做了报价单，客户说和工厂反馈，正在等消息。', 1753340765),
(216, 124438, 142, '24号上午收到询盘建档，由于时差原因，下午联系但信息一直显示未收到，晚上再打电话联系。', 1753351703),
(217, 123891, 142, '22日晚收到阿里询盘，建档并索要联系方式Whats app。23日发送蓝莓色选机图片和工作视频供客户了解。进一步沟通得知客户只在乎机器能筛选出软的坏的蓝莓，从而留下硬的质量好的蓝莓，客户有自己的货运代理，只需要一小时处理100KG的产量，24日发送报价单并询问客户代理的联系方式但未回复。25号制作并发送报价单，让他查看， 之后回复他需要时间，他会尽可能回到这个项目上来，于是我回复没关系我会等待，有任何关于机器的细节，参数售后问题都可以问我，请向我及时更新你的信息，这样我才能及时与工厂安排。', 1753351796),
