(349, 124700, 138, '加了WA，客户喜欢漂亮的，推的方拖，他不是很喜欢，清风系列价格太贵，预算大概6500USD,正在跟进中，加了WA，客户喜欢漂亮的，推的方拖，他不是很喜欢，清风系列价格太贵，预算大概6500USD,正在跟进中，喜欢那个大车雪铁龙', 1754392456),
