(713, 137098, 163, '8.31跟进  客户主做热食，烧烤，冰箱等设备，预算4000USD ,看网站价格，在沟通', 1756700449),
(714, 137758, 68, '1:9.1 已打通视频，解释亚马逊加分不是最终价格，和客户要了他喜欢的餐车的图片，客户暂未打发过来，会持续跟进', 1756708499),
(715, 137674, 68, '1： 9.1 确定要5米长，在和厂家沟通价格，会持续跟进', 1756708648),
(716, 137718, 163, '9.1  客户是公司，第一次买1台，如果ok ,买10台，作为商业用途，投资，报价披萨机8850USD ,其它功能另外报价', 1756713834),
(717, 137608, 150, '1. 9.1客户要两台四米与八米，四米口头报价6029美金，客户觉得价格可以，明天他到公司与设计师商量具体细节', 1756714075),
(718, 134291, 133, '已报价机器和运输到塞内加尔达喀尔港口的费用', 1756715007),
(719, 137734, 161, '客户有喜欢的款式：方拖和清风款，分别给客户报价了，看客户选择和预算范围。客户主动问到：您知道我需要遵循哪些程序才能在我国收到它吗？ 给客户回复并问下能否在港口提货，目前确认是布埃纳文图拉更近。', 1756715555),
(720, 137803, 161, '客户方拖，18英尺长，给客户发了图片和视频，要客户的信息客户没有回复。已口头报价10500美金，问道燃气配置，需要额外750美金，总计11250美金，等客户查看继续沟通', 1756715876),
(721, 134081, 60, '3500美金在当地买', 1756718969),
(722, 136072, 140, '客户最后上线于8.27凌晨为回复消息；周四、周日晚上打电话未接', 1756720489),
(723, 134082, 144, '客户退群', 1756722669),
(724, 68561, 164, '要扭花的机器，已发参数，厂家使用的原材料状态不同，跟客户确认中', 1756725431),
(725, 137857, 119, '9.1光发了一个询盘，啥都没说。根据页面猜测想要小型的薯条生产线，发送了食品。未读。', 1756726500),
(726, 68217, 138, '①6.18推荐了三款棉花糖机，发了价格图，不回复，营销，分享生活，不回复。加了WA，\n②7.22回复了，客户应该是中间商，还有3个库存，\n③持续营销中，只读不回。', 1756726986),
(727, 124700, 138, '①加了WA，客户预算大概6500USD,喜欢雪铁龙，担心各种西班牙的法规，客户最近很忙，\n②7.30-8.21一直不回复，说出去旅游了\n③8.21发了西班牙客户的付款截图回复了，跟进营销还是不怎么回复', 1756727103),
(728, 137685, 163, '9.1 客户懂，需要64层燃气烤箱，发送图片视频，等客户回复报价', 1756727155),
(729, 125047, 138, '①客户要一台，想要纯牛奶的，找到厂家了，\n②客户7.27后没上线，发邮件，发信息，一直联系不上，偶尔营销', 1756727184),
(730, 66514, 138, '已读不回，大概率不买，再问问', 1756727375),
(731, 72001, 138, '①给客户发了图片，视频。报价了，客户要色选机和分级机，分别发了视频。\n②7.24确认好了客户需要分级的种类，非常多，和厂家沟通后给客户推荐报价，正在等回复。\n③7.26价格说定了，不回信息，难以推进\n④7.30回国了，客户现在不需要，偶尔营销', 1756727412),
(732, 69374, 138, '①报价后不怎么回信息，持续营销中。7.21联系上，还要木薯脱皮机，正在报价中。客户要很多机器，需求不清晰，\n②7.24给客户推荐先买腰果和木薯脱壳机，给了500折扣，做了报价单，客户说和工厂反馈，正在等消息。\n③没钱，预算不够，2000预算让买腰果脱壳，不买，要贵的木薯脱皮\n④9.1偶尔营销，已读不回，近期不买', 1756727474),
(733, 137662, 163, '9.1  发送图片，等客户回复', 1756727553),
(734, 126457, 138, '①7.30-8.9推荐了很多款式，终于有客户喜欢的了，已经报价，报运费，满足了客户的定制需求，交定金/设计费/意向金都不交\n②8.10-8.17等客户买的其他机器到了规划预算，一边营销\n③8.17客户问方拖，报价，一边营销一边聊生活\n④8.17-26，客户找到1500的圆拖，没有竞争优势推了方拖，客户不喜欢，又要做计划，营销中\n⑤客户大概率选择便宜商家，并没有竞争优势，不间断跟进', 1756727677),
(735, 127096, 138, '①报价后不回复，运费4000USD太贵，持续营销，不喜欢信息轰炸\n②8.9已经在其他公司购买了，低价挽回，客户和伙伴商量\n③8.9以后不回信息，营销中', 1756727737),
(736, 127674, 138, '①打电话不接，发消息不读，联系不上', 1756727757),
(737, 127959, 138, '①发了报价单，发票，\n②客户购购买车位后，再付款\n③8.11后不怎么回信息，持续营销中', 1756727909),
(738, 128671, 138, '①只有几百美元，想买清风餐车，8.8准备贷款，正在等贷款情况\n②8.28客户说只能贷款1000美元，推荐便宜方拖，不回信息，持续营销中', 1756727957),
(739, 128712, 138, '阿里一直不读，联系不上', 1756728010),
(740, 129634, 138, '8.21成交', 1756728079),
(741, 130320, 138, '加上就联系不上', 1756728124),
(742, 130894, 138, '要拍照摄像机器人，可能是博主，阿里发信息已读不回，在跟进一下', 1756728275),
(743, 130139, 138, '①发了两封邮件，客户要炒股、计算彩票、送餐机器人，推荐了送餐机器人\n②8.12第三封信报了价，等回复，8.15发邮件询问进度\n③8.20客户回信觉得价格贵，他觉得机器人价格200美元合适，我解释了机器人的高科技性和价格的合理性，不回复', 1756728326),
(744, 137098, 163, '8.30 发送细节，客户发自己需要的圆拖图片急需要的小设备，9.1号营销客户，为他报价', 1756728576),
(745, 129123, 138, '报完价格，再不回复', 1756728670),
(746, 131097, 138, '①8.13-18给客户报价，披萨机比较贵，艾玩-彩云卷-鑫之源，10500-8500，一直找便宜厂家，客户预算7500，定金/意向金都不交，一直说价格高\n②联系、营销客户中，不怎么回信息', 1756728751),
(747, 131676, 138, '发了邮件报价和详情，一直不回复，阿里已读不回', 1756728827),
(748, 131760, 138, '①8.15报价了饮料零食自动售卖机，客户在安排\n②8.20客户说自己很忙，持续跟进中', 1756728848),
(749, 131937, 138, '①8.18给客户报价、报了运费\n②报价后客户不回信息，正在跟进中', 1756728867),
(750, 131904, 138, '①4米餐车报价和运费，给客户搭配了内饰，客户在规划，\n②8.19给客户更改了内饰方案，客户一直说要存钱再买，\n③8.28定金意向金都要不到，继续营销要钱', 1756728880),
(751, 132356, 138, '①8.16-17给客户报价4.5米黑色常规款方拖，解答客户细节\n②8.18报运费和总价，8.20客户了解了规格价格后不回信息\n正在跟进联系中', 1756728897),
(752, 132427, 138, '①8.17客户预算只有1000，冰激淋机6000多，预算不够，\n②8.20又问折叠房，准备做投资，没钱\n③8.20根据预算推荐了零食售货机，客户没钱，跟进中', 1756728915),
(753, 133321, 138, '客户要8000-12000产量的豆腐脑加包装卖到韩国，客户需求还没确定好，很多厂家说做不了这么大量，', 1756729004),
(754, 133825, 138, '等待确认信息', 1756729112),
(755, 134348, 138, '①8.22报价包运费，给50折扣，发付款链接，客户没付款\n②后来客户不回信息，一直营销联系中', 1756729176),
(756, 135700, 138, '①8.25-27报了披萨机、棉花糖机的价格，发了视频\n②8.29客户说家里有人去世，九月联系', 1756729342),
(757, 135926, 138, '①8.26给客户报了100L的希腊酸奶生产线，\n②8.27按照客户的要求更改了部分信息，客户说价格还可以，需要先获得当地的许可证，\n③8.28给客户折扣想要来定金/意向金，客户没读，一直跟进中', 1756729368),
(758, 136065, 138, '让销售人员联系我，已读不回', 1756729471),
(759, 132145, 138, '①8.16客户准备明年买，问客户喜欢的款式\n②8.20-21客户对网站价格与实际价格不符有些生气，3-4人推荐了5米的餐车，客户想自己选择长度，一直不回复，联系中', 1756729514),
(760, 133504, 138, 'v', 1756729587),
(761, 133504, 138, '①8.16-17给客户报价4.5米黑色常规款方拖，解答客户细节\n②8.18报运费和总价，8.20客户了解了规格价格后不回信息\n③9.1客户不读，大概率找了其他厂家，正在跟进联系中', 1756729592),
(762, 72051, 138, '①客户要50kg/h的，给客户推荐了两款小型豆腐机，视频，从阿里转邮件转WA，报价了，等待回复。\n②要面条机。豆卷机，需求不明确，年底来中国后买\n③无法推进，又提到售货机，问了拉面机，说不符合规定', 1756729657),
(763, 127178, 138, '8.10客户发邮件说不感兴趣，不要再联系她', 1756729693),
(764, 130531, 138, '①8.11按照客户需求推荐了一款人型＋有拍照功能的机器人，客户执着要一摸一样的人形机器人，需要定制，厂家不做一台\n②给客户推荐了其他人型机器人，客户不喜欢，一直不回复，隔几天联系一次', 1756729771),
(765, 133168, 138, '①客户挺专业，8.19报过价了，客户说9-10月要来中国，看过披萨机再买，意大利要求严格\n②坚持意大利要求严格，营销中', 1756729791),
(766, 136630, 138, '加上它朋友，朋友购买，这两天忙', 1756729953),
(767, 137342, 138, '①8.29-9.1客户是购买新手，产量非常小，但是要全自动的，报了全自动产量最小最便宜的，已报价报运费，正在问客户什么时候买', 1756730017),
(768, 137225, 138, '9.1给客户制作了两套生产线，等待客户回复，估计要便宜的', 1756730055),
(769, 137394, 138, '①正在问客户的具体产量和需求', 1756730069),
(770, 137794, 138, '客户两个人工作，亚马逊价格3000左右，推荐三米的，客户想要4米的，找便宜厂家问价，跟进中', 1756730115),
