(772, 137873, 138, '不说产品，问图片', 1756730199),
(773, 137603, 164, '已发配置，暂未找到合适的工厂，找到几个工厂不能处理客户要求的消毒方式', 1756730528),
(774, 137406, 164, '直接打电话，加拿大，想了解运费，要多台，做餐车，宠物店等 要做不同方案的图片', 1756730572),
(775, 137403, 164, '已发信息 圆拖，2人，推荐3米，煎炸、做煎饼和咖啡的东西，已报价', 1756730644),
(776, 137154, 164, '电话打通，自己已经有一台餐车，想要再买一台，2个人，问是否发过波多黎各，美国是否有库存，想要定制3个窗户，稍后发照片 发基本配置，问需求', 1756731122),
(777, 137433, 120, '8.31 联系客户说想要10+32的披萨机，放在商场用，问我要报价单\n9.1 给客户做了报价单，客户回复了谢谢，后面没有回复', 1756775054),
(778, 137767, 120, '9.1 客户开始想要清风款，口头报价，预算不够，又推荐了圆拖，口头报价3米，客户问从亚马逊下订单吗，查了客户的邮箱有阿里账号，推荐了阿里巴巴和TT付款，客户说要从阿里巴巴下单', 1756775228),
(779, 138091, 68, '9.2 已发名片披萨机工作视频 联系', 1756775330),
(780, 135744, 143, '8.26 建立初步联系，客户确定好款式和价格并询问了付款方式 解释两种付款方式后下线\n8.27 问了我运输流程、运费、要了报价单之后不回复估计是睡觉去了 晚上发了消息还没有已读\n8.28 没有找到更便宜的货代 客户表示了感谢 紧接着问客户是否满意价格 可以聊聊产品细节 不读不回复\n8.29 今天一天都没有上线，两天后进行营销。\n8.30 客户今天上线已读不回\n9.1 发了最新的报价表 未读', 1756776908),
(781, 136871, 143, '8.29 南非餐车跟进情况：\n8.29 按照他选中的型号报价，客户觉得太贵，推荐了更便宜的型号。\n8.30 客户发过来他看到的竞品的信息和价格，大概差1200usd，我分析解释产品优势。客户不打算在我这买，我提出可以打折扣，客户已读不回。\n9.1 再次提出折扣问题 客户已读不回\n后续跟进策略：\n松跟：2-3天发简短跟进、7天后分享新的成单案例、21天后打电话。', 1756776952),
(782, 137035, 143, '8.29 客户是购买订单又取消的，询问了真实价格之后不回复，推荐了更便宜的型号还未读。\n8.30 客户已读不回，推荐了更小型号的价格，上线了一次不读我消息\n9.1 说了可以有折扣，客户依旧已读不回', 1756776993),
(783, 137016, 143, '\"8.29 客户下单未付款说没有购买餐车的需求\n8.30 客户向我询问清风餐车的价格 感觉太贵 我推荐了方托的，客户觉得这个不错，但是还想要更便宜的，我询问预算客户不告诉我，又问了电三轮的价格 电三轮不单卖，还没回我。\n8.31 客户相中了一款，说正在存钱 让我帮他讲讲价 多赠送点东西 \n9.1 今天已经发了消息，还没上线\"', 1756777018),
(784, 137073, 143, '\"8.29 给客户发送了餐车视频，询问了基本需求，说了第二天为他查询运费\n8.30 给客户发送了昨天需要的视频和简单报价，客户还未读。\n9.1 客户一直未读 今天发了信息跟进\"', 1756777047),
(785, 137338, 143, '\"8.29 发了他喜欢的款式，询问了业务以及长度，客户正在确定设备清单\n9.1 客户未读 今天发了信息简短跟进\"', 1756777071),
