(814, 132429, 146, '8.24要给她报总价，客户说要阿里巴巴15期付款，报价后已读未回，应该没钱，觉得太贵了，8.25、8.26、8.28跟进未回复', 1756793991),
(815, 135880, 146, '8.26给客户报了实际价格，客户说要检查一下，之后没有回复，应该是对价格太高接受不了，8.27.、8.28、8.29进行了营销和跟进，已读未回，9.2发消息未读', 1756794597),
(816, 69508, 146, '8.26又做了个付款链接，但客户还是没付，说要等找到工作之后再付款，9.2给她发了消息，暂未回复', 1756794723),
(817, 130476, 146, '8.22给客户做了付款链接，但是客户看到需要额外增加关税之后，不买了，说不相信港口，用了很多话术，8.26说暂时不买了，8.27、8.29跟进未读，后续再尝试', 1756794864),
