(820, 137982, 146, '9.2给客户回答了一些问题，客户要内部图片，发送完以后问他送货方式，已读未回，可能睡觉了', 1756795089),
(821, 131337, 146, '8.13沟通，想用一半的价格买机器，应该接受不了机器的价格，8.15、8.16、8.20、8.25、8.28、8.30、9.2给客户发消息、营销、打电话，都联系不上', 1756795227),
(822, 130920, 146, '8.12报价后问客户需要的支付模块，客户不回，8.15、8.16、8.17、8.20、8.25跟进未回，8.26打视频接通说在忙然后挂断，8.28、8.30继续跟进，联系不上', 1756795368),
