(836, 138181, 145, '100L巴氏杀菌罐 已报价 询问购买时间 未回复（9.2）', 1756798179),
(837, 138181, 145, '请忽略上边的记录\n\n500L 牛奶冷却罐 已报价和运费 询问了关税 询问采购时间 未回复（9.2）', 1756798375),
(838, 138234, 60, '反向卖马赛克瓷砖', 1756800798),
(839, 135874, 122, '客户要求切鲜肉成条 单刀一组双刀一组 已报价 \n9.1客户更新需求，已跟技术确认，帮客户定制机器 已报价\n9.2客户说跟partner商量后反馈', 1756802392),
(840, 135874, 122, '客户要求切鲜肉成条 单刀一组双刀一组 已报价 \n9.1客户更新需求，已跟技术确认，帮客户定制机器 已报价\n9.2客户说跟partner商量后反馈', 1756802395),
(841, 135007, 122, '25客户售卖圆筒墨盒 问题多 意向强  已来回多封邮件进行沟通\n26客户要看到类似产品的操作视频 等客户发实物 安排厂家拍摄\n27已给客户发视频确认 28客户回复说第一次采购想慎重考虑 考虑好了回复\n29邮件未回复  \n9.1邮件未回', 1756802557),
(842, 133323, 122, '客户需要15mm厚，8/10mm直径，每小时处理15-20公斤，成本2万，已报到门价，客户说预算不够，但会省钱买这个机器，8.19要定金 21跟进客户说给他几周的时间省钱 25跟进未回\n27跟进未回 9.1跟进未回\n9.2客户回复说资金被其他项目耽误，一个月后再买', 1756802594),
(843, 133697, 122, '要求每小时产量150个 产量要求太少 做不了产线\n8.20 搭配了十几台小单机组合 已报价 \n8.22报价小型产线 \n8.25客户再跟他的客户确认 8.26发货图营销', 1756802632),
(844, 137319, 122, '8.30打电话确认需求，餐车设备待确认。\n9.2跟客户确认设备，并已发详细报价。', 1756803422),
(845, 137835, 122, '9.1给客户推荐热销款，已报价，客户嫌贵。推荐了不带机械臂的自助贩卖机。\n9.2 推荐单独的机械臂款式，客户说考虑一下。', 1756807116),
(846, 53743, 144, '8.14:给客户应餐车生产视频、水单进行了营销，客户并没有回复                                                 8.27：给客户营销了水单，并愿意给客户保留之前的很便宜的价格，目前没有回复', 1756809256),
(847, 71334, 144, '客户需要处理草莓，完成草莓工作之后在购买，大概在10月份或者是11月份，目前打算持续跟进，现在目前每周至少聊一次天，能感觉跟客户的距离正在拉近                 8.15：聊草莓                                            8.22：给客户进行了聊天，闲聊了一会，客户要去体检，并且墨西哥的雨水已经比较少了，聊的并不多，打算周一询问结果                                      8.25：问客户体检报告结果，客户没有事情，简单了聊了几句话', 1756809311),
(848, 71334, 144, '已经给客户报过了价格，查过了运费，说是要和同伴商量，客户读消息，但是一直不回复                              8.18：营销了水单但是没有回复                           8.20：给客户营销了展会照片，并询问什么时候购买，没有读消息                                                8.22：给客户制造了一些焦虑，说8月份订单很多，目前有很多订单在排队，如果您早些购买我可以跟老板申请优先购买                                             8.25：给客户发送了发货视频，进行营销，未读                  8.27：给客户发送了水单营销，只读了水单                            8.30：给客户发送了七夕团队图片营销，客户没有回复', 1756809397),
(849, 71334, 144, '已经给客户报过了价格，查过了运费，说是要和同伴商量，客户读消息，但是一直不回复                              8.18：营销了水单但是没有回复                           8.20：给客户营销了展会照片，并询问什么时候购买，没有读消息                                                8.22：给客户制造了一些焦虑，说8月份订单很多，目前有很多订单在排队，如果您早些购买我可以跟老板申请优先购买                                             8.25：给客户发送了发货视频，进行营销，未读                  8.27：给客户发送了水单营销，只读了水单                            8.30：给客户发送了七夕团队图片营销，客户没有回复', 1756809414),
(850, 66891, 144, '客户需要处理草莓，完成草莓工作之后在购买，大概在10月份或者是11月份，目前打算持续跟进，现在目前每周至少聊一次天，能感觉跟客户的距离正在拉近                 8.15：聊草莓                                            8.22：给客户进行了聊天，闲聊了一会，客户要去体检，并且墨西哥的雨水已经比较少了，聊的并不多，打算周一询问结果                                      8.25：问客户体检报告结果，客户没有事情，简单了聊了几句话', 1756809458),
(851, 125121, 144, '根据客户清单推荐产品，目前超出了客户的预算，购买时间需要给前老板商议，打算持续营销                       8.15：给客户发送了展会图片进行营销\n8.18：给客户发送了水单，并询问客户什么时候购买产品\n8.20：看到客户发布了动态，以此为话题发送消息,并发送了客户来访图片，再次邀请客户来中国，发现客户没有读消息，后来客户回复，我将会联系你                                                      8.22：发现客户没有读消息，询问客户是否在忙，是否发生了什么事情，发现客户在线但是没有回复                                                                                                                                      8.26：给客户发送了发货视频，营销，没有读                                                                            8.28：给客户发送了脱壳机的视频，营销是别的客户购买的，目前没有读                                           9.1：给客户营销了折扣，并询问什么时候买', 1756809505),
(852, 124724, 144, '对价格满意，但是客户说没有做好准备去购买，打算持续营销，接下来打算持续营销                               8.14：给小姐姐营销了一下餐车生产图片，并询问了目前对餐车是否有什么想法\n8.18：给小姐姐发送了团建视频，营销生活\n8.20：给客户发送了交付视频，并编故事说是墨西哥国家和马来西亚的客户要的餐车                               8.22：给客户说明目前的订单比较多，如果这周购买可以优先安排生产                                            8.25：给客户发送了发货视频，并且接下来是订单的旺季，询问想要什么时候购买，客户回复不要再给他发消息，他到时候会告诉我，打算减少营销频率，一周营销一次                         9.1：给客户进行了折扣营销，并再次询问什么时候购买', 1756809600),
(853, 124364, 144, '客户预计9月购买产品，暂时确定了产品和运费,还没有找好工厂，给客户用参展图片和公司视频进行了营销，并且经常和客户以客户的饼干生产情况为话题进行聊天              打算八月底给折扣营销一下                                                                                                                      8.20：给客户进行问候，但没有回复                                                                                           8.21：得到了客户的回复，了解到客户比较忙，正在建设自己的新工厂，目前没有提到付款，打算持续营销                                                                                                                             8.25：给客户发送了发货视频，并且接下来是订单的旺季，询问想要什么时候购买，客户只是回复了很好，并没有回答问题，打算持续营销                                                                   \n8.27：给客户提议可以在现在或者9月10号之前付款，这样在厂房完成之后就可以收到货了，客户已读，但没有回复                                                                                                       8.28：给客户问好是否在忙客户只是回复，目前在忙，问工厂也没有弄好，客户没有回复                              8.30：给客户发送了七夕团队照片，得到了客户的回复，只是问候了一句                                            9.1：给客户进行了折扣营销，并再次询问什么时候购买', 1756809654),
(854, 124003, 144, '客户表示延迟了购买计划，因为黎巴嫩的形势比较严峻，目前没有想好什么时候会购买，打算接下来一个星期给客户营销1-2次                                                                                               8.18：营销了展会照片、并得到了回复，打算下周已继续营销                                                   8.27：给客户发送了发货视频进行营销，并嘱咐客户注意安全', 1756809678),
(855, 126325, 144, '半年之后再决定购买产品，目前对产品很满意', 1756809715),
(856, 126556, 144, '客户还没有建厂，大概在10月份之后购买，给客户用参展照片，公司视频进行了营销                                 8.14：给客户说自己去了展会，公司的产品受到了欢迎，\n8.18：给客户说明了目前不参加任何展会，但是邀请了客户来参观公司\n8.20：给客户进行了营销，发送了客户来访照片，并邀请客户来公司参观，客户已读但未回                         8.25：给客户发送了发货视频，并且接下来是订单的旺季，询问想要什么时候购买，已读未回                           8.30：给客户发送了七夕团队的照片，得到了客户的回复，然后营销了9月将会有很多的折扣活动，如果在9月购买可以在9月参加折扣活动，享受优惠 ，客户表示会考虑一下，并跟财务商量状况', 1756809743),
(857, 126802, 144, '自从报过价之后，客户并没有回复消息，给客户营销了公司视频，团队参加展会照片，还有提单水单等，目前没有读消息                                                                                                     8.15：给客户发送了展会照片，营销\n8.18：客户回复我他很忙，以后会给我回复，问他大概什么时候回复也没有说\n8.21：给客户发送了客户好评的图片，进行营销，并且询问购买时间                                               8.26：给客户发送了客户使用货物图片，并再次询问什么时候可以给我结果，什么时候购买，没有回复                                                                                                                                     8.28：给客户发送了水单营销，客户没有看完消息，只看了一半，没有回复，客户表示公司正在竞标，竞标完成之后才可以进行考虑是否购买，等待结果                                                         9.2：询问客户竞标的结果有没有出来，并且宣传了折扣活动', 1756809782),
(858, 127897, 144, '已经给客户发送了邮件，邮件内容是推荐了几款色选机的照片和功能目前客户没有回复', 1756809815),
(859, 130146, 144, '给客户发送了小番茄磨浆机的视频， 目前还没有回复，给客户留了Whtasapp号码一直显示未读', 1756809835),
(860, 130702, 144, '8.16:客户需要购买5台鲜花机，客户目前正处于市场考察阶段，但告诉我对我发送的产品很感兴趣，说会联系我,十月份会购买                                                                                                  8.18:客户表示想要找我好好聊一聊，讨论产品的事情，说必须要带有冷藏的9格鲜花机，但是价格比较贵，不接受                                                                                                                    8.20：给客户查询了运费，客户接受了6格带有冷藏的鲜花机，目前正在确认支付模块                                   8.21：客户想用信用卡借记卡模块和纸币模块，但是厂家只能提供刷卡器，正在跟客户协商是否能接受一种支付方式                                                                                                                     8.25：给客户制作了报价单，一份英语一份西班牙语 明天约好的时间打电话                                         8.27：给客户打了电话，但是客户还是打算10月份购买，因为正在申请目前政府的各种文件                         8.30：给客户发送了七夕团队照片营销，得到了客户的回复', 1756809869),
(861, 131031, 144, '8.18:已经给客户发送了报价，还是没有联系上，后来跟运营联系发现客户一直没有在线                                   8.21：打了电话，直接秒挂，给客户发送了付款记录水单营销                                                     9.1：说了一下9月购买会有很多的折扣，没有回复', 1756809888),
(862, 132532, 144, '8.18:客户在网站上留言表示自己有10000美元的预算，想要做咖啡生意，已经给客户发送了邮件，提供了FOB价格8720美元的方案，包括餐车和设备，等待回复中              \n8.20：给客户发送了邮件确认是否查看到报价，并请求可以加WHATSAPP                                             8.21：客户回复目前正在考虑和解决事情，我表示关于餐车的一切因素可以跟我进行讨论和商量，并且再次询问是否对报价满意，目前没有收到回复                          8.28：给客户发送了一封邮件，告诉客户9月即将是旺季，所以尽快的确认产品，并优先为客户安排生产，等待回复', 1756809909),
(863, 132642, 144, '8.18:已经给客户简单的报过了价格，但是仍然有许多细节需要和客户确认，等待客户回复中                              8.21：客户已经读了消息，但是没有回复，给客户说已经跟老板商量同意给您好的价格，但是需要先确认细节，目前未读', 1756809936);
INSERT INTO `crm_comment` (`id`, `leads_id`, `user_id`, `reply_msg`, `create_date`) VALUES
(864, 133167, 144, '8.19：确认了餐车、运费，客户讯问是否需要税费等其他费用，回答可以提供门到门服务，不用再交任何费用，还没有回复                                                                                                  8.21：客户表示，正在进行许可证证明工作，打算持续营销                                                      8.25：给客户发送了发货视频，并且接下来是订单的旺季，询问想要什么时候购买                                     8.27：给客户营销了水单，并给客户说，如果您想要尽快拿到餐车，我可以安排您的餐车和这位客户的餐车一起生产                                                                                                                   9.1：给客户进行了折扣营销，并再次询问什么时候购买', 1756809975),
(865, 133171, 144, '8.19：说对餐车不满意，询问不满意的点在哪，并没有读消息，也没有回                                           8.21：询问客户是否可以做2.1米宽的餐车，还有确认灯泡，并发送了确认了设备的文件，客户表示需要直接按照他的图片进行定制，不接受建议                                                                     8.25：给客户营销了一下，2.1米宽的餐车和2.4米宽的餐车的不同，价格少了很多，客户觉得2.1米的餐车也不错，并让我在为他重新进行报价，他需要确定设备是进口还是出口                                                  8.26：给客户重新报了价格，报了两个——一个带设备，一个不带设备，然后客户说需要和丈夫讨论一下                                                                                                                                   8.28：客户表示9月1号会查看审批是否通过，如果通过了会考虑是否购买，9月1号会给客户发消息                                                                                                                                              9.1：给客户进行了折扣营销，并再次询问什么时候购买', 1756810015),
(866, 130252, 144, '8.13：给客户打了电话，并且发消息，客户并没有回复我，目前没有确定餐车样式                                 8.22：目前给客户发消息还是没有获得回复                       8.26：询问客户是否想要购买餐车', 1756810041),
(867, 133959, 144, '8.21：给客户推荐了4米便宜款餐车，并且整理了客户想要的设备，也标注了价格                                      8.22：给客户发送了客户好评进行营销，未读                                                                                 8.26：给客户发送了发货视频进行营销                                                                                           8.30：询问客户是否对餐车满意，说明下个月会有折扣活动，询问客户是否参加，没有回复，但是已读', 1756810138),
(868, 134077, 144, '8.21：给客户发送了产品图片，客户说目前正在考虑产品，考虑好了会告诉我，打算持续营销                       8.25：给客户发送了发货视频，并且接下来是订单的旺季，询问想要什么时候购买，并承诺会先优先安排生产，客户表示目前正在经营披萨店，所以最近没有时间去弄餐车的事情，询问什么时候可以联系，并没有给我明确的答案，只是说保持联系，打算营销慢一点，一周营销一次', 1756810168),
(869, 138165, 164, '披萨机， 烤箱，报价CIF', 1756810169),
(870, 135085, 144, '8.25：给客户发送了邮件，并进行报价，目前没有回复', 1756810191),
(871, 135675, 144, '8.25：给客户进行了简单的报价，客户觉得可以                8.26：给客户推荐产量较小的和面机，客户没有回复，打算直接做报价，让客户看                                          8.27：给客户进行了报价，客户对价格比较满意，也查了运费稍微贵一些，给客户回复船只少，还有是船公司的VIP等等，客户说可以接受运费，但是又给我说现在不买，到时候会联系我                                            8.30：给客户营销了一下七夕的团队照片，客户回复很好，只是简单的聊了两句', 1756810212),
(872, 89303, 144, '8.26：给客户进行了报价，查了运费，客户可能觉得贵，并且说了想要折扣，并讲价，我回复这需要给老板申请，我问客户预算，客户没有回复，打算持续营销                                             8.27：给客户说明可以给他折扣，但是客户说目前还需要观望看看买几台合适，还有不知道目前还要不要薯条机            8.30：给客户营销了七夕团队合照，并说9月会有折扣活动，客户想要参加，问是否想要薯条机，客户表示取决于价格，还说他想要机器人，给客户发了参数和图片，问是否要报价，他说他正在吃午饭，要休息                       9.1：给客户发送了9月的折扣活动，询问客户是否愿意购买，没有回复', 1756810241),
