(874, 136215, 144, '感觉客户正在普遍问价，并且在比价                8.27：给客户进行了报价，报的是4米的餐车，还有DDP费用，报完价后没有回复，晚上用水单营销了一次，还是没有回复                                                  8.28：客户说需要和同事商量一下，明天会给我结果，我问两天之后来问他结果她说可以，打算30号给客户发消息      9.1：问客户有没有和同事商量好没有回复，说9月份有折扣活动没有回复', 1756810328),
