(961, 136753, 126, '8.28回答客户的产品基本问题，8.29给客户发相关产品的照片与视频，客户提出售货机的自由杆子的需求，按照客户的需求给客户发相关的照片与视频，客户已读不回；8.30给客户报价，客户还是已读不回，打了WHATSAPP和途信电话，未接；9.1号与客户联系，客户已读不回', 1756883343),
(962, 124700, 138, '①加了WA，客户预算大概6500USD,喜欢雪铁龙，担心各种西班牙的法规，客户最近很忙，\n②7.30-8.21一直不回复，说出去旅游了\n③8.21发了西班牙客户的付款截图回复了，要客户的联系方式，\n④8.29不太想买了，说自己不认识任何人帮她完成认证，担心认证，要西班牙客户联系方式，跟进中', 1756884095),
(963, 128671, 138, '①只有几百美元，想买清风餐车，8.8准备贷款，正在等贷款情况\n②8.28客户说只能贷款1000美元，推荐便宜方拖，不回信息，持续营销中\n③9.2打视频还是没钱，要跟朋友借钱', 1756884113),
(964, 130139, 138, '①发了两封邮件，客户要炒股、计算彩票、送餐机器人，推荐了送餐机器人\n②8.12第三封信报了价，等回复，8.15发邮件询问进度\n③8.20客户回信觉得价格贵，他觉得机器人价格200美元合适，我解释了机器人的高科技性和价格的合理性，不回复\n④9.2发邮件关心近况、说明价格在任何地方都绝对买不到机器人，等待回复', 1756884131),
(965, 137403, 164, '营销澳大利亚案例，采购流程', 1756884161),
(966, 130531, 138, '①8.11按照客户需求推荐了一款人型＋有拍照功能的机器人，客户执着要一摸一样的人形机器人，需要定制，厂家不做一台\n②8.13-8.26给客户推荐了其他人型机器人，发送视频，客户不喜欢，一直不回复，隔几天联系一次\n③8.11后一直不回复，跟进联系中', 1756884163),
(967, 134158, 126, '8.21已给客户报了餐车的价格，客户没有回复，\n8.22推测客户预算不够，问客户预算，推了价格相似的餐车，并且问了油炸锅和冰箱的价格，客户未回消息，\n8.25未回消息，\n8.27未回消息，\n9.3号已打电话，未接；客户回复消息说预算不够，等资金到位后会联系我，我推荐客户可以先支付30%的定金，客户拒绝。后期继续根进', 1756884465),
(968, 135078, 126, '客户需要医疗用品的自动售货机，问客户包装尺寸，客户未回消息，已给客户发相关产品的照片；8.25已给客户报价，8.26询问客户地址，已报运费，已读不回;8.27客户已读不回；9.1号客户已读不回。9.3号打WHATSAPP电话提醒,电话未接', 1756886178),
