(990, 136622, 174, '客户询问了是否可以进口，配送方式等问题，也了解到客户的地址G39C+F8F 贾拉普 墨西哥韦拉克鲁斯，营销了我们在墨西哥的成单案例。但是当我发了一下这些内容后客户已读不回了。\n两个人的话我推荐你选择三米的餐车，价格表如下：\n\n物流费用到墨西哥当地的港口： 620美元\n\n普通款餐车价格：5000美元\n外壁：镀锌板/玻璃钢负压工艺\n内壁：镀锌板，白色\n地板：防滑铝花纹板\n门：1套\n窗户：1大1小（大窗包含一个外展板）橱柜：包括，201不锈钢\n水系统：双水槽+25升水桶2个\n电系统：照明灯+插座每米包括2个\n\n畅销款价格：4000美元\n主体：框架+三明治板（复合板）\n地板：防滑铝花纹板\n门：1套\n窗户：1大1小（大窗包含一个外展板）橱柜：包括，201不锈钢\n水系统：双水槽+25升水桶2个\n电系统：照明灯+插座每米包括2', 1756892722),
