(998, 127825, 173, '这个客户处于报了价之后虽然没有说贵。是一个批发商。但是后续一直处于失联状态。定时是都有跟进的状态。', 1756898857),
(999, 128676, 173, '8.06 报价说月底前进行购买\n8.08 发消息未回\n8.15发消息未回\n8.16回消息生辰最近遇到了资金方面的问题，下个月会买\n8.17发消息未回\n9.01 突然回消息说 没有忘记我们之间的约定 一定会在我这里买 我问时间大概多久 回复说年底前。', 1756899075),
