(1017, 138163, 120, '9.2 客户想要能制作签语饼干的机器，预算2000-5000美金。没找到厂家', 1756950082),
(1018, 138451, 127, '客户对交期的事情问的比较多，应该是比较着急要这个餐车，分别给他报了四米的三米的，昨天报完也没发表意见，报完四米的问三米的可能觉得价格贵。今天继续营销紧跟，有需求。', 1756950203),
