(1055, 138499, 119, '16层热风旋转烤箱（电），价格是 4992 美元。要5台，3%的折扣。最初，每个售价 4,992 美元，因此 5 个烤箱加起来是 24,960 美元。折扣为 749 美元，因此最终价格为 24,211 美元。\n一个烤箱的运费为 1,583 美元，因此五个烤箱的运费为 7,915 美元。这个客户觉得运送到古巴，玛利埃尔，哈瓦那的运费太贵了，然后想要在YMX上看看别的供应商，说他们包含运费。这个我时不时营销一下，他碰壁了能记起我就行。', 1756955769),
