(1163, 133520, 156, '8.20~9.4 客户10月要使用拖车，前后给客户推荐了2款拖车，已营销公司、工厂、水单，客户一直在比价中，期间说可能在我这里购买，昨晚告诉我对拖车不感兴趣了', 1757035011),
