(1171, 139134, 153, '客户是经销商，确定中间层级的机器后报价，报价4050美元，客户说没有利润可图，降价到3850美元+96美元，客户说完美但他要对比价格。', 1757036560),
(1172, 138799, 153, '客户自己使用，准备做冷冻糕点和甜点，3.5m餐车+设备共报价8100美元，客户想要拖拉窗加纱窗，目前在和厂家沟通这个事情', 1757036828),
(1173, 137866, 174, '给客户营销了一些发货信息，亲爱的某某，我今天来帮我意大利和美国的餐车客户发货了，多漂亮的餐车，希望收到您的好消息。', 1757036943),
(1174, 135542, 174, '给客户营销了一些发货信息，亲爱的某某，我今天来帮我意大利和美国的餐车客户发货了，多漂亮的餐车，希望收到您的好消息。', 1757036968),
(1175, 138217, 153, '确定好机器后报价29万多卢布，加运费总价是33万，客户在纠结网站价格13万而自己得到的报价高，我先用话术后用向公司申请优惠安抚住了', 1757036977),
(1176, 136424, 174, '给客户营销了一些发货信息，亲爱的某某，我今天来帮我意大利和美国的餐车客户发货了，多漂亮的餐车，希望收到您的好消息。', 1757037117),
