(1180, 128239, 174, '给客户营销了一些发货信息，亲爱的某某，我今天来帮我意大利和美国的餐车客户发货了，多漂亮的餐车，希望收到您的好消息。', 1757038687),
(1181, 138882, 122, '9.5报了到门总价，打电话未接，还没回消息', 1757038987),
(1182, 138454, 131, '9.3号刚加上WhatsApp，当天打了电话以及视频通话，未接。9.4号依旧联系不上。所以告诉了宗鑫姐帮忙联系上客户，9.5联系上了，发送了客户想要的披萨机的信息，客户还未读，等待。', 1757039229),
(1183, 137656, 131, '9.1号加上客户客户未读，9.2号联系上客户，给客户发送薯条及的相关信息及价格。看见价格后客户又问了一大段问题，一一对客户进行了回复，客户读了积极性不高。继续营销。', 1757039438),
(1184, 138919, 174, '#### September-4-Thursday\n昨天发了信息，客户未读未回，打客户电话\n#### September-5-Friday-10:32\n打客户电话未通，wp电话也未通', 1757039629),
(1185, 139084, 174, '#### September-5-Friday\n在阿里上发了产品信息，客户已读未回\n打阿里电话暂时没人接\n下一步会整理更详细的资料给客户，吸引客户（下午之前发过去）', 1757039763),
(1186, 137999, 131, '9.2号加上客户，客户先表明自己想要在亚马逊付款，马上给他解释亚马逊手续费贵等营销话术。客户预算低，还只喜欢亚马逊付款，后来我继续解释客户突然说自己是亚马逊的工作人员，已经不联系了，害怕出现问题。', 1757039789),
(1187, 138936, 174, '#### September-4-Thursday\n已联系到客户，客户非常热情，自己做披萨进行售卖，报了中吉八万的机器，没有加支付模块的价格。客户问运费，昨晚没及时回复，给客户报了到韦鲁斯港400美金的运费', 1757039957),
(1188, 133923, 131, '因为这个是玉珍的客户，所以不了解据具体聊到啥情况，祝你的话术也刚刚的', 1757040132),
(1189, 138796, 174, '#### September-4-Thursday\n已经联系到客户，客户需要餐车，我先介绍了我们有的常见几种餐车。\n温和的英国老大爷，他们觉得租房比较贵，食物客户储存在家里，可以要一个最小的拖车，这样就不需要支付额外的费用，可以营销我们餐车的实用价值。圆拖，2.3米\n已报价，客户说让我等他。', 1757040270),
(1190, 137915, 159, '与同伴商量要好几周，目前还在等待', 1757040296),
(1191, 137835, 122, '9.4客户说自己有货代\n9.5跟客户视频，客户说别人的报价是3000美金，比我们便宜了一半。联系厂家确认参数和其他型号。', 1757040547),
(1192, 135684, 131, '跟这个客户已经报完价格以及运费等相关信息。客户说自己有100万美元，不是有效客户。', 1757040547),
(1193, 139397, 122, '9.5客户视频未接。客户在酒吧工作，需求不制冷，卖零食，已推荐并报价。', 1757040684),
(1194, 137718, 163, '9.3 报价\n9.4 还好来中国', 1757041559),
