(1214, 135905, 174, '#### September-5-Friday-14:31\n国庆晚上收到客户的回复，客户是一位50岁老大爷，客户人挺好的，家里有大电视，有一定经济基础的老爷爷，重点跟进', 1757054265),
(1215, 135744, 143, '今天给我发了消息 说正在比价', 1757054539),
