(1219, 127595, 174, '#### September-5-Friday-14:51\n客户表示下半年要来中国，客户又一定经济实力，但是不会轻易付款，给他营销我们自动售货机信息，特别是工厂信息，争取在他来中国之前给拿下订单，但并不着急', 1757055151),
(1220, 138509, 122, '9.5跟进，客户说跟村老板申请经营许可证了，通过之后就会给下单购买。', 1757055161),
