(1222, 139449, 146, '确定了餐车和一个热转印烫画机，已发送形式发票，客户还要看其他机器，再决定购买哪些。', 1757055895),
(1223, 138800, 122, '9.4推荐主卖型号，视频参数已发，未回，电话未接\n9.5电话拒接', 1757056544),
(1224, 138853, 116, '客户想要更大的披萨尺寸，合作的几个厂家都没有。给客户营销常规的', 1757056552),
(1225, 139147, 116, '已跟进，客户是中间商，报价已发送同步邮箱', 1757056616),
(1226, 139286, 122, '9.5电话未接，消息未回', 1757056682),
(1227, 138409, 116, '联系上客户  需要零食饮料售货机，发送视频和目录后，不再回复，打电话没有接，会继续联系', 1757056691),
(1228, 139030, 116, '联系上客户，更新了视频和价格，等待客户反馈', 1757056749),
(1229, 139305, 129, '9.5 客户一上来就要问运费，因为是墨西哥现在给他查运费中', 1757056826),
(1230, 139275, 129, '9.5 给他报完价格和运费了，也已经发送付款链接，等明天她回复', 1757056906),
(1231, 139166, 129, '9.5 昨天给他报完价格之后，问运输时间，他很在意运输问题。又问我能不能只要保温板，我说可以，他又问我是否从中国发货，我说是。他说觉得时间长且运费贵。目前我正在给他要地址，查询运费后看情况。', 1757057017),
(1232, 139081, 129, '9.5 他打电话问了很多相关问题。要公司网站看产品。要美国客户反馈图片，问保修问题，如果在一个月内坏了怎么办。客户很精明。感觉不太信任。', 1757057109),
(1233, 136042, 133, '客户说买了个二手的，问价格，不说', 1757057160),
(1234, 139261, 174, '#### September-5-Friday-14:09\n客户醒了，5米清风\n报了8800欧元的价格，可以可以接受\n报了2700欧元的物流费用，可以也能接受，冲一冲了\n客户地址：Si paese Nicosia provincia di Enna regione Sicilia\n美丽的西西里岛', 1757057176),
(1235, 138879, 156, '9.4 询问寻求，发图片，视频消息都未读', 1757057232),
(1236, 131690, 214, '正在尝试取得联系', 1757057236),
(1237, 138828, 129, '9.5 已经给他发送了报价和运费，并制作了产品链接，她说它需要去询问税务问题，今天给他发消息问税务问题如何？还没有回复', 1757057240),
(1238, 139086, 156, '9.4 客户是中间商，已把我问他的问题转问给他客户，还没回', 1757057301),
(1239, 137640, 129, '9.5 报完价格和到门以及到港运费了，这位客户要去查看税务问题；要寻找能帮她解决各种问题的人，昨天询问了是否找到，说找到会给我发信息', 1757057341),
(1240, 137219, 68, '2： 客户说时间很紧，他不需要我们的服务了，放弃', 1757057347),
(1241, 136406, 133, '9.4说打电话问问当地港口，9.5没联系不上客户', 1757057450),
