(1244, 131672, 214, '正在尝试取得联系', 1757058384),
(1245, 138372, 159, '给客发信息、打电话都没回复', 1757058435),
(1246, 138099, 159, '客户想要同时做面条和米饭，给客户推荐盒饭机，现在还没回复', 1757058483),
(1247, 139310, 150, '9.5 客户要5.5米方托，报价9111美金·，客户表示满意价格但还在对比，营销了一下', 1757058501),
(1248, 136856, 159, '客户爽约，打电话发消息都不回复', 1757058524),
(1249, 139138, 161, '客户是中间人，确认完需求已跟客户口头报价25000美金，成本16万含税，客户让发到广西，木箱和运费共计15000元，报价2500美金，总计27500美金。原材料是PE，提供袋子和抽绳的原材料就可以生产抽绳垃圾袋，等反馈', 1757058565),
(1250, 137625, 148, '9.1-9.2在阿里上确定型号\n9.2-9.4详细解答机器问题并报价，答应查询运费\n9.5客户得知价格后想去看机器实体，在等ddp运费', 1757058620),
(1251, 139100, 150, '9.4客户只有邮箱，给客户发送邮件，报了大概价格区间，还没回复', 1757058634),
(1252, 134329, 159, '已给客户报价，现在客户在比价，给客户营销，客户说还没找到合适地方放置机器', 1757058660),
(1253, 139184, 161, '页面价格是3584欧元=29800元，结合页面价格先推印想厂家的蛋糕售卖机但是有wow的品牌和网站，先发中达厂家机器的图片，已留言发了机器的图片，视频。并问一下透明罐外面是否有纸盒包装，另外尺寸和重量分别是多少，等客户上线回复', 1757058669),
(1254, 139083, 150, '9.4客户要煤气的，发送资料后未回，在阿里上面聊', 1757058670),
(1255, 134291, 133, '9.4发了一些催单的话术，客户说有订单会告诉我，像是个中间商', 1757058684),
(1256, 138945, 161, 'WhatsApp还是联系不上客户......', 1757058725),
(1257, 133464, 133, '发的消息客户都不看了', 1757058768),
(1258, 138883, 150, '9.4客户需要高级款的餐车，保持英国的标准加上设备给客户报价22060，客户表示跟在英国买没什么区别，运用一点话术，客户最后表示要与丈夫商量一下\n9.5营销了一下公司还没回复', 1757058803),
(1259, 139326, 127, '给他发信息介绍自己发披萨机图片确认需求，然后还没联系上，发给他的消息还是未读。', 1757058848),
(1260, 139279, 127, '按照现有的蛋白粉机都给他报了个价，然后他选了个中间价位的。但是他稍微嫌有点贵了，但是他也不挑还有两款便宜的。然后运费支付方式，另外加的钱都给他报过了。他的已读回执关了，看不出来最后给他报的价格有没有已读。他要是还嫌贵的话，就劝他买那两款便宜的选一个。', 1757058876),
(1261, 128152, 133, '9.5早上给客户打电话，客户说经济不景气，等五个月后', 1757058893),
(1262, 139272, 127, '客户要5个以上的人在里面工作，然后给他推8m的方托，全车改为美国标准的加上油烟机，排风扇这些的16000美元差不多。他有点想自己安装水电，但是问厂家还是咱们给他装比较好。然后他说他要跟他丈夫商量一下。因为他没开已读回执，所以不知道后面给他发的工厂公司视频看了没有，应该睡觉去了。后面他要是觉得贵的话，再给他推便宜款的。', 1757058904),
(1263, 137960, 148, '9.2 确定型号颜色和定制问题\n9.3解决客户退货反面问题。告知三个港口运费与ddp，客户选择到港\n9.4更改港口\n9.5再次确定定制和总价格，引导阿里付款，为其起草链接，客户说明天付', 1757058950),
(1264, 138864, 150, '9.4客户需要10盘旋转烤炉，让计算一下一台价格与两台价格与运费，口头报价4344美金，按照阶梯式报价给客户报了两台机器，客户要与工作同伴商量', 1757059006),
(1265, 136119, 133, '9.5分享日常天气客户会回，但是没有回产品的事情', 1757059028),
(1266, 139179, 133, '9.5客户说不，问预算没回，电话不接', 1757059096),
(1267, 138431, 150, '9.3客户想买升降机的自动售货机，预算2700美金，给客户推荐便宜款式3300美金，客户说考虑一下\n9.5 用水单进行营销', 1757059121),
(1268, 137608, 150, '9.3客户说在度假，未读', 1757059158),
(1269, 137962, 148, '9.2 确认颜色，等待型号\n9.3确认型号，报价并为其查询ddp\n9.4更改型号并确认内部设备，报价\n9.5等待ddp ，在等客户确认内部设备', 1757059164),
