(1390, 139617, 60, '垃圾询盘', 1757127715),
(1391, 139151, 160, '9.6顾客有一家鲜花店 喜欢6格带冷藏的鲜花售卖机 已经报过CIF价，顾客满意 下周需要去当地咨询许可证和设计的事项', 1757127829),
(1392, 139617, 60, '垃圾询盘', 1757127845),
