(1394, 138674, 160, '9.6顾客是为投资组织投标一个大型灌装机生产线 目前无工厂无员工无预算 找厂家要了一套生产线方案发了过去', 1757128384),
(1395, 138501, 137, '客户不回应', 1757128410),
