(1397, 138857, 137, '明确尺寸需求，在谈相应设备--客户较忙，进度缓慢', 1757128615),
(1398, 138340, 160, '9.6给顾客推荐了更小的机器 但是顾客仍然想要最开始的那一个 阶梯报价并营销大额水单 告诉顾客如果购买3台以上可以给出2200美金的价格', 1757128640),
