(1402, 139250, 137, '价格确定，目前支付方式沟通阶段。', 1757128847),
(1403, 137408, 160, '9.6顾客发送了他们当地的刷卡器 询问了厂家说可以和机器配套使用 营销水单 告知优惠期快到了 询问购买时间 还未回复', 1757128875),
(1404, 139413, 137, '需求明确，重点跟进。', 1757128905),
