(1407, 139465, 137, '经销商客户。需要更改机器-在更换厂家', 1757128964),
(1408, 139305, 129, '9.4 查完运费 他回复我了，给他报完运费加产品价格 他说周一会决定采购事宜，他现在要去开会。', 1757129047),
(1409, 139569, 137, '奔亚马逊价格来（3000美金），营销餐车优势。--推测钱不多', 1757129061),
(1410, 137349, 160, '9.6要6格零食饮料自动售卖机 3种支付方式 发CIF价格，顾客想要在速卖通付款推荐了阿里顾客同意 发送了阿里的链接 就下线了 营销电话都不回复', 1757129196),
(1411, 68235, 137, '从来没有回应-已报价', 1757129244),
(1412, 136762, 160, '9.6  4米方拖 做当地美食 报CIF价 视频通话并发送了营业执照验证公司的真实性 营销水单、工厂视频等，但顾客需要对这项事业再进行考察并且他的生意明年夏天才开始  说明年才会购买', 1757129653),
(1413, 139541, 120, '123546', 1757130608),
(1414, 139115, 160, '预算为5000欧，要求5米方拖2人使用并送货上门，推荐了3米和4米方拖及到港价格，3米CIF价为5075欧接近顾客预算，顾客目前还在比价', 1757130827),
(1415, 139249, 158, '9.5号给客户介绍一些信息，报了价格和运费\n9.6号客户问运输和付款流程，表示有预算，但是计划在11、12月购买机器。目前营销和催款中。', 1757130983),
(1416, 139507, 122, '9.5电话未接。对608感兴趣，已发资料并报价。', 1757131905),
(1417, 139098, 119, '一台披萨机，10寸披萨，室内，32寸显示屏不要冷冻功能，报价9221美元。将披萨机运送到里斯本的费用为 195 美元。（运到葡萄牙Canical，是个小岛，货代只能运到里斯本。）感觉是个有钱人，有 4 间公寓供客户使用，也没给我讲价啥的。就是不确定购买时间。\n9.5分享了德国客户的水单和来访视频，简介营销零食饮料自动售货机。回复说还要调研，看看回报率。', 1757132225),
(1418, 139264, 123, '阿里发消息未读，打电话未接', 1757132361),
(1419, 130166, 82, '9.6发WhatsApp', 1757134675),
(1420, 138819, 120, '9.5预算不多，要的设备比较杂，正在整理资料', 1757135698),
(1421, 138518, 120, '9.5给客户发消息打电话，说了hello就挂了，听不懂英语，联系不上客户', 1757135876),
(1422, 138452, 120, '9.4 客户回复，要100kg/h的去皮机，不要分瓣机。已发机器图片视频，给客户口头报价报运费，已读不回', 1757136003),
(1423, 137767, 120, '9.2 客户说要贷款买', 1757136052),
(1424, 137767, 120, '9.4 营销公司上班视频，已读不回。问了贷款进程', 1757136095),
(1425, 137592, 120, '9.5依旧联系不上', 1757136151),
(1426, 137433, 120, '9.2 价格符合预算但是还要考虑关税，告诉我大概地址，给他查运费', 1757136247),
(1427, 137433, 120, '9.3给客户报了运费，未读未回', 1757136271),
(1428, 137433, 120, '9.5继续联系客户，显示在线过，但是没有已读消息', 1757136329),
(1429, 136719, 120, '8.28 客户想要三合一的机器，问厂家定制要九十多万，给客户说了17万美金，客户吓跑了', 1757136394),
(1430, 134733, 159, '客户已在当地购买', 1757136602),
(1431, 135712, 120, '9.5客户想要灌肠机，还想要能够自动扭结的机器，给客户口头报价，有其他供应商。又说还要斩拌机，给客户口头报价。', 1757138022),
(1432, 135712, 120, '9.6货代不接到苏丹的拼箱，给客户估算了个大概运费，还没回复', 1757138069),
(1433, 139534, 150, '9.5客户表示要十盘电热烤箱报价1810美金，客户发送万能蒸烤箱报价4760美金，客户表示在当地买4000美金也是中国制造，营销加上话术客户表示考虑一下', 1757138424),
(1434, 132756, 35, '9.6 邮件跟进', 1757138648),
(1435, 137647, 127, '9.4回复说不需要了', 1757138685),
(1436, 139731, 165, '9.6已联系上，待确认烤箱类型', 1757138878),
(1437, 139551, 127, '客户要卖盲盒短袖，发了详细的需求，咨询了厂家给他推荐了款式，以及价格，已读不回了，今天发的消息还是未读状态，客户还未上线。', 1757139006),
(1438, 139599, 127, '阿里上介绍自己，发了产品视频，问他具体需求还未读', 1757139046),
(1439, 139634, 127, '不知道客户要什么机器，客户发了自己的微信，加了还没同意。阿里上问他要什么机器，还是未读。', 1757139100),
(1440, 130907, 35, '9.6 添加whatsapp 初步联系', 1757139131),
(1441, 139042, 138, '①9.4-9.5报价＋运费，客户最终对黑色3m圆拖感兴趣，着急购买，给了500折扣期限三天，客户跟海关联系后回复。还要冷却器，不知道是什么，等客户再问再确认。\n②9.6担心关税问题，给出减税方案，给500折扣，等待回复。', 1757139672),
(1442, 139607, 138, '①客户要两个屏幕的，先别推尺寸，按照彩云卷50000的价格报价了9600，还有退税，所以报价低了些，22%利润，等客户回复，阿里联系', 1757139688),
(1443, 139807, 138, '①9.6推荐了中吉，客户选择了冷热23000咖啡，已经报价4600＋500，报运费300，符合客户需求，预计11月收货，等回复。', 1757139733),
(1444, 138720, 138, '①9.3报价＋运费，客户想自己装支付系统，和客户说明了对接型号，客户后来没回复，正在跟进中。\n②9.6说1800价格太贵，给了100折扣，等回复。', 1757139885),
(1445, 138456, 138, '①9.3给客户报价全自动的和运费，客户找了半自动的便宜些，又报价更便宜的半自动棉花糖机，客户没回复。9.4联系客户不回复，打视频拒接告诉我已经在其他家买了。\n②9.4问我有没有其他的售货机，正在联系中', 1757139946),
(1446, 134939, 124, '9.6 初步联系，客户自己做生意，买给自己用，沟通基本信息中，客户已谁', 1757139957),
(1447, 131937, 138, '①8.18给客户报价、报了运费\n②报价后8.19客户不回信息，一直不回复，跟进营销联系中\n③8.18-9.3营销不回复，跟进中', 1757140021),
(1448, 139327, 141, '客户在亚马逊上支付3000美金采购送餐机器人', 1757140324),
(1449, 135212, 123, '客户预算不够，在当地买了二手', 1757140949),
(1450, 124888, 214, '正在尝试跟进', 1757143105),
(1451, 124888, 214, '邮箱地址是错误的', 1757143180),
(1452, 70484, 214, '正在尝试取得联系', 1757143271),
(1453, 139235, 156, '9.4 白天发消息未读，不在线，晚上打电话没打通\n目前仍未联系上客户', 1757145522),
(1454, 139109, 156, '9.5 晚打语音电话，客户拒绝了，信息已读不回，今晚继续打电话', 1757145874),
(1455, 135675, 144, '9.6：发现客户发了动态，给客户发了消息，简单的闲聊了一会，然后客户说他的工厂正在建设，预计9月底收尾，我问那是不是10月份会有希望购买，客户说是的，然后聊到了自己的国家，然后刚好聊到让客户来中国拜访公司，客户说好的，打算持续营销', 1757146574),
(1456, 126802, 144, '9.6：给客户营销了水单，并且再次询问客户什么时候竞标结果出来，客户没有回复', 1757147837),
(1457, 136155, 144, '9.5号给客户制作了付款链接，客户最近一直没有回复消息，给客户打电话也不接，突然消失了一样，今天早上给客户营销了一下水单，没有回复', 1757148329),
(1458, 52498, 214, '正在尝试取得联系', 1757148450),
(1459, 27174, 214, '正在尝试取得联系', 1757148528),
(1460, 138385, 144, '9.6：给客户营销了一下客户来访，并提出可以打视频', 1757148877),
(1461, 83145, 210, '对方邮箱满了收不到邮件', 1757148940),
(1462, 82517, 210, '9.6初次发邮件', 1757148969),
(1463, 25914, 210, '9.6初次发邮件', 1757148985),
(1464, 136365, 144, '9.6：给客户又推荐了类似于清风款式相对便宜的餐车，说如果觉得清风款式比较贵这种可以考虑一下，并说可以的话可以给我发地址，我给客户查运费，客户已读未回', 1757149133),
(1465, 84401, 210, '9.6首次发送邮件', 1757149176),
(1466, 136215, 144, '9.6：给客户说为他申请了折扣，并给客户洗脑，公司有很长时间的出口经验，花高价钱买好产品能用时间长，对他来说很便利，洗脑没有成功，客户没有回复', 1757149783),
(1467, 137625, 148, '9.6告知价格太高，要改成煮鲜面条的机器，还在找产品', 1757149888),
(1468, 133959, 144, '9.6：用水单进行营销，没有回复', 1757150046),
(1469, 137960, 148, '9.6在等朋友信用卡支付', 1757150051),
(1470, 126556, 144, '9.6：问候客户，目前没有回复', 1757150097),
(1471, 139116, 135, '已给客户商定好价格，客户打算在九月份购买，想要飞过来签订合同和付款，具体时间未定，打了视频电话，问他在过来之前可以付个定金，他还是想过来之后再说', 1757150146),
(1472, 125121, 144, '9.6：给客户进行了水单营销，并再次强调目前有折扣可以考虑购买', 1757150735);
INSERT INTO `crm_comment` (`id`, `leads_id`, `user_id`, `reply_msg`, `create_date`) VALUES
(1473, 136773, 180, '9.4 营销 客户回复说他需要时间来考虑 我问客户大概什么时候购买 客户不回复，9.5 跟客户说明之前给他申请的优惠已经截止了，客户不回复    9.6 给客户发了询问的三台机器的报价单，客户已读不回', 1757150750),
(1474, 137982, 146, '9.3客户回复，但问客户地址和购买时间客户都不说，说等他考虑完之后再讨论，', 1757150803),
(1475, 139685, 159, '已给客户报3米、5米价格，正在查运费，客户在设计项目计划，还不确定具体要几米的，客户很有礼貌，意向很好', 1757150877),
(1476, 138415, 146, '9.5客户回复要下周一进行谷歌视频会议讨论', 1757150895),
(1477, 139027, 146, '客户未回复', 1757151020),
(1478, 139111, 146, '9.6凌晨取得联系，说只要单机、但是说两国距离太远，意思是不想买，跟进了但暂未回复', 1757151073),
(1479, 139124, 146, '9.4沟通了客户需要的机器人，以及定制的部分，讨论价格，第二天之后未回复', 1757151210),
(1480, 71334, 144, '9.6：给客户营销了水单，并且强调折扣活动快要结束了', 1757152270),
(1481, 138765, 148, '9.6告知想十月份回到罗马尼亚再购买。以营销尽快购买，还未读', 1757152546),
(1482, 139102, 148, '9.6 为其解释搭配使用的产品（客户无工厂）', 1757152736),
(1483, 139577, 144, '给客户确认了产品，目前还没有报价，而且目前还没有确认烤箱的尺寸，客户没有回复消息，应该去睡觉了，打算今天晚上给客户再确认尺寸，确认之后给客户报价', 1757153144),
(1484, 139687, 148, '9.6确定型号并告知价格，在等ddp', 1757153277),
(1485, 139636, 148, '9.6 发消息未读，会给其打电话', 1757153316),
(1486, 139164, 173, '9.04聊到一半，还没有报价，突然下线。一直没有上线。', 1757153738),
(1487, 138880, 173, '一直处于失联状态，发消息一直没回过', 1757153807),
(1488, 137977, 173, '已经报了价格和运费，并且咨询了运输方式。客户说需要跟小伙伴商量一下，目前正在持续跟进中。', 1757154050),
(1489, 137508, 173, '9.05 客户回消息说，在本地找到了更优惠的产品。不考虑购买。', 1757154120),
(1490, 137009, 173, '客户What\'sapp一直处于失联状态，一直没有回复过消息。视频，电话都尝试过。', 1757154195),
(1491, 136345, 173, '这个客户有比较强的购买意向，刚开始报价完了之后已经聊到付款方式，并且还咨询了港口税费，然后就突然下线了。一直没有上线，后边发的消息也一直没有回。有按时跟进，打视频，打电话。但一直联系不上', 1757154830),
(1492, 136228, 173, '8.27 报价 推荐款式 起草链接。客户说考虑一下\n8.28 客户说有更实惠的了，已经付款。中间转账被银行卡住。我营销客户同意在我们这买，说等钱取出来就在我这里下单\n8.29 客户说卡在银行的钱已将转到中国账户里。但是承诺下周会我这里下单。', 1757155005),
(1493, 135851, 173, '8.26报价 客户说等丈夫回来\n8.27-9.6一直在沟通产品\n目前处于继续跟进状态，因为客户要等丈夫回来。', 1757155075),
(1494, 135378, 173, '这个只有邮件联系方式，但是发的邮件一封没有回过，处于失联状态。', 1757155118),
(1495, 135081, 173, '8.24报价后，让我跟他发报价单后失联\n8.25-9.3号发消息，营销一直没有回过消息。\n9.4号回复说要看设备清单后又失联\n目前发的消息没有回过，后续会继续跟进。', 1757155367),
(1496, 138107, 156, '9.4~6 客户只要自己他发的那款冰淇凌机，只找到类似发客户，已报价，还未回复', 1757155439),
(1497, 134996, 173, '8.24-今天一直在处于沟通细节的状态，客户有预算并且沟通非常的积极。中间有尝试过让客户付定金。但是客户表示要所有东西沟通好了让他满意再下单。', 1757155477),
(1498, 134337, 173, '这个是在速卖通上已经下单的，但是后边报过价后客户表示跟线上价格有差距，并且表示不会接受这个价格，只接受速卖通的价格，并且取消了订单。态度比较强硬。后边发消息没有再回过了。有尝试找过便宜的厂家并且给客户优惠价格，但是客户就是不回。', 1757155704),
(1499, 133939, 173, '8.20报价，之后客户表示要考虑一下\n8.21客户表示她们在比价，并且计划50天后购买，希望给出一个优惠的价格。我给了折中的优惠价格。但是客户不回。\n8.22至今，中间有发过视频，打过电话。但是一直处于不回状态。\n后面会定期持续跟进。', 1757155856),
(1500, 133707, 173, '只有邮箱，发消息一直没有回过。', 1757155938),
(1501, 133592, 173, '已成交', 1757155969),
(1502, 133567, 173, '8.20报过价后，客户就消失了，发消息，打视频，打电话都不接。', 1757156032),
(1503, 133299, 173, '这个只有阿里的联系方式，客户一直没有回复过消息。', 1757156064),
(1504, 133043, 173, '8.18通过邮箱要到what\'sapp，报了价格和运费后消失了两天\n8.20回应称与目前资金参与另外一个项目，解决事情后会回来继续购买。\n8.21-今天，中间发的消息都没有回过，What\'sapp一直处于下线状态。发邮件也没有回过。打视频，打电话都没有接过。', 1757156240),
(1505, 132666, 173, '8.18报完价后对价格没什么异议，但是表示只会在亚马逊上进行购买。我说为他起草链接，并且解释了缘由。但他还是不同意在我这里下单，表示无论如何都要在亚马逊上下单。后边发消息就没有回过了。', 1757156526),
(1506, 138734, 126, '9.30已给客户报最小餐车的价格，\n9.4号告诉客户可以给一些优惠，并且让客户考虑分期付款\n9.05客户询问我分期付款是怎样的（虽然强调只是好奇）\n9.06让客户给地点，给他报了到港的费用，再次问他什么时候分期付款，客户未回复', 1757156617),
(1507, 132625, 173, '8.18报完价后表示会去比价，并且在当周周末告诉我结果。\n但是后面一直联系不上，发消息 ，打视频都不回。', 1757156693),
(1508, 132382, 173, '一直在跟客户沟通细节中，它一直没有表明自己要的是那儿款机器。我就根据他的需求给他推荐，但是一直没有找到他想要的款式。目前还在寻找中。', 1757156766),
(1509, 138989, 126, '9.04给了解客户的需求\n9.05给客户报价，餐车以及一些基础的配置，并且做了报价单\n9.06客户已读不回，猜测客户预算不够，询问客户预算，客户还未回复', 1757156802),
(1510, 132331, 173, '这个是一直没有联系上过。What\'sapp一直没有回过消息。', 1757156896),
(1511, 139845, 147, '三个月左右使用，放在商店里。计划做一个无人便利店。要了披萨机，冰淇淋售货机，以及零食饮料售货机', 1757156914),
(1512, 139446, 126, '9.05已给客户报了基础的餐车和基本配置，询问客户几人操作\n9.06给客户报了3米的餐车，并且报了价，客户未读未回，还给客户解释了怎么运输到美国', 1757156986),
(1513, 139570, 147, '美国的巴西移民，要做牛排与薯条，发给了我标别家的报价，再次基础上做了一个价格稍微低一点的方案。客户聊天积极，需求明确，但是预算没有很多。', 1757157009),
(1514, 139570, 147, '已经制作了详细的报价单', 1757157026),
(1515, 132259, 173, '8.16 报完价后，聊着聊着突然下线\n后边发消息都是已读不回，打视频，打电话都没有接过。', 1757157051),
(1516, 139512, 126, '9.05已给客户在阿里上发消息，询问客户需要制作什么淀粉，客户未读消息', 1757157092),
(1517, 131449, 173, '8.14报过价商家说考虑一下\n8.15 了解了购买的目的\n8.17 客户继续了解了机器的工作原因和一些细节问题\n后边处于失联状态。怎么发消息，打视频都没有回复过。', 1757157228),
(1518, 139641, 126, '9.06客户需要一个1.5吨制冰机，用于海鲜市场保鲜的大冰块，了解客户基本需求，已给客户回消息，还未报价，需要跟客户在沟通一些详细信息，等待客户回消息', 1757157233),
(1519, 128386, 173, '一直联系不上', 1757157570),
(1520, 127825, 173, '8.07日回了我可以给他优惠的消息，我报了价后消失。\n8.08 问我价格是否包含运输，然后失联。\n一直到今天，中间陆陆续续持续跟进，打视频。但一直都没有回复过。', 1757157769),
(1521, 139319, 147, '客户要2*1.2m的餐车，推了圆托，做饮料与咖啡。后续又推了一个尺寸可以满足的小推车', 1757157777),
(1522, 139201, 147, '给客户推了几款，想要小型的，但是功能不全。后面又同意了一个功能齐全的，报完价格后客户没有回复。后续问客户喜欢哪个款式，以及预算的情况。', 1757157840),
(1523, 138057, 147, '客户要四米的方托但是预算不足，给客户营销了工厂，付款，以及发货。保证我们俄品质，按照最低价报了过去，客户说要考虑几天', 1757157958),
(1524, 127824, 173, '这个是超低价引流进来的，8.05报了价后，觉得贵。我又推荐了便宜的款式。但是还是觉得贵，然后就不回消息了\n8.06打视频接了，然后说给优惠价格，已经给了不赔本的最低价，但是还是觉得贵。之后就失联了。', 1757157981),
(1525, 137584, 147, '客户要送餐机器人，打了半小时的视频，但是客户想要知道我们在美国哪个餐馆有售卖，给客户说是隐私，客户后续回复不积极', 1757158098),
(1526, 137431, 147, '营销了客户付款以及好评', 1757158250),
(1527, 137361, 147, '客户说阿联酋很难找到原材料，给客户说可以用新鲜的土豆。确认了型号，以及功能', 1757158318),
(1528, 136395, 147, '给客户打了电话，客户说在等客户的反馈，有结果会让我知道', 1757158373),
(1529, 136366, 147, '产品与报价已发送，可交互回复现在不是工作日，后台给我回复', 1757158421),
(1530, 134860, 147, '联系不上，', 1757158482),
(1531, 139562, 133, '9.6刚刚说周一给回复，和我们合作的几率很大，还在和合伙人商量。', 1757158486),
(1532, 127637, 173, '8.03交流具体产线需求。\n8.04 给他出报价单，和设计方案。\n8.05回复说 等待公司资金审批\n8.12讨论付款方式\n这个客户一直没有具体需求，感觉这条产线只是他的一个想法，没有实施的想法，后续会定期持续跟进。', 1757158494),
(1533, 126390, 173, '7.30问了价后就消失联系不上了', 1757158591),
(1534, 129695, 146, '9.6客户回复在找位置，协调把机器放在哪里，已经跟客户出了主意', 1757170380),
(1535, 139962, 158, '9.7联系上客户，客户需要4米蓝色方拖。已为他报完产品和运费价格。', 1757215208),
(1536, 140001, 144, '给客户推荐了产品和报价，客户比较满意，昨天因为周末货代不上班没法查运费，所以就给客户承诺今天查运费，打算下午给客户提供运费地价格，询问客户购买时间', 1757292015),
(1537, 140276, 163, '9.8  发送餐车，圆拖，方拖图片供客户选择，因时差，等回复', 1757292626),
(1538, 140179, 163, '9.8 发送家用型冻干机，2kg-75kg/次 的产量供客户选择，等回复', 1757292779),
(1539, 140087, 163, '9.7 发送家用型冻干机，2kg-75kg/次 的产量供客户选择，客户选择最小型号2kg ,跟进中\n9.8 发送小型号图片，视频，', 1757292852),
(1540, 139926, 68, '1： 已发工厂视频，已发成品视频，问什么时候收到', 1757293251),
(1541, 137626, 170, '9.8：确定了8.5米气泡清洗机和运费，初始利润率32%。\n        优惠200美金，利润率31%。\n        客户未回复，跟进中。', 1757294012),
(1542, 72120, 82, '9.7已联系上沟通细节报价', 1757294309),
(1543, 137743, 170, '9.2：为客户设计了土豆切割的产线，客户要求在最后加一台真空包装机。\n         选择合适的半自动包装机。\n9.8：未上线，电话未接。', 1757294465),
(1544, 138193, 170, '9.2：确定客户需要咖啡豆研磨咖啡自动售货机，给客户推荐了两台不同价格的机器。\n9.4：客户未回复，打电话被拉黑，途信未接。\n9.5：在阿里上推荐了更便宜的机器，已读未回', 1757294666),
(1545, 138302, 170, '9.2：给客户推荐了3台机器，客户未读未回', 1757294707),
(1546, 138383, 170, '9.3：鸭肠表皮刮肠机没有。   跟进未回。', 1757294764),
(1547, 138783, 170, '9.3：为客户推荐3台机器人，确定客户需要的型号\n9.5：做了商业发票，客户说想等10月1的活动，两周后会来中国。\n9.8：确定优惠折扣为5%，等客户上线', 1757294906),
(1548, 139499, 170, '9.5：确定机器型号和价格。客户有意向发展为供应商购买5台，给折扣。\n         客户要求公司给邀请函。\n9.6：客户要求先发货3台货到付款。发送公司明细打视频，客户坚持货到付款。', 1757295110),
(1549, 139611, 170, '9.6：报价客户想要的型号，客户想要网站700美元价格的机器。\n         解释机制，推荐最便宜机器，客户已读不回。', 1757295263),
(1550, 140055, 170, '9.7：披萨机太贵，最后选择了最便宜的售货机。\n         客户说有200到500美金，说服先付意向金，抓住国庆优惠。\n         客户回复没钱，存够1000美金要到明年一月，明年国庆一定找我买。', 1757295456),
(1551, 139690, 68, '2： 已做阿里付款链接，等待付款', 1757295692),
(1552, 126434, 146, '9.8回复已经购买，付款截图给发过来了', 1757296823),
(1553, 133164, 133, '9.8客户现在在法国，两周后回墨西哥，还在了解需要什么认证的阶段', 1757297493),
(1554, 139564, 133, '9.8约定打视频但是没打成，发的消息客户也不看，打途信电话不接', 1757297558),
(1555, 139716, 133, '9.7报价客户需要的纸币器（含找零）和刷卡器以及机器的价格一共2120美元，客户说太贵了，发消息不回了。', 1757297661),
(1556, 139960, 133, '9.7客户想看看我们都有哪种类型的以及各自的价格，做了一个pdf给客户，客户选择了一款。\n9.8客户说支付模块要纸币硬币和刷卡，已报价。机器3256USD,支付模块1043USD', 1757297953),
(1557, 139643, 165, '4m餐车做酒吧带冰箱和冰柜运到西班牙，CIF马拉加16900美元，春季才准备订购，长期跟进', 1757298044),
(1558, 140020, 165, '灌装海水，待确认细节', 1757298089),
(1559, 139313, 165, '9.8产能太小，已报半自动11710美金', 1757298132),
(1560, 139683, 133, '客户自己本身有两台机器，想要扩展业务，但是说什么我们能提供融资吗，没太明白，问客户是什么意思，没回。问问了明姐，明姐说他的意思应该是能贷款吗，给他推了速卖通的分期付款，等回复中。', 1757298357),
(1561, 139533, 133, '给客户营销，说一些话术，客户说给他一点时间考虑，语气有点不耐烦的感觉。', 1757298423),
(1562, 139731, 165, '9.8    12层热风旋转炉，待确认供能方式', 1757298447),
(1563, 136406, 133, '9.8问他周末过的好吗，他说good，谈正事不回了', 1757298483),
(1564, 137176, 133, '9.8说担心骗局，发了李桢客户来访的照片和公司的营业执照（已读），询问客户我们放不方便打视频（未读）。', 1757298576),
(1565, 139882, 163, '9.6 询盘，客户需要冻干水果，给客户发送10平方，20平方供客户选择，并报价。', 1757298592),
(1566, 140098, 174, '跟客户发了信息客户未读未回\n早上又发，客户仍然未读未回。', 1757301725),
(1567, 139283, 165, '已报中机的小鱼，CIF墨西哥城5385美金，客户想通过阿里支付，已制作付款链接，看过客户阿里数据并分析后，客户可能是在比价', 1757301802),
(1568, 139813, 174, '上周给客户发了资料，客户未读未回。\n今天早上早早问候了客户新的一周愉快，客户回复了，客户想要小型的旋转烤炉。', 1757301989),
(1569, 139977, 161, '已建档，客户有了解阿里巴巴平台，客户想要的餐车款式新和盛厂家可以做，已报价12500美金。后面又推荐5米方拖-按照威凯的成本报价9200美金，后面了解到客户的朋友已经买了餐车，主动提到DOT和进口税费是55%，客户明天跟代理人沟通后回复，跟客户确认一下付款方式', 1757303412),
(1570, 140258, 161, '已建档并留言，客户没有在线', 1757304252),
(1571, 140424, 24, '骗子，发的安装包', 1757304614),
(1572, 140382, 156, '9.8 客户目前只是了解产品阶段，计划明年购买', 1757304620),
(1573, 139888, 163, '9.6 发送餐车方拖，圆拖，客户要5米方拖，要炸锅，空调，冰箱，烤箱，要周一联系\n9.8 客户自己的生意，发送小设备细节，报价，计算运费，跟进中', 1757308383),
(1574, 139864, 163, '9.6 给客户发送一条半自动生产线视频，询问客户要生产线还是仅仅要单机，客户没有回复\n9.8 新的一天开始上班，想给客户建立连接，准备下午他们上班时间打电话', 1757308627),
(1575, 139820, 163, '9.6 给客户建立连接，需要30kg/h 半自动产量，发送视频，没有生产车间\n9.8 在产生连接，客户也需要包装机，客户第一次投资，跟进中', 1757308793),
(1576, 139270, 163, '9.8 在次给客户发送消息，发送办公室视频', 1757308850),
(1577, 138670, 119, '9.3中国人，公司总部在上海。想要半圆型鲜花自动售货机，发送报价，未读未回。\n9.4又要寿司机，报价3696，刷卡器300美金。发送报价单\n9.8要披萨机的报价单，给她发送了之前整理的披萨机的目录。说有点贵。回复话术，未回。感觉像是在收集信息。', 1757311938),
(1578, 138871, 119, '一台披萨机，10寸披萨，室内，32寸显示屏不要冷冻功能，报价9221美元。将披萨机运送到里斯本的费用为 195 美元。（运到葡萄牙Canical，是个小岛，货代只能运到里斯本。）感觉是个有钱人，有 4 间公寓供客户使用，也没给我讲价啥的。就是不确定购买时间。\n9.5分享了德国客户的水单和来访视频，简介营销零食饮料自动售货机。回复说还要调研，看看回报率。\n9.8发送公司概况视频', 1757312023),
(1579, 139098, 119, '上面写错人了\n很冷淡，问什么都说看价格才能决定，所以就推了最便宜的一款彩云卷家的9078美金。未回。\n9.8发送公司概况视频', 1757313095),
(1580, 139336, 119, '很主意节省税款的事，回复可以之后，发送照片问喜欢哪一款机器未回。\n9.8发送公司概况视频', 1757313532),
(1581, 139410, 119, '三轮车：1,400 美元\n运费：435 美元\n总计：1,835 美元\n一月份使用\n9.8问最实惠的价格，给他100美元的折扣，前提是三天内付款。未回复，应该在思考。', 1757313713),
(1582, 139820, 163, '9.8 给客户发送报价单', 1757314005),
(1583, 139472, 119, '发送邮件，未回。\n9.6再次发送邮件，未回', 1757314130),
(1584, 139947, 119, '想要带动力的餐车，劝说之后对方拖感兴趣。加一个冰箱，感觉预算在4400美金左右。\n推荐3.5米便宜款方拖，报价5114美金。\n9.8又提到想要带动力的，回复话术之后，发送公司概况视频营销。', 1757315184),
(1585, 139577, 144, '客户问有没有NSF认证，我跟客户说有，但其实可能没有，跟主管沟通说客户要了认证再说，先答应下来，客户知道有了NSF认证比较惊喜，然后目前客户说他正在确认面包房的尺寸，并说他会确认并给我发送尺寸，还有墨西哥饼的前端机器客户比较满意', 1757315532),
(1586, 140223, 140, '0908客户1-2个月内做出决定，目前在寻找放置机器的位置', 1757315722),
(1587, 139260, 144, '9.8：给客户重新发送了一份报价，包含DDP价格，比之前的价格少了有800、900美元，给客户说在这已经是最大的诚意了，而且收到了老板的压力，目前客户一直没有读消息，没有回复', 1757315746),
(1588, 71647, 82, '9.8已发WhatsApp不回信息', 1757315778),
(1589, 138854, 144, '9.8：给客户发送了客户来访照片，和水单进行营销，客户已读但是没有回复，问客户目前有什么想法也没有回复', 1757315843),
(1590, 138477, 144, '9.6：收到了客户的回信，客户想要清风款，但是没有提供有几个人使用餐车，没有确认尺寸，还问能不能送到墨西哥，我回复说可以，并给客户列出了问题，比如说预算是多少、地址、有几个人在餐车工作、想要做什么生意等等，目前没有回复', 1757315994),
