(1725, 137319, 122, '9.5跟进客户，客户说有点贵。推荐了更小的型号。报价3m的餐车带设备及运费。\n9.6添加新设备。9.7客户嫌贵问空车的价格，已报价。\n9.8发送标配空车的视频和介绍，客户未读。', 1757382809),
