(1731, 52632, 164, '问基本信息 最后几条信息未送达 发邮件 电话打过去语音信箱\n回复邮件，1-2个人工作。主要用途是制作混合饮料 报价基础配置 信息未送达 邮件再次跟进 问冰箱的价格，报价，然后还是没有回复，\n再次跟进没有送达，被拉黑', 1757384780),
