(1950, 139607, 138, '①9.9问了客户的需求，客户是采购商，实际客户洪都拉斯，是合作过的客户，所以属于潜在客户。\n客户一天的产量是4000L，想用来用来做鲜奶，液体酸奶，冰激淋，奶酪等成品，一条线加上其他设备可以实现，但是加上冰激淋后，成本会达到三位数。客户的实际需求并不明确，对包装和每个成品的产量也没有概念，和厂家沟通过后，决定先报价一条做鲜奶、酸奶、奶酪的生产线，后期根据客户的需求再进行更改。', 1757467937),
