(1989, 140130, 125, '客户需求很明确，要求美国标准，各个电气设备都要符合UL标准\n9.7晚明确客户需求\n9.8给客户制作详细的报价单，并告诉客户我们的餐车符合她们当地的标准\n晚上，客户再次强调设备要符合UL标准，污水箱要比净水箱多15%\n9.9按照需求给客户再次更新报价单，客户已读不回\n9.10晚上电话联系，了解客户的担忧', 1757477209),
(1990, 141015, 164, '圣地亚哥，做咖啡，自己使用，4米，木色款，报价CIF 确定生产时间，亚马逊上写2周，想要两周收到，解释，需要跟合伙人商量，明天联系', 1757477277),
