(1993, 139809, 125, '了解客户的需求后，给客户报了总的价格\n2.5 米餐车价格：4189 美元 3+1 水槽：600 美元 冰箱：600 美元 不锈钢工作台：100 美元 炉灶：280 美元 总价：4189 美元+600 美元+100 美元+280 美元=5769 美元\n9.10号了解到客户预算不够，跟客户提了先付30%的定金，剩下的钱可以分期付，客户说可以，给客户要邮箱起草订单，客户还未回复。', 1757477615),
