(2013, 132439, 122, '8.17电话简单确认需求，给客户发详细视频参考。\n8.18发带设备的详细报价。\n8.20客户修改设备，更新报价。并确认了港口和运费。\n8.21营销未回。\n8.23电话更改了配置，更新了带抽烟和不带抽烟两份报价\n8.25营销，客户说三周后购买\n8.26营销，给当月付款折扣，催定金。客户说10.17来中国。催付款先生产。客户考虑。\n8.28客户问先付多少定金，确定不带抽烟，9.12左右付款。让客户先付10%预留折扣，并更新了发票。客户说考虑考虑。\n8.29电话跟客户确认能否付款，客户说九月付。\n9.2更新发票，标明了新的折扣和定金。打视频未接。\n9.3电话未接。\n9.4跟进客户说在忙，需要更多的时间。营销客户反馈。\n9.5发货营销，电话未接。客户说还在忙，需要和代理确认我们的报价，代理确认后就支付定金。可能需要一天时间。\n9.8跟进未回。\n9.10电话未接。', 1757489852),
