(2084, 141265, 127, '9.10要创业盘个商店放自动售卖机，不确定要买什么样的，把所有的做了个大概的目录给他看，不包含价格，他说要和家人商量一下买什么', 1757552070),
(2085, 141299, 127, '9.10客户要做杂粮饼干小米饼干，几百千克的都想看看就给他做了一个中间产量的看看价格什么的，如果价格太贵就买小的，报价单已经发送了，正在给他找更多完整生产线的视频。昨天让他看报价不知道看了没，还没发表意见。', 1757552319),
(2086, 140704, 120, '9.10 客户要求付款链接和我承诺的完全一样，并且把详细参数加进PI里，改完后客户说要去比价', 1757552448),
(2087, 140230, 127, '9.10给我发信息说因为位置没定下来所以一直没有联系我，现在要先把棉花糖机放的位置确定了在买棉花糖机，问他大概什么时候能处理好说自己也不确定。', 1757552459),
(2088, 140098, 174, '跟客户打途信未通，wp消息未读未回', 1757552494),
(2089, 139718, 174, '昨晚跟客户发了水单营销，客户已读未回', 1757552604),
(2090, 139718, 174, '九月八号的时候早上给客户问了早上好，跟客户沟通不知道它在说什么，反正一直可以联系到\n十号晚上昨晚跟客户发了水单营销，客户已读未回', 1757552644),
(2091, 139813, 174, '八号跟客户发了公司培训视频，十号跟客户发了刘阿密的水单，“今天我收到了美国客户的定金，您最近似乎非常忙碌，什么时候可以跟您一起合作”\n仍然已读未回。\n分析原因是客户应该是想小机器没必要从中国买', 1757552802),
(2092, 139261, 174, '周一晚上跟客户催单客户严厉拒绝，周二的时候就只能跟客户聊家常了，客户家住西西里岛，我让他发一些照片，同事周二晚上我也发了公司客户来访和水单营销。\n客户周三晚上给我发了西西里岛的照片，我一顿夸。\n但是并没有要到客户付款', 1757552990),
(2093, 141383, 153, '已发送名片，询问客户需求', 1757553247),
(2094, 140856, 153, '9.11已反馈运费，客户对运费很满意，发送完整的报价单后客户开始回复不积极，后续追问客户说等一会，打视频接通一分钟客户在接待他的客户就断了，等客户回复中', 1757553414),
(2095, 140446, 153, '9.10已发送产品资料 询问客户需求，等客户回复中', 1757553468),
(2096, 139271, 174, '九月五号 客户是墨西哥歌手，搞乐队的，很酷，有购买欲望', 1757553473),
(2097, 139271, 174, '九月六号客户说自己担心关税，我立马帮忙查了关税，但是第二天她又决定在本地购买', 1757553525),
(2098, 139689, 153, '营销公司视频，并说明我们的机器目前可以制作10寸和12寸的披萨问客户需要哪个尺寸', 1757553528),
(2099, 139271, 174, '九月八号，早上客户给我发了好人卡，并表示要有限从当地购买。\n帮客户点明我们的优势：成本更低、可以根据您的需要生产定制、质量更优；当地都是二手，且不一定符合您的要求，送您女儿的礼物我不希望您买到劣质的产品。\n我还发了美国客户的水单，和一些发货视频，客户开始已读不回', 1757553570),
(2100, 139271, 174, '昨晚给客户发了刘阿密的营销水单，“这是我美国客户的餐车定金，我希望您可以重新考虑您的餐车。。。”\n客户：谢谢你的关注，考虑到时间，距离等因素，我还是觉得在本地购买更加划算', 1757553580),
(2101, 140884, 120, '9.11 询问客户进展，给客户推荐便宜款', 1757553710),
(2102, 139573, 153, '打视频未接通，营销公司视频，询问客户是有哪方面的顾虑，等客户回复中', 1757553733),
(2103, 139484, 153, '营销公司视频，客户未回复', 1757553764),
(2104, 140707, 120, '9.10 给客户发机器操作视频和图片', 1757553824),
(2105, 138799, 153, '客户想在亚马逊支付，话术运用得不太好，客户有些应激，准备打视频沟通', 1757553860),
(2106, 140946, 150, '9.10打折了300美金，还是嫌贵，营销没回', 1757553861),
(2107, 140707, 120, '9.11 给客户发机器工作流程和时间', 1757553888),
(2108, 140678, 123, '介绍机器，确认需求，报价；客户需要确认关税和运费；营销客户来访', 1757554324),
(2109, 138852, 174, '周一打wp电话未通，发团队照片未读，\n途信也打不通\n属于报价后消失的类型', 1757554481),
(2110, 140987, 130, '2025.9.10 客户回复消息说想要视频和内部细节以及价格是否包含税和运费到他的港口。我回复明天上班给他发。\n2025.9.11 将视频发给客户以及一些参数，发送的是清风款的。询问客户有多少人将在车上工作以便推荐尺寸。', 1757554484),
(2111, 139084, 174, '始终联系不到客户', 1757554523),
(2112, 131215, 174, '客户已经明确不会从我们这里采购', 1757554571),
(2113, 137227, 153, '报价单客户已读，问需要增加设备吗，客户不回复', 1757554663),
(2114, 139674, 120, '9.11 给客户发发货图片', 1757554674),
(2115, 138936, 174, '昨晚用刘阿密的水单营销：\n“亲爱的朋友，最近过的怎么样，您最近似乎非常忙碌。昨天我收到了美国客户的披萨机定金”\n客户：最近确实非常忙，想去参观圣保罗的披萨机，我说要征得客户同意，并营销了李桢的披萨机。', 1757554746),
(2116, 141097, 137, '询问要求，客户提到需要一一确认饼干所有细节-', 1757554828),
(2117, 137866, 174, '昨晚用刘阿密的水单营销：\n“亲爱的朋友，最近过的怎么样，您最近似乎非常忙碌。昨天我收到了美国客户的披萨机定金”\n客户未读未回', 1757554879),
(2118, 141050, 137, '客户与搭档商量讨论', 1757554899),
(2119, 137228, 153, '营销阅兵折扣活动和公司食品，问客户需要什么形状的饼干，等待客户回复', 1757554996),
(2120, 138783, 170, '9.9：客户想要产品目录，发送后等待回复。\n9.10：客户说在考虑，忙完回', 1757555137),
(2121, 141313, 157, '9.10 晚上打电话沟通 对方要一台炸薯条机、棉花糖机和拉面自动售货机 想要知道报价和运费', 1757555150),
(2122, 136424, 174, '昨天客户跟我说他问了当局，关税高达60%，我问是否还有可能考虑我们，他说会的：\n接下来给他营销一些帮他省钱的技巧。展现专业', 1757555256),
(2123, 136696, 153, '客户是采购，对对出口文件和餐车资质比较看重，表明如果机器质量可以愿意成为经销商，但是询的是AI生成的餐车图，目前只问到领秀恒和可以做，成本32000人民币，还没给客户报价\n8.30已给客户报价，同时在询运费\n9.5客户之前反馈当地7500美金能买到带抽油烟机和烤架的餐车，报价从7250裸车降到了7000带抽油烟机和烤架，已发送报价单，客户说需要老板意见老板去学习了，一有消息后会通知我\n9.11分别营销阅兵折扣活动和运费上涨，目前客户还没回复', 1757555365),
(2124, 141051, 174, '昨晚跟客户通了电话，客户要求明确，第一次购买餐车。', 1757555389),
(2125, 141052, 124, '9.10 打电话，客户未接通', 1757555455),
(2126, 140989, 124, '9.10客户为公司购买，沟通机器基本要求', 1757555526),
