(2327, 139676, 164, 'whatsapp和途信未打通 营销公司工厂 客户案例', 1757640944),
(2328, 140183, 180, '9.8 先给客户发了邮件 之后在Whatsapp上与客户解释了产品价格与店铺价格不符，客户在速卖通后台取消了订单\n给客户推荐了YG-P7X和YG-A625i两款型号 客户询问了YG-A625i的价格 \n给客户口头报价（包含到港口运费）客户又询问到达港口需要多长时间 之后客户没回复\n9.9 继续营销跟进 客户没回复', 1757642573),
(2329, 141568, 125, '10号给客户发邮件，发送电加热炒锅的视频图片，并向客户确认他的需求；\n11号客户回复邮件，说计划本周购买，客户给我发了一个链接，点开显示是危险网站', 1757642901),
(2330, 141451, 125, '10号给客户发送了邮件，包括机器图片和参数，并向客户明确需求，客户未回复', 1757642957),
(2331, 140214, 180, '9.8 与客户发了我们的房子的尺寸、类型，客户没上线 。\n晚上用途信给客户打了两个电话 客户没接，之后用Whatsapp给客户\n打电话，客户挂断\n9.9 与运营说明情况，让运营联系客户 \n晚上给客户发消息，客户没上线', 1757642959),
(2332, 141345, 125, '10和客户取得联系，明确客户想要的款式，客户想做披萨和烤肉生意，给客户报了餐车的价格以及设备的价格。（3米圆拖的价格是4413美元）客户应该是为公司购买的，想增加霓虹灯，上面定制公司的名字；\n11号给客户报了到勒阿弗尔港的运输费用为 787 美元。又给客户发送霓虹灯的种类供客户选择。', 1757643255),
(2333, 141342, 125, '12号跟客户取得联系后，给客户报3米方拖的价格6777美元，客户想要在亚马逊上付款，告诉客户亚马逊不支持付款，引导客户线下TT付款，客户不信任，坚持走平台，告诉客户可以走平台，消除客户疑虑，发送公司视频。接着给客户报了到墨西哥哈利斯科州瓜达拉哈拉港的运费为 723 美元。总价为 6777 美元 + 723 美元 = 7500 美元，客户还未上线，还未回复', 1757643566),
(2334, 134447, 130, '2025.9.10 客户已读不回\n2025.9.12 给客户发信息营销公司', 1757644100),
(2335, 134254, 130, '2025.9.9 给客户发信息自我介绍，并发送了公司餐车的图片。询问了2.5*2米的方拖运送到沙特阿拉伯利雅得的费用。想要折扣。我询问他还要其他的配置吗，没有回复。\n2025.9.11.给客户发消息，并发送水单。没有回复', 1757644481),
(2336, 133401, 130, '2025.9.9 给客户发信息自我介绍，没有回复。\n2025.9.10 给客户打电话，没接，发信息 没有回复', 1757644639),
