(2355, 140999, 127, '推荐福匠家的全自动油炸机，性价比比较高。在考虑范围内，问我还有没有其他的，9.11推连续性的，还没回复', 1757648510),
(2356, 141738, 165, '已留言，暂未联系上', 1757648548),
(2357, 127280, 130, '大都是已读不回的，刚开始说不信任我。然后我提出打电话，她说她不会讲英语。后来就给他发送产品图片视频，国外来访的客户，水单。没有回复', 1757648568),
