(2363, 137911, 125, '联系不上客户了', 1757648779),
(2364, 141299, 127, '9.11给他发了详细的生产视频，说自己正要去出差，和团队商量一下9.12号回复我,给我发他们要做的饼干的图片', 1757648785),
(2365, 141807, 161, '已建档，客户发的邮件，发现客户有WhatsApp，先在这里跟客户留言了，发了披萨机的图片和视频，问下要10寸还是12 寸', 1757649643),
(2366, 141892, 161, '已建档，客户没有WhatsApp，打算发邮件并结合打途信', 1757649670),
(2367, 140223, 140, '0911客户回复说再整理一些物流问题，又问了与支付相关的问题，说很快会再次联系', 1757650265),
(2368, 141613, 160, '顾客需要一辆5米的方拖 已经根据顾客要求推荐厨房设备并发送报价单 营销 顾客比较满意 目前正在和她的丈夫商讨', 1757650652),
(2369, 141082, 160, '顾客不愿意支付运费也不愿意补差价 另一位同事没有联系上顾客', 1757650716),
