(2375, 138452, 120, '9.8 营销水单未读未回', 1757654693),
(2376, 138452, 120, '9.12 营销发货图片，问客户还在犹豫价格吗，已读不回', 1757654731),
(2377, 141577, 153, '已发送名片和介绍，今日营销公司视频并询问客户需求，等回复中', 1757656385),
(2378, 140581, 139, '9月12日向客户展示公司图片，介绍公司背景，询问预算，客户已读不回', 1757656525),
(2379, 138338, 125, '客户是代理商，帮他的客户购买的，他的客户有7条产线，想扩大产线，生产桃酥和曲奇两种饼干；\n客户只想要两台成型机，给客户做了报价单；\n客户告诉我他的客户想要空运，为他查询了空运的费用将近一万美金，给客户报了；\n9.12号得知客户觉得空运费用太高，但客户9月底就想收到机器，所以才坚持走空运；客户说他的客户不理他了，劝说代理商劝他的客户尽快购买，能为他缩短生产周期，加急，代理商说会给他的客户沟通，会告诉我结果。', 1757657087),
(2380, 140583, 136, '根据客户询问的产品发送机器资料，营销，报价，再次联系客户时客户说另一个中国朋友报价1000美元，解释其中原因，及存在隐患，客户说会再考虑', 1757657530),
(2381, 138003, 125, '9.4和客户取得联系，客户想要那款爆款餐车，明确客户的需求后给客户报价，客户没有说价格不行；给客户送车牌作为送给他妻子的礼物进行催单。\n9.5继续跟客户联系，客户说周六不适合推销；用餐车的生产和运输周期催促客户下单。客户说计划在定居点中心附近开冰激凌店，但目前在建构阶段，所以今年不打算购买。后续继续因生产周期和运输周期来催促，客户已读不回；\n9.12继续跟进', 1757657810),
(2382, 140744, 125, '9.11给客户提意向金的事，让客户现付200美金的意向金保持现在的这个价格，因为快到中国的春节了，运输费用和餐车的价格都会上涨，以此来催促客户付意向金；\n9.12客户告诉我自己一点钱都没有，这几天还要修车子，可能会欠钱之类的，给客户说了好久，客户就是没钱，说下个月贷款下来了再买。', 1757658734),
(2383, 140708, 125, '9.11客户回我消息了，让我给他发送所有的披萨机型号和价格，给客户发送了好几款，客户说会和他的老板商量；\n9.12询问客户给老板商量的怎么样，并发送水单营销，客户已读不回，今天打算打电话沟通。', 1757658977),
(2384, 140678, 123, '制作了报价单，客户已读未读', 1757659474),
(2385, 141340, 125, '9.10给客户发送消息，发送一些餐车的图片和视频，客户未回复；\n9.12凌晨客户回复我了，明确客户想要哪款餐车后，给客户报价，4米清风款餐车。客户坚持要在亚马逊付款，引导客户线下TT支付，客户坚决不，告诉客户可以通过第三方平台，客户说很好。随后转移话题，讨论餐车本身，给客户报价6547美元，到迈阿密的运费是739美元，总计7196美元。问是否符合预算，客户说符合，接着要了邮箱。客户又询问平台名，给客户发了阿里巴巴的水单并介绍阿里，客户知道这个平台。给客户拍公司，客户说期待与我们公司合作，问客户还有什么问题，客户说没有。为了建立信任，跟客户约定打视频，客户同意了，但没接，后面就已读不回了。\n9.12继续跟进', 1757659560),
(2386, 140574, 136, '初次联系到客户，询问需求，发送视频图片信息，后客户无回复，继续跟进中', 1757661687),
(2387, 140272, 136, '发消息营销，打电话，联系不上客户', 1757661730),
(2388, 139215, 136, '沟通饼干机器细节，了解需求，催付款，客户已经发送水单', 1757661769),
(2389, 139154, 136, '阿里巴巴后台发送消息，询问信息，客户未读', 1757661825),
(2390, 138968, 136, '与客户沟通好机器细节与需求，催付款中，客户说需要等待资金', 1757661883),
(2391, 138968, 136, '以上一条跟进记录有误，此客户预算不足，只有1500美金，速卖通不支持加纳国家分期付款', 1757661984),
(2392, 138533, 136, '与客户沟通需求，发送机器视频信息报价等，后客户不回复，打电话，客户语言不通，继续营销，几天后客户发送语音，捕捉信息大概是想要手动款，担心关税问题，会继续联系厂家找到相应款式，并告诉客户关税问题的应对办法', 1757662184),
(2393, 62368, 130, '客户已经购买了餐车。从阿里巴巴平台', 1757662257),
