(2399, 135697, 136, '联系客户，了解需求，推荐并营销产品，服务等，报价，客户不回复，后客户询问运费，想送到门口，货代说不行，除非整柜，后做报价单和PI给客户，客户无回复，打电话不接，发消息询问是机器还是价格问题，不回复，打电话不接，隔几天继续跟进', 1757663689),
