(2413, 139577, 144, '9.12：给客户制作了报价单，客户对价格很满意，问了一些售后和怎样付款的问题，问客户什么时候购买，客户说他需要把机器的尺寸发给同伴看一下，觉得客户的意向比较大打算重点跟进', 1757665406),
