(2422, 141653, 141, '客户询问了 两款的价格， 运费， 说要核算其他费用， 下个月计划采购', 1757666157),
(2423, 141000, 131, '1.9.10接到询盘。与客户确认客户购买的机器事冰淇淋机。客户有自己的农场餐厅，有经济实力。给客户推荐了彩云卷家的冰淇淋机，客户反应一般。\n2.又给客户推荐了七云家的冰淇淋机，价格相对彩云卷便宜，客户反应可以。\n3.客户向政府提交了售卖申请，等找好放置的地方后，就决定购买，继续营销。', 1757666165),
(2424, 139260, 144, '9.12：给客户报了价格，客户说想要明年2月份来参观公司，并向我询问了总共的DDP费用，还有生产时间，感觉是一个持久战', 1757666251),
