(2701, 138785, 129, '客户在亚马逊下单后，得知没有现货，取消了订单。', 1757924479),
(2702, 142091, 146, '9.13给客户报了餐车的价格和设备价格，客户问付款方式，说了需要通过其他方式付款，客户害怕是诈骗，但通过话术和公司展示，逐渐消除了客户的疑虑，9.15为客户报了运费，客户还没读，到时候看看客户反应', 1757924601),
(2703, 142330, 160, '3米圆拖 计划下周购买 已发报价单 但顾客港口很偏 运费很贵 顾客目前在和合作伙伴商讨颜色等事宜 但有从亚马逊购买的意向', 1757924682),
(2704, 141934, 129, '报完价后没有回复', 1757924688),
(2705, 141884, 129, '暂未取得联系', 1757924701),
(2706, 141704, 129, '这个客户是个中间商，目前正在跟他确认具体的方案', 1757924738),
(2707, 140967, 124, '9.12说同事会中文，要联系我，一直没联系，建议给我号码，没给\n9.14打招呼，分享周末生活\n9.15询问觉得价格怎么样，点赞价格，没有回复。进一步询问能否做发票', 1757924752),
(2708, 142053, 124, '9.12 打招呼介绍自己，发送机器照片，问为谁买                                                                                                                                                                                                  9.13客户为自己买，沟通基本需求，报价7200美元 ，报运费750美元        \n9.14分享周末生活                                                                                                                                                      9.15打招呼，运输需要10-15天，询问客户报价是否在预算之内，已读不回', 1757924877),
(2709, 142640, 122, '9.15客户需求：3mm,6mm,8mm厚度，电压220V,50hz, 直径8cm 11cm 13cm, 已报价，客户提交报价给老板看', 1757925162),
(2710, 141052, 124, '9.14 分享周末生活照片，客户未读', 1757925344),
(2711, 141052, 124, '9.14 分享周末生活照片，客户未读', 1757925346),
(2712, 142021, 146, '9.12给客户报了参数和价格，然后客户问了一些技术问题。9.13客户又问了一个技术问题。9.14给客户回复并进行营销，已读未回，9.15发送了个视频吸引客户回了消息，继续跟进', 1757925821),
(2713, 142269, 164, '要燃气款，报出厂价格，发名片，要到门价格，想要看当地的机器\n报价到门', 1757926077),
(2714, 141740, 146, '9.15又跟客户要地址，客户说还没有', 1757926291),
(2715, 140989, 124, '9.12 话术给出选择询问为什么没有回复消息\n9.14打招呼，分享周末生活照片\n9.15提出视频通话参观公司，视频电话被拒绝', 1757926860),
(2716, 142154, 119, '9.13发送基本信息', 1757927194),
(2717, 142610, 119, '9.15发送基本信息，想要散酒自动售货机。', 1757927215),
(2718, 142653, 119, '9.15发送基本信息。客户一上来就说想来中国看厂。一台披萨机9221美金，运送到非洲杜阿拉1050美金。一台薯条机10879美金。但是客户说预算就6000美金。答应客户这周内购买2%的折扣。今天购买3%的折扣。客户又说我的竞争对手价格比我低。回应话术并询问别的供应商的参数，已读未回。', 1757927229),
(2719, 142333, 119, '发送一封邮件', 1757927252),
(2720, 139636, 148, '9.15 客户说在筹集资金，并找地方放置机器', 1757928004),
(2721, 142490, 124, '9.15客户问网站价格低，话术解释并提出100美元的折扣安抚', 1757928359),
(2722, 137648, 125, '9.15号给客户营销外国客户来访照片，客户还未回复', 1757929103),
(2723, 141646, 146, '9.14发送消息未回复，9.15又跟客户营销了一下客户来访', 1757930087),
(2724, 127178, 138, '①客户在忙，一直没消息，发邮件，打电话打不通\n②8.5发邮件，客户说最近很忙，等他闲下来\n③8.11发邮件，客户不感兴趣，说不要再联系她。', 1757931674),
(2725, 66514, 138, '不需要，不买', 1757931748),
(2726, 137873, 138, '不读不上线', 1757931980),
(2727, 137795, 138, '不读不上线', 1757931996),
(2728, 142036, 159, '已确定客户处理产品的信息，正在为客户找相似的机器', 1757934000),
(2729, 141352, 159, '已联系上客户，客户想要做移动租赁婚礼生意，已报价，在等待客户回复', 1757934088),
(2730, 141080, 159, '中间商客户又找了新的客户，美妆自动售卖机，已报价', 1757934128),
(2731, 140697, 159, '已给客户发送便宜的包装机，客户已读未回，还在考虑', 1757934168),
(2732, 127096, 138, '①报价后不回复，运费4000USD太贵，持续营销，不喜欢信息轰炸\n②8.9已经在其他公司购买了，低价挽回，客户和伙伴商量\n③8.9-9.3以后不回信息，陆续营销中\n④9.16在别的地方购买了', 1757934464),
(2733, 141730, 157, '9.13 问了最小型号的价格 报价后未回复\n9.14-15 发消息未回，打电话没打通', 1757935112),
(2734, 136173, 153, '客户是公司采购，对出口文件和餐车资质比较看重，表明如果机器质量可以愿意成为经销商，但是询的是AI生成的餐车图，目前只问到领秀恒和可以做，成本32000人民币，还没给客户报价\n8.30已给客户报价，同时在询运费\n9.5客户之前反馈当地7500美金能买到带抽油烟机和烤架的餐车，报价从7250裸车降到了7000带抽油烟机和烤架，已发送报价单，客户说需要老板意见老板去学习了，一有消息后会通知我\n9.11营销阅兵折扣活动和运费上涨，目前客户还没回复\n9.15营销水单，询问什么时候订购', 1757935236),
(2735, 136173, 153, '上面更错了\n客户想要一台咖啡类餐车，已推荐并发送给客户报价单，客户想要3D效果图和平面图，引导客户交定金，客户说要和搭档商量一下。\n8.30已营销巴基斯坦客户和日常问候，情人节资料\n9.15营销水单，询问什么时候订购', 1757935269),
(2736, 136696, 153, '9.15营销水单，询问什么时候订购', 1757935293),
(2737, 68217, 138, '①6.18推荐了三款棉花糖机，发了价格图，不回复，营销，分享生活，不回复。加了WA，\n②7.22回复了，客户应该是中间商，还有3个库存，\n③9.16持续营销中，只读不回。', 1757935395),
(2738, 69374, 138, '①报价后不怎么回信息。7.21联系上，还要木薯脱皮机，正在报价中。客户要很多机器，需求不清晰，\n②7.24给客户推荐先买腰果和木薯脱壳机，给了500折扣，做了报价单，客户说和工厂反馈，正在等消息。\n③没钱，预算不够，2000预算让买腰果脱壳，不买，要贵的木薯脱皮。\n④9.1偶尔营销，已读不回，近期不买，9.12推荐了便宜的木薯脱皮机，不回信息，跟进中', 1757935415),
(2739, 71320, 138, '①客户问了棉花糖机，披萨机，又问了冰激淋机，爆米花机，他对爆米花机的价格感兴趣，价低，预计26年购买，一有钱就买，持续营销。\n②7.24推荐客户买棉花糖和爆米花机，给了500折扣，客户说没钱，营销客户付500意向金，正在等回复。\n③8.13给折扣不为所动，一定要等年底存钱买，现在没钱\n④8.13-9，16后不回信息，偶尔营销', 1757935437),
(2740, 141018, 159, '打电话、视频、发信息，客户都未回复，还未与客户取得联系', 1757935464),
(2741, 72001, 138, '①客户是采购商，7.24确认好了客户需要分级的种类，非常多，和厂家沟通后给客户推荐报价，\n②7.26价格说定了（福煦最小款），不回信息，难以推进\n③7.30回国了，客户现在不需要，偶尔营销\n④9.4又来中国，要来看厂，打了视频，问什么时候来，不回复，9.12又去其他国家了，对色选机兴趣不大了，偶尔营销', 1757935527),
(2742, 72051, 138, '①客户要50kg/h的，给客户推荐了两款小型豆腐机，视频，从阿里转邮件转WA，报价了，等待回复。\n②要面条机。豆卷机，需求不明确，年底来中国后买\n③无法推进，又提到售货机，问了拉面机，说不符合规定\n④9.16说26年4月之后买，偶尔跟进', 1757935548),
(2743, 124700, 138, '①加了WA，客户预算大概6500USD,喜欢雪铁龙，担心各种西班牙的法规，客户最近很忙，\n②7.30-8.21一直不回复，说出去旅游了\n③8.21发了西班牙客户的付款截图回复了，跟进营销还是不怎么回复\n④9.13-14又问方拖和其他款式，问价格，联系中', 1757935570),
(2744, 125047, 138, '①客户要一台，想要纯牛奶的，找到厂家了，\n②客户7.27后没上线，发邮件，发信息，一直联系不上，偶尔营销\n③7.27-9.16客户没有再上线，联系不上，偶尔营销。', 1757935586),
(2745, 126457, 138, '①7.30-8.9推荐了很多款式，终于有客户喜欢的了，已经报价，报运费，满足了客户的定制需求，交定金/设计费/意向金都不交\n②8.10-8.17等客户买的其他机器到了规划预算，一边营销\n③8.17客户问方拖，报价，一边营销一边聊生活\n④8.17-26，客户找到1500的圆拖，没有竞争优势推了方拖，客户不喜欢，又要做计划，营销中\n⑤8.28-9.6客户大概率选择便宜商家，并没有竞争优势，近期没有计划购买，偶尔跟进', 1757935603),
(2746, 141331, 159, '客户正在找他想要的饼干模具，给客户发了饼干的制作视频、模具，客户还未回复', 1757935610),
(2747, 127096, 138, '①报价后不回复，运费4000USD太贵，持续营销，不喜欢信息轰炸\n②8.9已经在其他公司购买了，低价挽回，客户和伙伴商量\n③8.9-9.3以后不回信息，陆续营销中\n④9.16在别的地方购买了', 1757935620),
(2748, 127674, 138, '①打电话不接，发消息不读，联系不上\n②8.8接了电话，让她看WA，没后续，打电话不能正常沟通\n③联系不上', 1757935640),
(2749, 127959, 138, '①发了报价单，发票，\n②客户购购买车位后，再付款\n③8.11后不怎么回信息，持续营销中，8.17回复还是担心各种认证，解释没有用，8.17后一直不回信息，已读不回，9.16不回信息', 1757935659),
(2750, 128671, 138, '①只有几百美元，想买清风餐车，8.8准备贷款，正在等贷款情况\n②8.28客户说只能贷款1000美元，推荐便宜方拖，不回信息，持续营销中\n③9.2依旧没钱，要跟朋友借钱，坚持营销中', 1757935676),
(2751, 129123, 138, '①已报价，问预算、需求不说，不喜欢信息轰炸\n②8.8后不回信息，单钩', 1757935699),
(2752, 130320, 138, '①一直联系不上', 1757935719),
(2753, 130139, 138, '①发了两封邮件，客户要炒股、计算彩票、送餐机器人，推荐了送餐机器人\n②8.12第三封信报了价，等回复，8.15发邮件询问进度\n③8.20客户回信觉得价格贵，他觉得机器人价格200美元合适，我解释了机器人的高科技性和价格的合理性，不回复\n④9.2发邮件关心近况、说明价格在任何地方都绝对买不到机器人，没回复，没消息', 1757935733),
(2754, 130531, 138, '①8.11按照客户需求推荐了一款人型＋有拍照功能的机器人，客户执着要一摸一样的人形机器人，需要定制，厂家不做一台\n②8.13-8.26给客户推荐了其他人型机器人，发送视频，客户不喜欢，一直不回复\n③8.11-9.16一直不回信息，问需求不回复', 1757935756),
(2755, 131676, 138, '①阿里转邮件，8.15报价参数价格，一直没回复\n②9.2发邮件问进度，什么时候买，等回复\n③9.11客户发邮件问豆腐机详情，解答了，等回复。', 1757935783),
(2756, 131097, 138, '①8.13-18给客户报价，披萨机比较贵，艾玩-彩云卷-鑫之源，10500-8500，一直找便宜厂家，客户预算7500，定金/意向金都不交，一直说价格高\n②8.15后不回信息，打电话不接，营销中\n③9.10推荐了一款披萨机8500，利润很低，巨大折扣，还是不回信息，一直读，就是不回复。9.16仍然在等客户回复，最近不读不回', 1757935846),
(2757, 131760, 138, '①8.15报价了饮料零食自动售卖机，客户在安排\n②8.20客户说自己很忙，持续跟进中\n③8.20-9.15后不回信息，陆续营销中\n④9.16说有三台现货，三天付款可以预留，等回复', 1757935863),
(2758, 131904, 138, '①4米餐车报价和运费，给客户搭配了内饰，客户在规划，\n②8.19给客户更改了内饰方案，客户一直说要存钱再买，\n③8.28定金意向金都要不到，继续营销，\n④9.9客户还是担心加拿大的法律问题，能退款再买，然后不回复，后续会着重这一点营销。', 1757935879),
(2759, 131937, 138, '①8.18给客户报价、报了运费\n②报价后，8.19-9.16客户一直不回信息，偶尔营销联系', 1757935895),
(2760, 132145, 138, '①8.16客户准备明年买，问客户喜欢的款式\n②8.20-21客户对网站价格与实际价格不符有些生气，3-4人推荐了5米的餐车，客户想自己选择长度，\n③8.21-9.16一直不回复，还没确认餐车情况，跟进联系中，营销不回复', 1757935911),
(2761, 132356, 138, '①8.16-17给客户报价4.5米黑色常规款方拖，解答客户细节\n②8.18报运费和总价，8.20客户了解了规格价格后不回信息\n③9.1-16客户不读不回，近期没有购买需求', 1757935942),
(2762, 132427, 138, '①8.17客户预算只有1000，冰激淋机6000多，预算不够，\n②8.20又问折叠房，准备做投资，没钱\n③8.20根据预算推荐了零食售货机，客户没钱，跟进中\n④8.25-9.16没钱，不接视频，营销不回复', 1757935962),
(2763, 133321, 138, '①客户是采购商，韩国客户豆腐脑的产量8000-12000kg/h，包装产量，8000-12000kg/h，包装容量400g\n304材质的，不含税的价格，木箱费，货期，地址浙江，产量太大，很多工厂不做。\n②8.30有一家让提供工厂图，不回复，9.12-16问工厂面积不回复，', 1757935975),
(2764, 133504, 138, '①客户有确切的需求，且了解该产品，给客户报价回复了一系列问题\n②8.22客户说其他家价格更低更专业，不回信息，跟进中，之后一直不回信息\n③9.16联系不上，不读不回，单钩', 1757935986),
(2765, 133168, 138, '①客户挺专业，8.19报过价了，客户说9-10月要来中国，看过披萨机再买，意大利要求严格\n②坚持意大利要求严格，营销中，不聊产品，不回复\n③8.22后不回信息,跟进中，到9.10一直说要来中国，11月来，不说机器，一直说忙。', 1757936008),
(2766, 133825, 138, '①等待客户确认酸奶线具体细节，9.6本周之前\n②9.6-16客户不急购买酸奶生产线，没有说出自己的需求，还在跟进中', 1757936020),
(2767, 134348, 138, '①8.22报价包运费，给50折扣，发付款链接，客户没付款\n②8.22后客户不回信息，打电话不接，偶尔营销联系中\n③8.22-9.16不再回复信息，打视频拒接', 1757936031),
(2768, 135700, 138, '①8.25-27报了披萨机、棉花糖机的价格，发了视频\n②8.29客户说家里有人去世，九月联系\n③9.5问了几个问题，专业回复了，9.5-16不读不回信息，营销询问中', 1757936043),
(2769, 135926, 138, '①8.26给客户报了100L的希腊酸奶生产线，\n②8.27按照客户的要求更改了部分信息，客户说价格还可以，需要先获得当地的许可证，\n③8.28给客户折扣想要来定金/意向金，客户没读，一直跟进中\n④9.5回复许可证需要一个月，有了许可证再下单，减少跟进频率，9.13祝周末快乐', 1757936070),
(2770, 137342, 138, '①8.29-9.1客户是购买新手，产量非常小，但是要全自动的，报了全自动产量最小最便宜的，已报价报运费，客户说还可以，正在问客户什么时候买\n②9.2客户又问面条机，客户有回复，客户不说是哪种面条机，是说太小，询问不回信息，打电话现在也不接。\n③9.4推荐客户先买一个蛋清分离机，不回信息，\n④9.12说先买蛋清分离机，做了发票和链接，客户不回信息，今天再打视频联系，', 1757936108),
(2771, 137225, 138, '①8.30-9.1确认客户需求，9.1发送两种方案\n②9.3客户说和朋友讨论，\n③9.9改方案，要500L液体酸奶。9.10报价，一万美元预算，不太够，尽力报了低价设备，等待客户和朋友确认信息，', 1757936118),
(2772, 137394, 138, '①客户不确定需求，9.2报价了最低产量的机器，等回复，\n②9.6-10还没回复，打电话不接，推荐其他不回，9.6-16一直不回信息，偶尔营销', 1757936127),
(2773, 137794, 138, '①9.1-2客户两个人工作，要四米餐车，报价润如吉家最便宜款方拖，客户说还可以，给客户搭了设备\n②9.2-16一直营销中，信任问题还可以，但是只说购买时会通知我，继续营销', 1757936140),
(2774, 137944, 138, '①9.1-9.2客户帮公司购买，已经报价，等回复\n②9.11要折扣，原计划公司审批后两个月内购买，回复近几天购买优惠200，客户和老板商量去了\n③9.16还没有进度，我强调了再给一周的优惠时间，继续跟进中', 1757936155),
(2775, 138262, 138, '①9.2客户为公司采购，报最低价格3300的迎宾机器人，客户说有点超预算，上报公司，给我回复。\n②9.4说自己还有另一个机器，到了回复我，9.4-9.16一直不回信息，9.16打电话拒接，联系中', 1757936165),
(2776, 138456, 138, '①9.3给客户报价全自动的和运费，客户找了半自动的便宜些，又报价更便宜的半自动棉花糖机，客户没回复。9.4联系客户不回复，打视频拒接告诉我已经在其他家买了。\n②9.4问我有没有其他的售货机，正在联系中，9.4-16一直不回信息，成单钩，', 1757936177),
(2777, 138720, 138, '①9.3报价＋运费，客户想自己装支付系统，和客户说明了对接型号，客户后来没回复，正在跟进中。 \n②9.6说1800价格太贵，给了100折扣，9.6-15不回信息。 \n③9.16说不需要香水售货机了，考虑别的机器，正在看是否能转化成其他的产品', 1757936190),
(2778, 138905, 138, '①9.4报价报运费，客户对价格不太敏感，也不问机器如何运行操作，可能有经验。很在意售后问题，提出赠送配件和24小时在线服务，不回复。\n②9.4-9.16不回信息，9.16直接报了基本最低价格8600的披萨机，等回复。', 1757936202),
(2779, 139042, 138, '①9.4-9.5报价＋运费，客户最终对黑色3m圆拖感兴趣，着急购买，给了500折扣期限三天，客户跟海关联系后回复。还要冷却器，不知道是什么，等客户再问再确认。\n②9.6担心关税问题，给出减税方案，给500折扣，等待回复。\n③9.7说来中国，又说最近很忙，正在考虑餐车，9.7-15不回信息\n④9.16说不需要了，挽回中，免费升级餐车，等待回复。', 1757936217),
(2780, 139607, 138, '①客户要两个屏幕的，按照彩云卷50000的价格报价了8600，阿里WA联系。\n②9.9重新阶梯式报价，又给50优惠，8550包括付款方式、免费送波兰语言，客户要买两台，准备付款，又问到顶棚，然后不回信息，\n③9.10-16不回信息，不读不回，正在联系中。', 1757936231),
(2781, 139686, 138, '①9.8客户要2.5米的圆拖卖饮料，需要冰箱和冰柜，加上运费共5000价格，9.8-16报价后不回复，营销中', 1757936247),
(2782, 142545, 157, '9.15 客户自己用，美容美发，不需要内部设备，只需要空车加电力系统。\n        沟通需求，报了3米圆拖价格，并为其查询最近港口运费，对方又发送了3个异型餐车，想知道他们的价格，待沟通', 1757936261),
(2783, 139807, 138, '①9.6推荐了中吉，客户选择了冷热23000咖啡，已经报价4600＋500，报运费300，符合客户需求，客户预计11月收货。\n②11月收货，现在购买刚好，客户在对比中，9.7-9.16不回信息。', 1757936271),
(2784, 140120, 138, '①9.8确认了客户的需求，推荐了50kg的腰果脱壳机，发了参数，总价2200美元，当天要阿里巴巴的付款链接，然后不回信息，一直联系中。\n②9.8-9.16不回信息，一直营销中。', 1757936283),
(2785, 140931, 138, '①9.9问了客户的需求，客户是采购商，实际客户洪都拉斯，是合作过的客户，所以属于潜在客户。\n客户一天的产量是4000L，想用来用来做鲜奶，液体酸奶，冰激淋，奶酪等成品，一条线加上其他设备可以实现，但是加上冰激淋后，成本会达到三位数。客户的实际需求并不明确，对包装和每个成品的产量也没有概念，和厂家沟通过后，决定先报价一条做2T鲜奶、1T酸奶、1T奶酪的生产线，提供多种包装选择，后期根据客户的需求再进行更改。\n\n②9.10给客户发了报价单，客户自己是中间商，所以一直怀疑我们也是，各种侧面验证我们是否是工厂。9.16客户那边需要和股东讨论，周期会比较长，需要耐心等待。', 1757936294),
(2786, 141405, 138, '①客户要5米的或者更长的，有自己的设计图纸，要设备，但是觉得价格贵，不在线，等回复\n②9.15说找到更便宜的了，没有竞争优势，正在问客户其他供应商多少钱，客户不回复。', 1757936305),
(2787, 141921, 138, '阿里不读信息', 1757936312),
(2788, 142474, 138, '①9.13加上WA,客户要包装炼乳，正在问细节，回复不积极', 1757936322),
(2789, 68429, 138, '联系不上', 1757936457),
(2790, 68500, 138, '联系不上', 1757936469),
(2791, 142473, 164, '网上价格低，解释，想要融资', 1757936529),
(2792, 130894, 138, '要拍照摄像机器人，可能是博主，阿里发信息已读不回，9.16不读不回', 1757936582),
(2793, 140066, 164, '报价3米圆拖，普通电配', 1757936698),
(2794, 136065, 138, '①8.31让销售人员联系我，已读不回\n②9.5以后已读不回，试着联系中', 1757936920),
(2795, 142916, 161, '已建档并初步留言', 1757936940),
(2796, 142555, 157, '发送了基本信息，待回复（9.15）', 1757936955),
(2797, 142961, 161, 'WhatsApp已通话，客户说保加利亚语，WhatsApp已留言，问下客户要什么？', 1757937078),
(2798, 142478, 164, '民宿，发基本信息 电话未打通，发邮件', 1757938242),
(2799, 142679, 164, '36个询盘都是食品相关类，有水果脱水设备，灌装设备\n发基本信息  电话未打通', 1757939228),
(2800, 142071, 164, '营销美国新订单', 1757939479),
(2801, 142555, 157, '9.15晚上 对方问了价格运费以及保修服务，解答之后说明天为他查询运费。', 1757982170),
(2802, 142543, 157, '9.15 被拉黑 晚上打途信电话没打通', 1757982224);
INSERT INTO `crm_comment` (`id`, `leads_id`, `user_id`, `reply_msg`, `create_date`) VALUES
(2803, 142457, 157, '9.15 发送了报价，已读但未回（后续继续跟进营销）', 1757982319),
(2804, 142406, 157, '9.15晚上 发送了报价单和PI，并进行营销，对方说现在还需要考察，有购买计划再联系我。（继续营销跟进）', 1757982396),
(2805, 141900, 157, '9.15 查询了运费，发送了新的报价单，对方表示超预算，调整生产方案', 1757982617),
(2806, 141725, 157, '9.14 发送基本消息未回复\n9.15 进行营销未回（下午打视频尝试联系）', 1757983170),
(2807, 143107, 120, '9.16 给客户发了两种饼干的视频，问客户想做什么样的饼干', 1757983316),
(2808, 141313, 157, '9.15 发送了新的报价，但是未读未回（继续跟进）', 1757983360),
(2809, 142995, 120, '9.15 已给客户留言', 1757983367),
(2810, 141291, 116, '报价后 客户还挺满意，保持跟进中', 1757983488),
(2811, 137397, 157, '9.11 打电话 未打通 9.15 发消息营销未回 9.16打电话未打通', 1757983515),
(2812, 137100, 157, '9.11 打电话拒接   9.15 发送营销，已读未回', 1757983588),
(2813, 141570, 116, '报价后  没有回复  会继续跟进', 1757983740),
(2814, 142004, 116, '在评估价格  已发送披萨机和薯条机的报价  等待客户反馈', 1757983787),
(2815, 137099, 157, '8.30-8.31 沟通基本需求，想要黑色方拖，卖汉堡薯条，问了支付方式，想在亚马逊购买，解释引导之后，对方已读不回\n9.1-9.9 每天问候加营销 已读不回\n9.13 营销 已读未回 打电话不接\n9.15 营销 未读未回', 1757983816),
(2816, 142312, 120, '9.15 给客户打电话，客户说是她老婆买的，说在WhatsApp上沟通', 1757983898),
(2817, 142293, 120, '9.15 客户想要定制30格的，已口头报价，说要跟搭档商量一下', 1757983958),
(2818, 136641, 157, '9.15 发消息未回\n9.16 打视频未接通', 1757983976),
(2819, 134941, 157, '9.10 营销，未读未回  9.11 问进展未读未回，打电话没接  9.14 发消息未回 9.15 营销加发消息，已读未回，打电话拒接 说由于公司内部原因，购买计划暂时停止，有新的变动会再跟我联系。（继续跟进）', 1757984204),
(2820, 143134, 146, '9.16已经发送视频，等待回复', 1757984419),
(2821, 143074, 146, '9.16WhatsApp发了消息，也发送了封邮件，暂未回复。', 1757984487),
(2822, 143008, 146, '9.15晚上发了消息，打了电话没回，9.16早上发现已读，然后发消息跟进，未回', 1757984524),
(2823, 142466, 146, '9.15晚上回答了一些问题，客户要9.17号进行视频通话，看机器人，意向很高。', 1757984579),
(2824, 142752, 121, '9.16号的询盘，接到后就跟客户打了招呼 发了图片，暂时还没有回复', 1757985035),
(2825, 142618, 121, '9.15的询盘，在阿里上打招呼还没有读', 1757985106),
(2826, 141766, 120, '9.16 给客户发邮件', 1757985202),
(2827, 142335, 170, '9.15：客户的预算是1500，推荐了客户预算内的售货机。\n           客户是几内亚的，CIF运费要990美元，客户不回复了', 1757985205),
(2828, 142638, 124, '9.16 途信电话，客户未接', 1757985901),
(2829, 142490, 124, '9.16 打招呼，要客户地址，提出包运费，暂时未读', 1757985966),
(2830, 142248, 144, '9.16:客户表示会在2026.1月购买，目前已经报过了价格和运费，总共550美元，打算一周营销一次持续营销', 1757986225),
(2831, 142967, 165, '客户要做移动理发店，已报价，待客户检查', 1757986325),
(2832, 142053, 124, '9.16 询问客户没有回复原因，价格，运费还是机器', 1757986376),
(2833, 141738, 165, '推荐了魔兽款，客户问了所有的价格，报价后已读未回', 1757986440),
(2834, 139643, 165, '客户反馈做了市场调研后感觉市场不好，项目暂停了', 1757986559),
(2835, 143142, 139, '向客户打招呼并发送名片，询问客户想要的款式图片，客户暂时没有回复', 1757986701),
(2836, 140581, 139, '向客户表示可以选择小尺寸的餐车，价格相对便宜很多，客户未回复', 1757986789),
(2837, 140001, 144, '9.16：客户说目前因为债务人不还债，所以没有钱，问什么时候购买，他说12 月或 1 月购买', 1757986970),
(2838, 141158, 165, '跟进未联系上', 1757987098),
(2839, 142588, 165, '已读未回，已跟进', 1757987289),
(2840, 69293, 130, '被客户拉黑', 1757987493),
(2841, 143019, 157, '9.16 沟通基本需求，要最小型的自动售货机，配备三种支付方式，表示明天可以支付一部分的定金。  现在给她制作报价单和PI，晚上发给她，催付款。', 1757990105),
(2842, 143022, 157, '9.16 发了基本消息，暂未回复', 1757990140),
(2843, 141734, 141, '问客户的需求 不回应， 他说仅仅对餐车感兴趣。', 1757990190),
(2844, 142287, 141, '客户要4台 ，分别发法国2台 摩洛哥2台，报CIF 价格。15号也给客户折扣价。跟进客户。', 1757990299),
(2845, 142676, 141, '阿根廷客户饼干机是客户自己手工做的饼干 现要扩大生产， 买小型饼干机。 但客户的图案比较复杂， 机器很难做出来', 1757990390),
(2846, 142694, 141, '客户的电话是虚拟号，目前未打通。运营后台已发信息等客户反馈', 1757990435),
(2847, 142934, 141, '客户不急采购，再了解餐车阶段', 1757990461),
(2848, 140020, 165, '需要申请批准，预计12月之前', 1757990916),
(2849, 140947, 141, '客户找到便宜的机器。 给客户折扣价格 同意一周内付款。', 1757991003),
(2850, 140014, 141, '客户使用亚马逊一个金融分期软件 支付，给客户讲，TT付款也可以分期。 但客户坚持使用这个APP分期支付。', 1757991130),
(2851, 138685, 141, '客户的预算是2000欧元，买冰淇淋机 预算不足', 1757991209),
(2852, 142573, 163, '9.16 打电话未接，继续跟进', 1757991217),
(2853, 138272, 141, '客户租到了 场地， 近期会采购。', 1757991241),
(2854, 143221, 71, '在广州有代理', 1757992319),
(2855, 142985, 127, '已发自我介绍和视频作为示例。问他要罐装具体的产品尺寸、图片。还未回复', 1757992694),
(2856, 143136, 127, '已发送介绍，整理好了要发的产品资料，等他睡醒给他发', 1757992776),
