(3001, 142374, 146, '9.17凌晨打电话客户挂断，说明天给我回复。', 1758040900),
(3002, 142292, 146, '9.17凌晨打电话没有打通', 1758041032),
(3003, 142057, 146, '9.17又发送了邮件', 1758041447),
(3004, 143183, 141, '客户要5m长的餐车， 给客户报价后，客户拿亚马逊网页4000美金 做对比， 告诉客户是2.5m 3m 的餐车价格。 因为价格 客户犹豫了', 1758069818),
(3005, 140581, 139, '向客户发送问候，询问对价格是否有顾虑，客户未读', 1758069985),
(3006, 143142, 139, '客户回复了想要的餐车款式和图片，询问了客户想要的尺寸和用途，客户暂时没有回复', 1758070059),
(3007, 143257, 139, '尝试给客户打电话，客户未接，但消息已读。继续向客户发送关于订单的信息，客户暂时没有回复。', 1758070146),
(3008, 142658, 174, '客户身份是手工烘焙店主，但是对奎宏的４００型曲奇饼干机感兴趣，昨天报了价格，说明了参数，客户暂时未读。\n目前对客户的需求已经很明确了，目前要做的就是用我们现代化的饼干机的高效和精美营销客户，激发客户的购买欲望，然后探测出客户的价格接受范围。', 1758070365),
(3009, 143505, 174, '第一时间跟客户发了信息，等待客户回应', 1758070450),
(3010, 143197, 133, '9.16客户说现在没有那么多钱，提了先付30%定金帮他保留价钱，等她付到60%的时候可以安排生产。或者直接支付60%为他安排生产。', 1758070496),
(3011, 142312, 120, '9.17 口头报运费', 1758070681),
(3012, 143124, 134, '9.16 电话没人接 9.17再次尝试', 1758070702),
(3013, 143562, 134, '已跟进 客户不知道要什么产品 等待客户回复', 1758070773),
(3014, 143474, 172, '加了whatsapp发信息还没读', 1758071133),
(3015, 143259, 172, '阿里已读不回', 1758071167),
(3016, 126590, 172, '信息一直没读', 1758071197),
(3017, 142555, 157, '9.16 做了报价单，对方说有一家自动售卖公司，想先订购一台试试水，之后可能回购，但在价格方面比较犹豫。（继续跟进营销）', 1758071495),
(3018, 143314, 174, '本来跟客户推了升降和吊钩两种机器，客户很坚定的选择了升降。\n**客户需求**\n５－１０台自动售货机\n想要高配置，所有的支付方式都想要\n要带冷冻设备，即使价格较高？\n中吉报价（上下左右升降）：单柜２.８万，双柜４.３万\n报价情况：单舱价格（购买少于三套）：3,810 英镑;\n3 至 7 个单位：3,500 英镑;\n7 个或更多单位：定制订单。\n双柜价格（购买少于三台）：\n5,850 英镑;3 至 6 个单位：5,407 英镑;\n6 个或更多单位：定制订单。\n并跟客户讲了，如果有突发情况我们可以派工程师到现场（中吉）', 1758072271),
(3019, 143390, 140, '客户有披萨店，需要德语英语波兰语可以满足，已给客户报机器的价格', 1758072380),
(3020, 143082, 121, '报了价格后，客户询问运费，应该是对货值能接受，今天给客户寻了运费，到港总运费是2132美元，报给客户后，客户说有点高就不回消息了。', 1758072487),
(3021, 142492, 140, '与客户进行食品通话后，客户想要两台机器只要刷卡机，9.16与厂家确认客户需在当地购买刷卡机，厂家预留接口，客户目前在咨询刷卡机', 1758072532),
(3022, 143129, 174, '客户名片已经给我了。\n客户是做特氟龙管道，阀门的公司，有一定经济实力，值得跟进。\n印度客户就是喜欢麻烦人，这次一定要耐得住性子\n用福匠的机器报了价格，客户是有觉得贵的，我还要再学习产品知识', 1758072621),
(3023, 143350, 140, '客户预算3-4K英镑，只要白色 给客户推荐了三款机器，已发送照片和视频。对其中的两款感兴趣，问了价格和运费', 1758072651),
(3024, 143501, 122, '9.17打电话确认需求，不要内部设备，不要工作台，只要电系统和3+1水槽。已报价。客户说确认后联系。', 1758072685),
(3025, 143053, 140, '给客户发去了披萨机的报价，询问客户售卖披萨的尺寸，客户地址不明确，问了是要送货到港还是到门，目前还没回复', 1758072742),
(3026, 143024, 140, '暂未联系上', 1758072754),
(3027, 142344, 174, '在十五号联系到了客户，客户偏爱清风款，报了三米８５００美元的价格', 1758072822),
(3028, 142344, 174, '跟客户报了价格客户并没有回复，目前需要做的就是了解清楚是哪里不对，是价格贵了还是产品不符合他的要求，还是其他顾虑。\n今天早上再次跟进。', 1758072833),
(3029, 142878, 68, '3 ： 9.17 打视频，已确定型号，以营销图片和视频，要向老板汇报，准备发邮件', 1758072865),
(3030, 142752, 121, '今天又尝试打了电话，还是没有接通', 1758072970),
(3031, 142074, 174, '周一上班的时候，客户因为我没有第一时间告知他支付模组需要另外付款，他很生气\n发了报价，发了产品，客户不信任我了。', 1758073045),
(3032, 142074, 174, '客户已经说了不要再发信息给他了，但是他又是真实客户，且有返单潜力。有些纠结怎么做。', 1758073054),
(3033, 141922, 174, '客户说话根本听不懂，他家徒四壁想让我们送他', 1758073090),
(3034, 141812, 174, '搜到了客户的领英账号，教育领域，有一定购买能力，今天整理资料再跟进一步。', 1758073348),
(3035, 143345, 71, '已报价', 1758073418),
(3036, 142114, 157, '9.15 发送消息，进行报价，客户说考虑考虑\n9.16跟进，暂未回复（继续跟进）', 1758073551),
(3037, 141373, 174, '客户一直联系不到，要不试着用其他方式，比如找找他的邮箱什么的', 1758073569),
(3038, 141051, 174, '周末跟客户通了电话，客户说不再需要我们的产品', 1758073866),
(3039, 143066, 58, '9.15没有what s app 已经发送邮件问了客户乙烯二基础问题再开始给客户推荐型号以及报价', 1758073913),
(3040, 141333, 174, '客户当天就说自己已经对我们薯条产线不感兴趣，问他有其他需要没他就不回了，已经跟鹏飞哥反馈', 1758073942),
(3041, 143126, 58, '已经添加whats app 问大概情况发送基础资料 9.16回复三室40ft 带有斜坡屋顶和露台+发送报价', 1758074079),
(3042, 141958, 82, '9.12 发信息未读 9.16 17打电话未接', 1758074207),
(3043, 143133, 144, '客户想要夏威夷果脱壳机，但是他还想要捣碎，不知道要捣碎成什么样子，打算今天下午在跟一下，还有11月想要来中国', 1758074278),
(3044, 143254, 58, '25.9.16 发送基础资料  17号一直未回复', 1758074423),
(3045, 143352, 144, '9.16:客户购买的可能不止一台，客户有很多问题，并且想要产品目录，打算做一个，还有一些问题今天下午解答', 1758074923),
(3046, 138796, 174, '客户说自己是经销商，所以订单没法着急，我又给发了一些公司实力，证书的资料，客户说会跟他的客户再次反馈。', 1758075278),
(3047, 139084, 174, '今天把阿里客户又通了一遍，这个客户没邮箱也没电话，木法', 1758075337),
(3048, 142974, 143, '9.16 做了报价单客户觉得和网站价格相差较大 已读不回 持续跟进中', 1758075551),
(3049, 141323, 143, '9.17 客户在比价 持续营销中', 1758075589),
(3050, 142926, 134, '9.18营销 发货，9.22再次联系客户', 1758075648),
(3051, 140252, 143, '9.11给客户做了简单的方案和报价 客户已读不回', 1758075849),
(3052, 135340, 174, '始终未读未回', 1758075989),
(3053, 142920, 144, '给客户发消息，一直没有回复，昨天给客户打了两个电话，客户不会说英语没有办法沟通，说了Whatsapp，但感觉客户没有懂，然后给客户发了短信，没有回，Whatsapp也没有回', 1758075992),
(3054, 132310, 174, '都给客户最低价格了，他还是不买，营销公司产品力', 1758076053),
(3055, 140179, 163, '9.10 9.12.9.15  9.17 发送营销，联系不上', 1758076088),
(3056, 140087, 163, '中间一直联系，客户助理不积极，客户说他在考虑是否买，还在跟进', 1758076173),
(3057, 141386, 119, '9.12说打算在当地购买，询问原因。说是港口费用太高，总价超过5000美元。\n9.13营销，感觉没多大用\n9.17回复已经在当地购买过了，让发点餐车照片学习一下，未回。', 1758076288),
(3058, 143104, 137, '与客户确认细节中，客户发完消息就下线。', 1758076432),
(3059, 143211, 137, '客户是确认自动售货机款式，价格运费已报4万多，相关细节信息都已邮件发送，客户在与团队商量。目前打算购买两台。', 1758076553),
(3060, 139882, 163, '中间商，发送报价单，明年夏天买', 1758076594),
(3061, 128239, 174, '这个客户跟这么久，竟然发现当时建档跟李薇冲突，我改了电话建的档，之前操作好离谱啊，但这是个真是客户，他正在等银行。', 1758076654),
(3062, 143493, 58, '9.17发送基础资料无回复', 1758076792),
(3063, 124364, 144, '9.17：客户还是不确定什么时候购买，说下星期会联系我，我打算不重点问客户什么时候想要购买的时间了，就打算持续营销', 1758077084),
