(3065, 141957, 134, '推荐客户购买样机', 1758077167),
(3066, 139260, 144, '9.17：客户说2月份会安排伙伴来中国，打算到时候购买机器，意向挺高的吗，打算持续营销', 1758077262),
(3067, 126556, 144, '9.17：营销了客户来访，客户已读', 1758077452),
(3068, 138263, 40, '9.17：客户是中间商，为他的客户购买，还在对比型号选择便宜的机器', 1758078370),
(3069, 140412, 90, '联系不上', 1758078490),
(3070, 140776, 90, '要25*20 的房子，但没有图纸，没有具体规划', 1758078549),
(3071, 140778, 90, '联系不上', 1758078607),
(3072, 140815, 90, '预算不够，想要产量低的机器，但是没有找到其他家有符合的机器', 1758078668),
