(3077, 143265, 145, '9.16接到冷库询盘 采购项目在非洲 要购买六个四十尺集装箱冷库 零下十八度 等待报价', 1758078854),
(3078, 143645, 75, '客户是中间商，他的客户要买，已经报了S6，311，318以及511的参数和价格，等他的客户看过之后通知我。', 1758078909),
(3079, 142832, 145, '中国人在加拿大 购买落地式小型洗碗机 已报价 DDP,客户要让安装师傅上门确认线路 等待确认', 1758078927),
(3080, 141540, 90, '跟进未回复', 1758079477),
