(3083, 141716, 90, '双层折叠房报价，客户未说明运输港口和采购计划', 1758079780),
(3084, 136215, 144, '9.16:给客户发送了水单和客户来访照片，不确定客户是否已读', 1758079880),
(3085, 134077, 144, '9.16：问客户目前的披萨店的运行情况，客户说这周末有望开业', 1758080054),
(3086, 125121, 144, '9.16：给客户营销了客户来访和水单，目前没有回复和已读', 1758080184),
(3087, 139413, 137, '与客户打电话，接通没有声音。目前在营销，尝试当面打通电话沟通阶段。', 1758080330),
(3088, 143360, 161, '确认需求：16盘热风循环炉，电和燃气都报一下，CIF加纳\n佳怡推了一个价格更有优势的厂家：正麦，在接待客户，晚会才能回复', 1758080354),
(3089, 141097, 137, '客户在聚会，还没确定询问的细节，尽快会确定。', 1758080387),
(3090, 141050, 137, '客户在比价，看到比我们便宜600美金的机器，从产品特质指出我们的优势。-已读未回，打电话不接。', 1758080519),
(3091, 71334, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复', 1758080558),
(3092, 136365, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复，没读', 1758080681),
