(3094, 138854, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复', 1758080740),
(3095, 138385, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复', 1758080788),
(3096, 140107, 137, '目前途信，whatsapp联系不上。', 1758080842),
(3097, 133959, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复', 1758080859),
(3098, 133171, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复', 1758080941),
(3099, 142249, 90, '客户要开一家公司，先采购一台机器，询问支付方式，客户当地的支付方式不符合', 1758080952),
(3100, 124724, 144, '9.16：给客户发送了客户来访和水单营销，客户没有回复', 1758080987),
(3101, 142562, 137, '客户提到，也在等其他家报价，公司开会商量审批问题。需要决策层来定，目前把餐车问题，目录，出口认证问题都已经给客户讲明。', 1758081041),
(3102, 142285, 90, '客户想要放在高速路边，已报价，客户还在考虑', 1758081047),
(3103, 142436, 90, '未回复', 1758081067),
(3104, 139577, 144, '9.15的时候，客户想要证书，需要通过卫生局的审批，因为没有NSF证书，给客户准备了CE证书，客户说他要NSF证书，然后在9.16日给客户了NSF证书，客户已读，打算晚上问一下客户有没有提交给卫生局，客户说如果审批通过他将会购买', 1758081171),
(3105, 142506, 90, '客户想要干冰清洗机和干冰制造机，运费已报价，客户未回复', 1758081195),
(3106, 139809, 125, '到波士顿港的运费是$510，总费用是$5759+$510=$6269。\n9.15号给客户营销其他客户收到餐车的图片，9.17客户回复我，说需要几周时间收齐钱，收齐后会付款，给她预留位置。告诉客户会为她预留本月的生产位置，但是一定要在本月前交定金。', 1758081210),
(3107, 142632, 90, '已读未回复', 1758081219),
(3108, 142999, 90, '当地价格一样，客户想在当地买', 1758081256),
(3109, 143403, 124, '9.16 客户在平台下单付款然后又取消付款，沟通退款原因，客户说自己后悔购买\n9.17 展示公司实力，发送冻干机照片，询问客户具体需求', 1758081334),
(3110, 142315, 156, '9.13 客户确定要2台饮料售货机，已报价，介绍产品\n9.15 报运费，一直未读\n9.16 墨西哥最近过独立日这两天放假，客户明天要查一下关税问题，名字 邮箱已要过来了', 1758081497),
(3111, 89303, 144, '9.17：给客户发送了客户来访照片营销，并说明如果对薯条机有任何想法可以随时跟我说', 1758081657),
(3112, 142519, 156, '昨晚打电话，刚接通客户就挂了，在重新确认客户需求中', 1758081789),
(3113, 131031, 144, '9.17：给客户营销客户来访照片，客户没有仍然没有回复', 1758081876),
(3114, 139210, 156, '客户想买棉花糖机来创业，但最近不会买，不知道什么时候买。可能在找地方或有资金问题，后面4~5天联系一下', 1758082028),
(3115, 142325, 125, '9.16号给客户发消息让客户查看WhatsApp，客户未读\n9.17号客户读了没回，再次给客户发消息让他查看邮件；准备在WhatsApp上发送邮件内容', 1758082072),
(3116, 143146, 130, '客户想要更换自动售货机的支付系统，我问了厂家，厂家说不好弄。不清楚客户的自动售货机有么有预留刷卡器的安装位置还有接线口。我建议客户买台新的，客户也同意了，给他报完价后，他说他的自动售货机250美元买的二手的。后来就没回复了，估计嫌贵，没有预算。', 1758082098),
