(3310, 66891, 144, '9.18：给客户发消息，询问家里人目前的情况，客户说很好了，然后询问了草莓的状况，还说了加下来11月份、12、1、2、3月份是收获季节，可能会很忙，询问客户是否会是在明年购买，客户说不确定', 1758197003),
