(3325, 143390, 140, '0918给客户解释完切换语言和货币识别还未读，下午打电话', 1758244561),
(3326, 143579, 180, '9.17  根据邮件上客户给的照片给客户做了背调，发现客户是做有关船舶运输和清洗的，再次确认客户是否是清洁船舶机械和水垢后给客户发送机器清洁的视频，客户需要这款机器不同型号的价格和参数，客户看后询问是否有一样清洁效果但机器整体的尺寸要小，需要可以放在船上移动的型号，与客户查询后，与客户说明机器要小但无法满足客户的清洁需求，A625i 的整体体积小，机器配备轮子手柄可以移动等 之后客户给出具体地址查询DDP的运费，之后客户说要付款的话会及时通知我 \n客户需要我给些折扣，发了网页上别家型号的机器图片，还是纠结机器体积有没有更小的，跟客户说明机器尺寸后，客户已读不回\n9.18 给客户发送关于申请折扣并发送报价单的邮件 在Whatsapp上给客户说明已经给他申请到折扣让客户注意查收后，客户又询问是否有干冰制造机之后，问我如何付款，是用paypal？之后根据客户所给的信息，为客户起草阿里的信保订单。\n客户发现阿里订单的图片与报价单中不符，为客户说明情况 ，后续发现客户没有付款，询问情况，说明Paypal付款会出现失败是很正常的，附带了一张其他客户付款失败但后面成功的照片，客户还未读', 1758244723),
(3327, 144392, 174, '第一时间跟客户发了信息，等待客户睡醒回应', 1758244859),
(3328, 143259, 172, '9.19号给客户发信息没读然后打视频也没接', 1758244867),
(3329, 142344, 174, '昨晚客户已读了我的信息，问我们的餐车需要生产吗？\n我说餐车内部根据客户需求定制，需要15-20天的生产时间。', 1758244953),
(3330, 142658, 174, '昨晚趁客户在线再次跟进，问客户在考虑价格，收货，生产等问题吗？客户说他们正在讨论，我祝客户事业兴隆。', 1758245035),
(3331, 144277, 174, '客户是烘焙坊女主人，她想要定制餐车涂装，已报价，客户需要跟丈夫商量一下。', 1758245131),
(3332, 140183, 180, '9.16 法国干冰清洗机(33-675707173)\n9.16 客户需要清理旧车的锈迹，与客户发机器处理锈迹的视频 ，客户询问机器价格\n客户觉得太贵他的预算只有1200欧，问我是否有既满足他清洁需求又能满足他预算的机器，会为他尽力查找\n说明有预算范围的机器，但无法满足他的清洁要求 也发了机器的参数和价格 客户回复会考虑一下的', 1758245251),
(3333, 58769, 82, '9.19 已发WhatsApp跟进', 1758246162),
