(3344, 143900, 129, '暂时没有联系上', 1758248108),
(3345, 144080, 173, '9.18 已报价，客户在纠结怕售后不及时与在本地购买相比 晚上打了视频。客户有购买五台的打算，说今天给回复', 1758248171),
