(3350, 143082, 121, '昨晚上客户说要跟妻子商量一下，在等回复', 1758248262),
(3351, 143380, 173, '9.16 已推荐 客户发的单个机器并进行报价\n9.17客户又询问了小型生产线，给了报价单\n9.18没回复\n9.19 今天继续跟进', 1758248352),
(3352, 143916, 121, '18号 的询盘，加上WhatsApp后，没有回复，打了语音电话后就回复了，说暂时不需要，我说那以后有需要随时联系。', 1758248370),
(3353, 143378, 173, '9.16 已经报了价格和运费\n9.17 客户又问了新款式\n9.18 客户说买，发了支付宝收款码，客户说下周买', 1758248455),
(3354, 142752, 121, '给我发了一个文件，说里面是他想要的产品信息，我的电脑打不开，问客户能不能发图片，他还没有回复', 1758248521),
(3355, 143047, 173, '9.17 已经给客户报价\n9.18 与客户讨论餐车款式 客户考虑交期，以及款式问题还在讨论\n9.19 目前还没回消息', 1758248586),
(3356, 143045, 173, '9.17 给客户提出可以先支付定金，然后安排生产，等客户回国了再发货、客户表示认可\n9.18 客户问百分之三十定金是多少，回复并提供了支付方式，目前客户还没回复', 1758248696),
(3357, 143021, 173, '9.17 疑似客户是骗子', 1758248717),
(3358, 142311, 173, '9.16 客户没回消息\n9.17 客户回消息了，一起讨论了机器的细节，各方面客户都很满意\n9.18说12月筹备好资金，一定会来购买', 1758248838),
(3359, 144176, 149, '壁挂式香水自动售货机：1,150 美元\n卡支付系统：550 美元\n硬币支付系统：50 美元\n产品总价：1,750 美元。\n到西班牙阿尔赫西拉斯港，费用为 177 美元，\n到荷兰阿姆斯特丹港，费用为 165 美元。', 1758248943),
(3360, 141715, 173, '9.13 确定款式并报价\n9.14客户没有回复\n9.15 客户对款式和价格表示认可。表示要买 但客户倾向亚马逊，我引导阿里，并起草付款链接\n9.16 客户一直没付，我询问理由 客户说 不相信我们的合法性 我开始营销\n9.17 打了两个视频电话，没接。但是客户表示疑虑消除\n9.18 与客户在确定收货地点和一些款式细节上的问题。', 1758249050),
(3361, 141656, 173, '9.16 11-16 号一直没回消息，16好回消息说太忙了，仍在和小伙伴对比。我提出说了更加优惠的力度\n客户表示认可。说本周会给回复', 1758249188),
(3362, 141609, 173, '9.14突然出现说再考虑价格问题 说感觉加上进口税和运费价格会超级高。我向他解释了说DDP不需要他交额外运费。但是一直到现在还没有回复消息。', 1758249337),
(3363, 143259, 172, '客户说他已经800美金在其他地方买过了', 1758249349),
(3364, 141141, 173, '9.10-9.16中间断断续续交流细节中，\n9.17客户表示说，需要先找到场地们，再考虑购买.我建议客户可以先交定金提前生产，在这个时间内可以去找场地。客户表示否定。还是坚持先找场地。', 1758249476),
(3365, 141099, 173, '到9.19一直联系不上。', 1758249504),
(3366, 140907, 173, '9.12 问了跟团队的讨论结果，但是一直没有回复\n9.13回复说实在太忙了，导致最近有点生病，没精力回复，然后就下线了，一直没有上线。', 1758249656),
(3367, 144175, 68, '1:已whatsapp 联系，已发视频，已发机器功能和优势，已问具体的需求是要脱什么坚果，和从哪个环节到哪个环节，产量重新和客户确认了1000千KG 每年', 1758249862),
(3368, 144398, 165, '客户有位置放机器，已报出厂价，客户在纠结亚马逊价格和实际价格不一致', 1758250192),
(3369, 140907, 173, '一直到今天，有在间接性跟进。', 1758250293),
(3370, 143266, 209, '9.19营销了公司的金秋动员会，客户说房子是给她母亲居住，但不和我讨论房子的细节', 1758250310),
(3371, 140695, 173, '一直到今天都联系不上', 1758250356),
