(3374, 144420, 71, '拖鞋机+包装机，送货到门， 客户需要考虑下，从我们买机器和原材料，目前机器送到门总价格31450美元', 1758252403),
(3375, 144187, 71, '1000产量不含烘干，总价12300USD， 送到客户港口，想要来看机器，计划中，短期内应该不采购', 1758252507),
(3376, 144345, 164, '300kg, 只需要油炸机和速冻机，法式土豆条，已经有其他的机器，福匠做配置，已报价油炸机，速冻机需要确定客户长度尺寸', 1758253191),
(3377, 144317, 124, '9.19 联系客户，打招呼并发送自动售货机照片，询问客户售卖售卖什么东西。', 1758253767),
(3378, 139564, 133, '9.18晚客户突然回信，说一些乱七八糟的他单身诸如此类的话，他要我照片，跟他说约定北京时间9.19早8:30打视频聊机器，同意了，说看看到时候有没有时间\n9.19早发消息未回。', 1758253898),
(3379, 144036, 71, '4*4 金属烘干，全套设备72360美金  CIF价格， 10月12来看厂，竞争对手在新郑，预计12月份使用机器', 1758253948),
(3380, 142090, 133, '9.19客户说周末才有时间评估，周一谈。', 1758253951),
(3381, 142638, 124, '9.16 发现被拉黑\n9.18.途信电话，客户未接\n9.19 途信电话，客户未接，电话被拦截，换电话打，未接', 1758253992),
(3382, 144244, 133, '9.19报价2803美金，客户想用1800美金/台的价格买，买4台，说我给他的价格太高了，问底价。机器的成本2070美金，给了折扣价2550美金，已读未回。', 1758254150),
