(3384, 142293, 120, '9.18 营销发货，国庆节，已读未回', 1758254427),
(3385, 138720, 138, '客户说不感兴趣，不耐，不要再联系', 1758254495),
(3386, 144452, 163, '9.19  客户需要方拖 ，发送，图片和视频，因为时差，客户还没有回复', 1758254592),
(3387, 138720, 138, '①9.3报价＋运费，客户想自己装支付系统，和客户说明了对接型号，客户后来没回复，正在跟进中。 ②9.6说1800价格太贵，给了100折扣，9.6-15不回信息。 ③9.16说不需要香水售货机了，9.17说现在不感兴趣了，停止联系', 1758254630),
(3388, 143562, 134, '已再次跟进 等待回复', 1758257599),
(3389, 122881, 78, '邮箱撞单', 1758259099),
(3390, 144497, 78, '别人扔到公海的疑似垃圾客户', 1758259147),
(3391, 143124, 134, '客户需要现货 但是有现货的厂家 价格贵 等待客户回复', 1758260761),
(3392, 142538, 170, '昨晚打电话，客户表示周围很多人说餐车在美国使用还需要很多的证件和改装，而且中国的拖车价格并不便宜，所以他决定在当地购买。', 1758261731),
(3393, 143676, 124, '9.17 后台联系客户，客户是中间商，采购机器出口尼日利亚。客户发了客户清单，询问厂家说能做，询问客户的具体产量。\n9.19 发送屠宰线运行视频，再次询问客户的客户的产量要求', 1758261909),
(3394, 144383, 139, '了解了客户需要的餐车尺寸是四米，客户咨询运费也为客户报了运费价格，客户想要的设备有旋转烤箱，燃气灶，小冰箱，为客户发送了几种尺寸选项和价格，客户也确定了具体的型号。客户想要餐车的布局图，我回复客户说需要支付意向金为他设计，客户还没有读取消息，后面会继续跟进。', 1758262012),
(3395, 142053, 124, '9.19 视频营销，发送手机壳售卖机的俄语版机器操作视频，已读不回', 1758262072),
(3396, 142053, 124, '9.19 视频营销，发送手机壳售卖机的俄语版机器操作视频，已读不回', 1758262074),
(3397, 143257, 139, '客户昨晚回复消息，说是儿子在了解详情，不小心点错了，回复客户没关系，并继续营销跟进', 1758262101),
(3398, 140967, 124, '9.16 把美元报价换算成俄罗斯卢布，问什么时候购买，要客户邮箱，名字\n9.18 问客户是否浏览过换算的价格，是否超出预算\n9.19 发送俄语版手机壳售卖机运行视频，营销公司实力', 1758262387),
(3399, 144057, 134, '客户坚持亚马逊付款，再感化一下', 1758262532),
(3400, 142926, 134, '下周一再次联系', 1758263233),
(3401, 142490, 124, '9.19 发送一些冻干机冻干物料视频，询问预计购买机器的时间', 1758263299),
(3402, 143476, 153, '了解到客户是为了完成去世丈夫的遗愿所以想购买一辆大的餐车，上来就问最大的尺寸，向客户介绍我们最大的是36英尺的，问到目前餐车内部有三位员工，明年可能会增加，推荐了6米的餐车还没报价，问了一些问题客户也不太清楚，说明天去实地测量下，唯一提出的要求就是空调要最大的', 1758263647),
(3403, 143418, 159, '客户想要2-3台，但是在意进口清关和关税问题，给客户报了ddp价格。客户在当地找到了中吉代理商，包括清关交税，但是价格更高。已给客户优惠并且阶梯报价，客户在考虑，我会继续营销跟进。', 1758263942),
(3404, 143409, 159, '客户想在11.5号收到餐车，想要2.2m圆拖，天纵厂家做的快，预计下个月可以做出来，但是太小的不做，给客户推荐3m长，已报价5500美元，客户要和他商业商量。', 1758264122),
(3405, 144248, 123, '客户很急躁，一直说付款也要在亚马逊；想要在亚马逊平台上聊天', 1758264246),
(3406, 143277, 159, '客户购买5台机器，给客户阶梯报价，加上支付方式每台3350美元，客户说泰国供应商报价3200美元，他还没决定购买哪一家。', 1758264259),
(3407, 143869, 123, '报完价不回复，意向还好，会在营销', 1758264275),
(3408, 143547, 123, '客户不经常上线，还没确定好客户的需求', 1758264307),
(3409, 143252, 123, '客户想要网站上的价格，解释网站上只是参考；推荐了便宜款式', 1758264339),
(3410, 142662, 153, '客户目前处于前期收集资料阶段，计划在学校和机器投放机器，能不能落地还有待商榷。了解需求后推荐了彩云卷家的55英寸屏幕12寸披萨的机器，报价11200美元利估29%，到洛杉矶的运费186美元，客户说要收集更多的资料有消息会通知我', 1758264341),
(3411, 142879, 159, '客户购买10台机器，阶梯报价，但是客户已读不回，发信息很冷淡。主动提起再次申请优惠，每台给客户又优惠100美元。客户已读未回。计划在营销营销，找个合适理由再次降价。', 1758264370),
(3412, 144259, 170, '9.19：暂定4米方拖，做了报价单。客户要了阿里链接看看其他型号，客户说明天回复', 1758264449),
(3413, 143025, 123, '营销客户来访', 1758264477),
(3414, 142802, 123, '已经报价，客户是中间商；要等他合作伙伴商量', 1758264509),
(3415, 143085, 153, '客户提出阿里巴巴等平台付款，是否有CE，以及要保证玻璃罐子的完整，计划在26年3月，4月投入生产，对客户的问题都进行了回复，营销了水单进行催单', 1758264587),
(3416, 142853, 159, '客户刚开始做饼干行业，给客户发饼干方案。但是客户说饼干在当地竞争太大，要重新考虑饼干生意，在做调研看是否要开启这个生意。', 1758264645),
(3417, 142723, 123, '客户很忙，回消息不及时；但是态度很好，已经给客户推荐了设备清单，还在确认中', 1758264672),
(3418, 142391, 123, '帮客户找合适的餐巾纸和杯子，持续跟进中', 1758264718),
