(3425, 141080, 159, '现在客户想购买假睫毛，先不讨论机器了，给客户发送了假睫毛的信息，客户要一层一层给终端客户说，现在还未回复', 1758265051),
(3426, 141018, 159, '客户手机无法接通，还没联系上，打算让其他同事联系试一试', 1758265092),
(3427, 142796, 134, '今晚打电话问一下原因', 1758265271),
(3428, 140697, 159, '客户不！回！复！！！！！！！！！', 1758265314),
(3429, 140249, 159, '给客户打视频客户不接 发信息不回，以后不那么着急报价了！！！！！！！！', 1758265370),
(3430, 139540, 159, '客户有创业梦想，但是就是不讨论机器，发信息不回', 1758265417),
(3431, 142687, 134, '客户没有WhatsApp  周一跟客户发邮件  等待客户回复 ，今天跟客户打电话', 1758265459),
(3432, 140025, 159, '客户刚开始做热狗生意，在意价格，觉得太贵了，在给客户营销，可能她挣一段时间钱 就有钱买餐车了', 1758265491),
