(3435, 143475, 155, '给他做过报价单了，3.5m方拖还有设备，也咨询了运费，都报了价格，昨天晚上也用水单营销了，客户现在已读报价单和营销没有回复，下一步可以打电话询问', 1758265770),
(3436, 143151, 155, '跟客户聊了之后询问过后才知道他要的是卖咖啡的餐车，给他推了圆拖之后也简单报过圆拖的餐车价，但客户又说需要那种集装箱样式的不带轮子的，昨天问过威凯家之后发了一款，但是未报价，客户已读没有回复产品怎么样反倒是发了个早上好', 1758265911),
(3437, 142558, 155, '阿里卖家上客户一直未读未回', 1758265942),
(3438, 142687, 134, '电话已接通，已再次跟他发送规格和价格，等待客户回复', 1758267990),
(3439, 142602, 134, '客户想了解 价格，昨天已报价 但是客户没有回复', 1758268203),
(3440, 143749, 119, '9.17在网上找了一款65 × 75 × 180cm，功率为 2200 kW 的洗车机售价 913 美元。想要把洗车机放在车里面，可是他的车只有1米高。\n9.18又在网上找了一款小型的洗车机，不过就几百块。。。。', 1758268332),
(3441, 143749, 119, '9.19计划今天给他推拖车，让他开车拉着拖车走，洗车机放进拖车中', 1758268384),
(3442, 142602, 134, '已再次营销，等待客户回复', 1758268669),
(3443, 143318, 119, '9.16 需要两辆3.5*1.6*2.3M电三轮，报价2011美金，想要进行室内设计。性格：活泼\n9.17营销公司视频\n9.19营销阿拉伯水单', 1758268733),
(3444, 143703, 119, '9.18需要双头香肠捆扎机，机器报价是 6613 美元。客户嫌贵，推荐单程机器售价 2,172 美元。\n9.19运送到MEDELLIN的运费为356美金\n运送到布埃纳文图拉的运费为129美金，让客户挑。', 1758269248),
(3445, 142509, 134, '晚上跟客户详细沟通一下', 1758269359),
(3446, 143921, 119, '9.19选择方拖（貌似喜欢19英尺的那款，5.8米，报价7839美金），需要 2 个油炸锅、水槽站、冰箱、冷却器，也许还有小平烤架', 1758269676),
(3447, 143944, 119, '9.19发送披萨机车间照片，告知披萨机价格基本相同，询问想要放置几寸的披萨', 1758270077),
(3448, 144271, 68, '1：已联系，已推荐长度', 1758270381),
(3449, 144195, 119, '9.18速溶咖啡自动售货机售 2,580 美元。喜欢现磨咖啡自动售货机，报价 4,464 美元\n运费约为 300 美元\n卡：600 美元\n现金支付：200 美元\n想要$1,284 澳元，含运费，购买。还说如果你能匹配这个，我会直接支付给你的企业，而不是通过全球速卖通..回复话术，并再次推荐速溶款的，实惠。\n9.19想要最实惠的价格，说如果经营的好，之后会购买多台（画饼）。速溶款和现磨款都便宜3%，让客户选择。', 1758270694),
(3450, 144289, 158, '9.19 早上联系到客户，介绍完产品和价格，希望通过速卖通平台分期付款，解释手续费等问题，客户说保存我的号码，决定购买时会联系我。后续继续跟进和营销。', 1758271239),
(3451, 144204, 119, '9.18想要电动款小金刚，报价5582美金。9.19推荐拖车，客户偏好圆拖。B款3米圆拖4050美金。预算只有7000SR，大约1,866.20 USD。给折扣3%。4050 美元 - 122 美元 = 3928 美元，还是嫌贵。推荐2.3米B款圆拖，报价3000美元。需要与搭档商量（下周）。\n地址：R5PF+598 塞卡凯 沙特阿拉伯\n（客户挺活泼，色色的）', 1758271292),
(3452, 144202, 133, '客户未读', 1758271339),
(3453, 143453, 133, '9.19客户未读消息', 1758271362),
(3454, 143790, 127, '在阿里上发了图片视频，问他需求，需要的每小时产量已读未回复', 1758271387),
(3455, 142911, 133, '要到WhatsApp，正常跟进', 1758271419),
(3456, 144279, 127, '发送自我介绍，餐车图片，客户就问了在亚马逊上多少钱，问他要几米的没有回复', 1758271475),
(3457, 144150, 120, '9.18 已发图片留言', 1758271489),
(3458, 144150, 120, '9.19 客户要完整报价单，正在做', 1758271504),
(3459, 144337, 120, '9.19 已给客户留言', 1758271529),
(3460, 144302, 127, '发送了自我介绍，披萨机的图片，询问他的需求，还是单钩', 1758271542),
(3461, 144343, 120, '9.19 已给客户留言', 1758271552),
(3462, 144502, 120, '9.19 已给客户留言', 1758271690),
(3463, 144209, 119, '9.18发送基本信息，问有没有有厨房家具，回复由基本配置，一一列举，并表明可以为客户配备她所需要的其他厨房家具。已读未回\n9.19发送客户喜欢的款式的照片，可能在忙，未读。', 1758271728),
(3464, 143837, 170, '报价后客户未回复，找便宜厂家中', 1758271763),
(3465, 144066, 120, '9.19 运费贵，客户暂时不考虑', 1758271801),
(3466, 144436, 127, '客户要集装箱类型的厨房，给他报了空车和带基础设施的车的价格，在给他计算加上他需要的设备的总价', 1758271811),
(3467, 143977, 120, '9.19 口头报价9000USD，客户说他的预算只有6000，给客户推荐其他方案', 1758271859),
(3468, 143353, 127, '发消息询问附加功能不回复。', 1758271878),
(3469, 144296, 119, '9.19通话，大胡子男性。客户喜欢双层TS款，询问运输流程，运费。回复后，没有表态。询问想要几米拖车，已读未回。', 1758271901),
(3470, 142471, 134, '客户在当地已经找到合适的了 ，跟他营销 但是他说他已经买了，只能期待他之后在我们这里购买', 1758271946),
(3471, 143961, 120, '9.19 问客户要什么尺寸的屏幕，暂时未读未回', 1758271965),
(3472, 143884, 120, '9.18 客户要既能磨粉又能磨酱的，暂时没有找到厂家可以做', 1758272021),
(3473, 143884, 120, '9.19 给客户发了磨酱的视频，已读未回', 1758272039),
(3474, 143845, 120, '9.19 客户说还没跟他客户说机器价格，这几天见面说', 1758272083),
(3475, 142407, 134, '客户一直不上线，连续营销跟进三天 打三天电话没有回复  今晚再试试电话联系', 1758272089),
(3476, 142104, 158, '9.15客户说自己国家有人在做这个生意，自己的想法不在新颖了。营销未回。\n9.16给客户打视频，并介绍公司的各种自动售货机，问了薯条机，报价后不回复了。告诉他我们有各种区间价格的机器，已读未回。\n9.18营销公司金秋大战活动，现有促销，已读未回。', 1758272108),
(3477, 144167, 148, '9.18 确定车型和长度（3.5方）\n9.19 在确认内部设备', 1758272108),
(3478, 143711, 120, '9.18 他的客户那边还没消息', 1758272203),
(3479, 143891, 148, '9.18-9.19 暂时确定车型还未确定长度和门窗位置', 1758272210),
(3480, 143282, 120, '9.18 给客户发型号，客户说只要他文件上的那款', 1758272247),
(3481, 143107, 120, '9.18 打电话打不通', 1758272296),
(3482, 143107, 120, '9.19 给客户写邮件', 1758272306),
(3483, 143440, 148, '9.17 确定机器和型号（8格），已报价。说要考虑考虑\n9.19 询问客户想法，还未读', 1758272334),
(3484, 143415, 148, '9.16 确定型号，报价和运费价格，客户说只是想了解价格，在考虑。\n9.17 问客户更喜欢哪个尺寸，未读', 1758272421),
(3485, 142995, 120, '9.16 给客户留言未读未回', 1758272421),
(3486, 142995, 120, '9.19 看客户在线，打电话未接，发消息未回', 1758272468),
(3487, 144499, 163, '9.19  已经和客户互动，并发送400型5W成本饼干机，客户发了他要做的饼干和视频，其中有曲奇饼干。跟进中', 1758272530),
(3488, 142645, 120, '9.17 客户未上线，发消息未回', 1758272539);
