(3499, 140674, 148, '9.16 下班后打了视频展示了公司，客户说要在两周内购买', 1758273575),
(3500, 140436, 148, '9.11-9.12 发送更长的餐车图片和视频，未读\n9.19 今晚打电话', 1758273655),
(3501, 137962, 148, '这周发消息，未读，打了两次视频未接通。现在面临的问题是:出口欧洲尤其是法国必须额外加4000美金或4500美金的COC认证价格，还未和客户沟通', 1758273883),
(3502, 137625, 148, '9.17 终于找到厂家，为客户发送视频，客户感兴趣，介绍机器，客户说计划来中国看机器之后再购买', 1758273952),
(3503, 140288, 148, '客户觉得机器贵，为客户找到便宜的，客户讲价太狠，会为其找更便宜的机器', 1758274062),
(3504, 144329, 119, '9.19想卖珍珠奶茶和饭团。\n电动三轮车售价 2,011 美元。\n1.2 米冰箱 $350\n8 升 304 食品级储物容器 $150\n1.2 米隔热展示架$450\n运费 $494\n总计：3455 美元', 1758274243),
(3505, 144334, 158, '9.19阿里上介绍后，客户问了能在户外使用吗、防水吗。美国应该休息了，后续继续跟进。', 1758274285),
(3506, 140072, 120, '9.19 发100kg/h报价单', 1758274385),
(3507, 144538, 119, '9.19想要AI款2.8米粉色拖车，要到WA，发送基本信息报价，未回', 1758274459),
(3508, 143922, 158, '9.18打电话、发信息未联系上.\n9.19发了一些图片和运输问题 客户就下线了', 1758274741),
(3509, 144262, 158, '9.19介绍了两台自动售货机，告诉客户价格和支付方式的信息。\n后续继续跟进和营销。', 1758275032),
(3510, 144492, 163, '9.19 WhatsApp 给客户发送基础信息，图片视频，等待客户回复', 1758275046),
(3511, 142486, 156, '前几天客户一直犹豫选哪个运输 方式，今天告诉我他已经在当地找到更便宜的了，还在尽力挽回', 1758275138),
(3512, 143945, 158, '打电话、发信息未联系上，已发送邮件。', 1758275177),
(3513, 143957, 156, '客户想要了解自动售货类的信息，发了4款类型的售货机都没有客户喜欢的，还在确定需求', 1758275377),
(3514, 143889, 158, '3m黑色圆拖\n9.18联系上客户，介绍一些餐车信息，客户需要3m黑色圆拖。\n下个月或至少到十一月购买，营销尽快买，客户说Amzon更便宜，并且问分期付款问题。要去和同伴讨论一下再告诉我。注：解释平台上是定金，客户表示理解，有礼貌。', 1758275636),
(3515, 144188, 137, '打电话确认客户是帮别人采购，需要对方确认后下单。', 1758275817),
(3516, 143388, 158, '9.16联系上客户简单介绍。9.17给客户发自动售货机目录让客户自己选择。客户需要和老板核实一下。9.18询问客户情况，客户说老板太忙了，等他查看后会告诉我。', 1758275854),
(3517, 143877, 158, '3m圆拖\n9.18给客户介绍了餐车，客户说明年年初会使用，报完价格后客户说需要和丈夫谈一下。9.19问她商讨怎么样,未上线。', 1758276078),
(3518, 143850, 158, '9.17发信息介绍自己已读未回。9.18发豆腐机产品信息、要号码已读未回。9.19发信息已读未回。', 1758276210),
