(3528, 142637, 87, '客户说让介绍加拿大的供应商，要在加拿大买，如果没有，不感兴趣购买，后面跟进无回复', 1758277234),
(3529, 140831, 157, '9.11-9.15 发消息营销未回\n9.19 营销未回', 1758277302),
(3530, 142362, 87, '生产线和原材料，已发PI，今天跟进说在核实海关和税费，已经大概告知，等客户回复', 1758277344),
(3531, 142372, 134, '等待客户回复，今晚尝试联系客户', 1758277734),
(3532, 142348, 134, '客户没有whatsapp  再次跟客户发送邮件', 1758277840),
(3533, 143881, 157, '9.19 发送邮件', 1758277883),
(3534, 143303, 158, '自动售货机+衣服售货机\n9.16给客户介绍了自动售货机等说太贵了，要去其他家买。说我网站上营销最贵的机器标注最便宜的价格。解释营销话术。客户说别人便宜也包运费，到门。\n9.17为他找了一款超级便宜的机器，可以接受。问了衣服售卖机，发送了图片和价格已读未回\n9.18发消息未回。\n9.19打视频电话拒接', 1758277956),
(3535, 143852, 157, '9.19 报了运费 客户说预算6500美金（机器加运费），想要折扣，如果合适将会购买更多。（目前价格超预算比较多，折扣待计算）', 1758278023),
(3536, 143460, 157, '9.19 问了个性化定制问题，其他没什么疑问，待发报价单和发票（继续跟进）', 1758278127),
(3537, 142235, 134, '客户没有回复，打电话一直没有接', 1758278284),
(3538, 143199, 158, '平台上付钱的\n9.16电话打不通，介绍自己和产品信息，9.17、18发信息打电话未回。9.19头像灰色，单钩。', 1758278360),
(3539, 143092, 158, '9.16给客户发邮件，9.17回复邮件问我运输、保修期等问题。回复客户后未答复我。wsp没给我', 1758278521),
(3540, 143386, 157, '9.19 客户问了常温款最小型售货机，给他优惠了100美金，还是觉得价格高，进行营销，客户说再想想。（没说不要，继续跟进）', 1758278522),
(3541, 142188, 134, '已经再次跟进，等待客户回复', 1758278621),
(3542, 142978, 157, '9.19 发送邮件 待回复', 1758278879),
(3543, 143862, 158, '4m圆拖+4m长的抽油烟机+空调\n9.18客户发了一系列问题，说自己在货比三家，聊了一些抽油烟机最大做多长和空调能否放在-40度的环境里。\n9.19早上为客户报价，机器+内部设备价格。上线未读。', 1758278922),
(3544, 144234, 160, '顾客只询问了工作流程 发送视频和文字解释 顾客已读不回', 1758279187),
(3545, 143455, 160, '发什么顾客都已读不回 后续不读', 1758279234),
(3546, 143389, 160, '个人使用 喜欢206和606型号 但是预算很低 发完价格之后说价格太高 提了质量和售后 不回 推荐了更便宜的款式 不回复', 1758279319),
(3547, 143090, 160, '发送了两封邮件 全部投递成功 但是顾客没回复', 1758279349),
(3548, 143050, 160, 'wsp顾客未回复 打语音未接 未联系上', 1758279420),
(3549, 142975, 160, '顾客喜欢带有泡面款式的自动售卖机 但顾客对网站上的金额与实际不符产生疑问 解释网站上是定金 但顾客还是对质量和售后不放心--话术解释 营销 顾客仍然想要再他们当地购买', 1758279714),
(3550, 142179, 157, '9.19 发送跟进邮件，待回复', 1758279760),
