(3556, 139665, 93, '需要30kw船用柴油发电机组，报价以及运费，客户需要查看旧发电机是否能修好，能修好旧不进行购买，微修好就从我们这里购买，9,8表示1-2周后会有结果，9.15联系表示会在当地购买更便宜更便捷，包安装售后以及维修，表示之后有机会再进行合作', 1758279959),
(3557, 142089, 158, '3m圆拖+抽油烟机+3+1水槽+空调\n9.15营销说有活动和折扣价。\n9.17客户问折扣价是什么，给他发了一些餐车照片。抽油烟机、水槽和空调的价格，客户表示很满意。并且了解了运输和生产时间。\n9.18问她水槽位置，发送餐车草图，客户很满意。说准备付款了。要了地址、名字和邮箱制作PI.\n9.19给客户发送PI到wsp和他的邮箱里。发消息打电话未上线。', 1758279980),
(3558, 139661, 93, '9.6介绍不同型号的砂浆喷涂机视频以及参数，未回复\n9.9报价柴油喷涂机价格，运输到深圳，在中国有自己的货代，计划一个月采购，并询问小抹墙机价格报价\n9.11联系阿里后台再次询问价格，我就他折扣，他表示会在10日内购买\n9.15营销发往库拉索的同型号喷涂机，回复很棒，表示在贷款\n9.18表示仍在寻求贷款，会回来告诉我，让我耐心等待\"', 1758280014),
(3559, 140068, 93, '9.7发送不同型号价格，客户表示要等两天做选择\n9.10客户选号型号发送问题，回复问题并营销了公司\n9.12发送迪拜客户购买纸杯机反馈视频营销\n9.17发送纸杯机视频，没有收到回复\n9.18再次发送问候，客户回复还在进行研究，然后不回复', 1758280045),
(3560, 140095, 93, '已报价薯条，冰淇淋自动售货机，客户表示价格过高，表示可以为客户申请折扣，对方不回复', 1758280076),
(3561, 140248, 93, '9.8已跟进回复询盘，邮件报价后客户发送7个问题\n9.9解答后表示和同事讨论后会给我答复\n9.15询问对方是否有反馈，客户表示还在分析，需要更长时间，有问题会联系我们', 1758280112),
(3562, 141406, 157, '9.19 发送邮件，待回复', 1758280115),
(3563, 140597, 93, '9.9计划今年年底采购22台用于医院的300kw220v60hz的发电机组带静音箱，已报价，对方需要将信息反馈给她的boss：\n9.11联系运营董宇要升降平台价格，发送自动和半自动12米升降平台报价单\n9.14联系客户是否在收集报价，客户说在联系清关代理，费用很高\n9.17询问贵方能否给公司网站，可以促成我们双方的长期合作\n9.18客户未给网站表示已转告boss，发送公司经营产品的汇总视频并介绍公司从事外贸行业10余年，让对方对我们公司有更深的印象', 1758280135),
(3564, 142328, 160, '包装谷物 大米 荞麦等 并添加了封口机 已经根据顾客需求推荐产品 但是顾客预算比较低 满足顾客需求的机器超出顾客预算，已经发送更小规格的机器给顾客确认', 1758280140),
(3565, 141313, 157, '9.16 发消息 对方说周四会查看\n9.19 询问 未回复（继续跟进）', 1758280170),
(3566, 141227, 93, '9.10已报价电动款砂浆喷涂机以及抹墙机视频图片和价格，询问价格是否符合预期，表示检查后会联系我\n9.12打电话询问反馈未接\n9.17询问对方采购计划是否改变，未回复', 1758280192),
(3567, 141443, 93, '9.11询问扫地机价格，邮件发送报价单\n9.12要到客户whatsapp号，发送更多扫地机视频以及图片\n9.13想成为扫地机的巴西独家代理，表示每年会来中国采购产品，询问主管后发送独家代理要求客户表示需要和团队商量\n9.15降低成为代理要求，客户仍表示要和团队商量\n9.18询问客户反馈，并表示如果只采购单台试验也可以给予优惠价格，未回复', 1758280228),
(3568, 142216, 160, '常温款自动售卖机 个人使用 已发报价 但顾客目前在筹备他的个人网站 很忙 暂时搁置了购买自动售卖机的计划', 1758280269),
(3569, 141871, 93, '9.12发送卫生纸机不同型号复卷机报价，\n9.14客户询问是否为生产线报价，回复后介绍全自动以及半自动化型号的区别，发送视频图片未读消息\n9.15询问是否需要提供生产线报价未回复\n9.18营销客户来工厂参观图片视频未回复', 1758280279),
