(3577, 143058, 93, '9.16跟进报价20米深小蓝钻机，2600USD还价2000USD，无法成交', 1758280433),
(3578, 144383, 139, '和客户确认好小冰箱的型号后，客户希望尽快发送给他报价单和示意图，让客户先睡觉，已经做好了报价单，需要进一步确认的是，客户的炉子是要电的还是天然气的，因此做了两个版本的报价单，供客户选择。', 1758280533),
