(3580, 140178, 158, '9.15发送其他客户的披萨来营销。客户问价格有什么不同。16、17发信息未回。9.18客户突然联系我说给他一些时间需要和土地具有人协商并且需要冷藏款披萨机。营销运输和产品生产会占用时间，这个他时间刚好去找位置。\n9.19营销客户分享的视频，已读未回。', 1758280735),
(3581, 142744, 172, '9.19号给客户营销客户回复后重新报价又没有回复', 1758280801),
(3582, 142088, 160, '很专业 对餐车的各种认证进口标准都了解 顾客还有考虑自己生产 对价格和售后比较满意 但是海运费比较贵 已经解释运费不是有我们收取 并为他在运费上提供折扣 顾客目前还在考察', 1758280844),
