(3596, 144091, 174, '早上客户退群，我赶紧私发解释自己西班牙语不好，巴拉巴拉。\n客户中午问娱乐设备，让报10台的价格，我网上找了家，报价700美元。沉着冷静！不要热情过度', 1758284043),
