(3612, 144596, 146, '9.19发了一封邮件，没有回复\n9.20又发了一封', 1758348883),
(3613, 144588, 146, '9.19给客户推荐了两款香水售货机，并进行介绍、报价、解决问题，判断有意向。9.20给客户查询到门运费', 1758349257),
(3614, 144232, 146, '9.18跟客户确定了所有细节和价格，非常顺利，客户要给他做付款链接。他要先进行一笔预付款，发送完付款链接后，没有付款，也联系不上了。9.20继续跟进、打电话，但都未回复。', 1758349337),
(3615, 144224, 146, '9.18给客户推荐了几款机器人，客户选了两款喜欢的，然后进行介绍和报价，9.19查了到门运费，然后说今天和伙伴讨论购买事宜，下午跟进说暂时搁置了，让给他发送其他网站的链接。9.20发送阿里、SEO链接', 1758349454),
(3616, 144221, 146, '9.18跟客户报了餐车和所有需要的设备的价格，然后又讨论了细节。9.19给他计算了总价，客户说接受不了。跟当地价格快一样了，然后进行营销和话术，留住客户，客户有一点动摇，继续营销。', 1758349574),
(3617, 144179, 146, '9.18拉了群组，客户问能不能分期付款，然后就已读不回了，判断可能是没钱', 1758349669),
(3618, 143459, 146, '9.19和客户确定了港口，现在等客户确定怎么运输', 1758349868),
(3619, 129059, 146, '9.17回复说明天会进行第一次预付款，但是客户想的是等机器人到货后再支持剩余50%，跟客户进行了解释和话术运用。客户提到有没有之前合作的俄罗斯客户的合同，如果没有他们将起草发给我进行签名9.18问了清关问题，进行了解答，并进行了催单，之后已读未回', 1758350070),
(3620, 144596, 146, '9.20下午回复了消息，说喜欢在邮件上沟通，已经回复了机器的型号，参数、功能和价格。', 1758360444),
