(3633, 144216, 137, '给客户解答关于冰块自动售货机工作原理，冰块和冰袋的配套使用情况。已给客户发送意大利和英文版本报价单，客户评估后会尽快联系。', 1758376501),
(3634, 144635, 137, '客户询盘定制需求以及运费问题。一一讲述定制问题，以及运费到港或到门，最后均以反问形式询问客户，做什么生意/几个人在食品拖车工作。', 1758376625),
