(3641, 144516, 139, '向客户发送外国客户来访照片，表示如果可以的话，客户也可以来参观我们公司和工厂。并询问看到报价单后客户有什么顾虑可以谈谈', 1758423260),
(3642, 143142, 139, '9月20日客户回复了whatsapp的消息，说最近生病了，所以没有上线。客户表示预算不多，只需要容纳两个人。因此为客户分别提供之前他选择的4米双层餐车和3米便宜款餐车的报价供选择。', 1758423562),
(3643, 144383, 139, '客户看到报价单后，人家价格和亚马逊上相差太多，已经超过了二倍多，他认为他的预算要接近亚马逊上的价格。在看到客户购买意愿下降后，我向客户推荐了四米加两米栅栏的餐车，也适合他，价格比之前他选择的便宜得多，也接近他的预算，客户发来一张图片，询问我能不能做类似可以控制上下开门的餐车，问过工厂之后，工厂表示可以做，同时把这个消息同步给了客户。', 1758423836),
(3644, 144888, 137, '与客户大概确认了设备价格，还剩一款设备在沟通，在查运费，客户需求明确。', 1758426189),
