(3731, 143073, 122, '9.16打视频未接，客户说不方便。推荐款式并报价。\n9.17客户得到报价2500美金，我们的报价是8000多美金。客户说不会从我们这购买。\n9.18跟进未回 问客户相关报价的情况未回。\n9.22跟进 还未读', 1758503879),
(3732, 144247, 122, '9.19发送相关图片视频参考\n9.20简单聊了餐车，交货期，维修等问题。\n9.22发了当地一款餐车问我们有没有 已找厂家报价 和客户确认细节中。', 1758504102),
(3733, 142746, 122, '9.15确认尺寸和内部设备，已报价\n9.16客户觉得贵，换了更小的餐车，已报价\n9.17设备进行了修改，已更新报价\n9.18跟进未回\n9.22跟进还未读', 1758504413),
