(3742, 143166, 237, '营销都不回复', 1758504841),
(3743, 144860, 127, '客户想要四米的尺寸报价5000多美元，嫌贵，说要去亚马逊上买，给他解释了最终需要和我们确认，如果预算有限可以推荐小的，已读不回复', 1758504856),
(3744, 145084, 121, '客户来的时候需求比较明确，昨天晚上就在线，来的时候说要三米的小圆拖，不要内部设备，只要空车，然后我就跟他说明天在他醒来之前会把价格报给他，说期待明天与你联系，客户也挺好的，很有爱的回应我，刚刚把价格报了过去，现在客户那边是早上四点左右，等他醒了之后在追价格反馈。', 1758504879),
