(3752, 144956, 129, '跟我要关税，我说需要了解他的需求还没有回复', 1758505215),
(3753, 144914, 129, '问需要几米长还没有回复', 1758505241),
(3754, 140744, 125, '9.22客户告诉我因为周日他们不上班，所以明天才能知道贷款是否能下来，客户将餐车增加到3.5米的长度，原价是5280美元，给客户了280美元的折扣，客户说贷款下来如果能承担得起就买，承担不起会问其他的供应商，等贷款下来了随机应变，持续跟进中', 1758505251),
(3755, 144081, 82, '之前和客户有过沟通，客户说是证券公司一带一路项目要采购挖掘机，但客户总聊一些题外话。\n周一客户已经被拉黑', 1758505300),
(3756, 144907, 129, '他要的是炸薯条机，问了很多问题回答了，报完价了还没有回复', 1758505303),
(3757, 144104, 82, '客户让给折扣，已发PI和报价', 1758505327),
(3758, 145117, 157, '9.22 发了相关信息，确定需求（一台+纸币器硬币器），报价和运费，对方说现在没钱，12月份发工资会再次联系我。（继续营销跟进）', 1758505344),
(3759, 144250, 129, '他给我发了他的冷库草图，了解完各项信息之后，现在在给他报价', 1758505362),
(3760, 127503, 140, '之前了解到客户预算低，上周推荐了1880的售货机客户已读不回，刚打电话沟通客户想要更便宜的，两个月之后有购买计划，又加了微信', 1758505490),
(3761, 143865, 125, '客户打算购买几台在当地购买，给客户报了他感兴趣的那款餐车的价格，客户已读不回，又给客户推荐了几款便宜的并报价，客户还是已读不回；\n22号继续跟进，尝试给客户打电话或视频，了解客户担忧', 1758505514),
(3762, 144687, 120, '9.20 要参加活动来不及，取消订单，发几张好看的餐车，客户选了其中一款，口头报价', 1758505545),
(3763, 144886, 125, '9.21明确客户需求，客户想要做墨西哥食物，需要增加设备，给客户报价\n9.22给客户报运费和总的费用总价：$5280+$300+$1,000+$680+$650+$580+$1145=$9635，客户已读不回，持续跟进中', 1758505717),
(3764, 144994, 157, '9.21 沟通需求，（自己用，3米方拖加一个炉子和一个甜甜圈机，做热狗汉堡等快餐生意）报价后，对方说她以为亚马逊的价格是最终价格，她是看中价格低才来问的，预算只有2600美金。', 1758505977),
(3765, 144317, 124, '9.22 给客户打whatSapp视频电话，客户未接', 1758506283),
(3766, 142089, 158, '9.20客户发信息到我的邮箱，问怎么付款，分享客户银行水单打消顾客疑虑。发送PI和银行信息截图。客户说去银行付钱，说周末不一定开门，周末去看一下。我告诉他也可以用手机app。\n9.21对顾客的餐厅表示赞美，拉近距离。\n9.22客户问可以通过手机银行app吗，已回复。', 1758506308),
(3767, 144880, 156, '客户要2.2米的圆拖，接受3000美元的价格，今早报了到门价已读，发完报价单未读', 1758506382),
