(3785, 145360, 170, '明天联系', 1758511463),
(3786, 145200, 149, '到布埃纳文图拉港的海运费：186 美元。\n产品价格：3100 美元。\nCIF 布埃纳文图拉港总价：3286 美元。\n报价比网站价格便宜100美金', 1758511720),
(3787, 143852, 157, '9.22 给他算了折扣，发送报价并营销，等待回复。', 1758512504),
(3788, 145144, 165, '客户已选择方拖，待确认尺寸及设备', 1758512586),
(3789, 145049, 157, '9.22 发送了邮件，待回复。', 1758512735),
(3790, 142440, 71, '已报价未反馈，40尺房子，报完价就不说话了', 1758512789),
(3791, 145181, 214, '已发邮件和WhatsApp，尝试取得联系', 1758512861),
(3792, 145207, 165, '暂未联系上，已留言', 1758513149),
(3793, 144742, 152, '9.20获取客户邮件，给客户发邮件回复客户问题，询问客户需求并简要介绍我司产品，表示希望获得客户联系方式，客户未回。9.22向客户再次发邮件，未回。', 1758513532),
(3794, 144640, 163, '总计：2000 美元 + 285 美元 = 2285 美元，相当于 42045 墨西哥比索，客户价格接受，问到关税，在沟通', 1758513549),
(3795, 145125, 148, '9.22 确认方拖（2.5米），确认3+1水槽的位置+推拉窗+空调。客户睡觉去了，让我明天报总价和运费（弗罗里达）', 1758513680),
(3796, 144885, 148, '9.21 打电话，客户说会看信息还未回复。\n9.22（晚上打电话）', 1758513748),
(3797, 144652, 148, '9.21 打电话沟通，确定方拖\n9.22客户发送产品截图，为其发送类似图片视频，还未回复', 1758513849),
(3798, 144863, 157, '9.22 在阿里平台发送基本消息，等待回复', 1758513910),
(3799, 144167, 148, '9.20 客户要跟自己的会计确认并要去当地询问COC，关于如何上牌再给我答复\n9.21客户说周日联系不上人，想周一给我答复', 1758513957),
(3800, 143891, 148, '9.21确定门窗位置\n9.22确认内部设备（griddle），（晚上可以报价格）', 1758514066),
(3801, 142116, 156, '一直在和客户沟通刷卡器的问题，客户不接受我们的刷卡器（有手续费、月租费），想要安装自己使用的电子支付，\n厂家接口客户要的电子支付文档和协议后，手续费高了10个点，客户不接受。\n还在持续跟进，说服客户接受我们的刷卡器', 1758514066),
(3802, 143440, 148, '9.20 客户说喜欢机器，但有点贵，会为其找更便宜的机器', 1758514108),
(3803, 142315, 156, '9.22 催单问客户什么时候购买，客户担心由于政治问题，关税不是很稳定。\n安慰客户， 我们可以在报关文件中把交易金额写小点，可以为他减少税款降低成本。未读', 1758514277),
(3804, 144983, 152, '9.22途信打电话未接通', 1758514443),
(3805, 137962, 148, '9.20-21客户问如果下周下单什么时候能收到货，还是很有意向的。', 1758514453),
(3806, 144279, 127, '已将确认好了餐车的所有配置，给他报了运费。还没有回复', 1758514540),
(3807, 141017, 148, '9.18-22 更改储冰槽的尺寸和风扇以及水桶的尺寸，为其修改报价单，还未读', 1758514557),
(3808, 144302, 127, '客户要32英尺的屏幕，给他发了不同型号的价格表供他参考', 1758514661),
(3809, 144793, 152, '9.22途信打电话未接通', 1758514681),
(3810, 145280, 164, '已打视频，黑人，想要网上的价格和成品，已经有一辆车，解释 营销设计图， 发基本的4米价格', 1758520561),
(3811, 144972, 165, '暂未联系上，已留言', 1758520652),
(3812, 144752, 165, '暂未联系上，已留言', 1758520681),
(3813, 145148, 165, '已联系上客户，待确认产品信息', 1758520718),
(3814, 142980, 154, '发了两封邮件都没有回复，之后会再隔三天发一次。', 1758520782),
(3815, 143070, 154, '需要清风，卖咖啡。客户需要高质量的咖啡机，且需要英语教学视频。给客户在1688上找了两款咖啡机客户都不满意。之后没有回复', 1758520928),
(3816, 144595, 120, '9.22 预算7500USD，先从小产量实验，合适再买大产量，厂家已报价，价格还行', 1758520981),
(3817, 145234, 134, '客户需要薯条生产线，报完价 就下线了', 1758521321),
(3818, 143264, 154, '3米方拖，总金额7637美元。谈判到清关阶段，给客户发了报价单，客户目前有点犹豫，和客户说明了清关所需要的费用，报价单也列出了所有的收费项目，客户一直也在跟我联系中，没有消失。看看后续反应，再继续跟进', 1758521491),
(3819, 144966, 157, '9.22 沟通需求，想买几台放商店（纸币器+硬币器）报了一个，对方想要更小的型号，刚发完报价，待回复。', 1758521612),
(3820, 141438, 122, '9.12给客户分别报了到门和到马萨特兰港口总价，客户又问了一些机器其他相关问题。\n9.15更新了详细的报价给客户，客户只回复谢谢。\n9.16营销客户，已读不回，电话未接。\n9.17客户咨询清关等问题。\n9.18客户咨询相关机器问题，推荐付款，问客户要邮件，起草了订单。\n9.20更新付款链接，客户没付。信息已读未回，电话未接。\n9.21电话未接。\n9.22客户回复说一切都很好，他在等待董事会决定，有消息了会回复。', 1758521711),
(3821, 143408, 154, '初次报价后，以为客户会嫌贵，客户没有对价格有很大的反应。比价关心清关，喜欢跟风。给客户发了之前加拿大客户买的聊天记录，约了视频通话，客户爽约，给客户留言本来要谈话的内容，没有回复。再次约客户，客户一直未读（客户是做夜班工作，比较忙）', 1758521739),
(3822, 145127, 164, '自己使用，搭配车内的配置，已报价，想通过amazon使用Affirm付款，解释不可以的原因，他们有一万的Affirm额度，推荐阿里 发邮箱已做阿里链接', 1758521790),
(3823, 139562, 133, '9.22说又联系了两个场地，本周会有两个答案。', 1758521891),
(3824, 144639, 120, '9.22 报DDP价格，等回复', 1758522006),
(3825, 143574, 154, '客户在亚马逊下了单，情绪比较激动，对亚马逊平台非常依赖。引导解释，未果，客户回复说要去和亚马逊客服反应，他只想要他在亚马逊上下的那个订单。我的思路是：在亚马逊上和客户聊，给他发一个定制的表格，告知他餐车属于定制产品，需要填写信息（必须非常全面），如果客户填写，给他计算出一个总价。如果不填，告知他由于客户没有完成后续订单工作，订单在24小时内自动取消', 1758522039),
(3826, 143770, 154, '德国客户，要求严格，行事严肃。和客户先大概确定了车型，尺寸，设备。进程本来在持续往下进行中，客户比较忙，爽约多次。只能给客户先留言，看客户怎么回复', 1758522168),
(3827, 143533, 164, '现在正在研究和比价阶段，问项目时间，和工厂进度，可以免费设计', 1758522422),
(3828, 144825, 157, '9.21 沟通需求，问了单柜和双柜的售货机，最后想要双柜，报价加查运费，待回复。还问了咖啡机，待沟通。', 1758522545),
(3829, 144771, 141, '已给客户报送货上门的价格， 保持跟进客户中。', 1758522585),
(3830, 143926, 122, '9.18打电话确认了细节，已报价。客户以为是现货，想快点收到货。\n9.19确认了两台的价格，不要设备，到纽约。已报价。\n9.20分享周末图片给客户，已读未回。\n9.22营销发货图，还未读。', 1758522675),
(3831, 144643, 141, '客户要3500*2100*2100尺寸的餐车， 客户做快餐油炸类。客户已发需要设备名称， 在做报价中', 1758522687),
(3832, 144276, 141, '已发餐车视频 和图片， 客户喜欢3500*2100*2100方拖。', 1758522754),
(3833, 144018, 154, '客户已经关注餐车很久了，需求明确，想在亚马逊上下单。大致了解了需要的设备，车型。给客户查了运费，客户不经常在线，一直未读。后续可以打个电话', 1758522758),
(3834, 144704, 157, '9.20 沟通需求，想要圆拖，冲着网站低价来的，解释之后，已读未回（继续跟进）', 1758522768),
(3835, 143151, 155, '给客户又重新在1688上找厂家，找了一个可以做小一点集装箱款式的，发了视频图片，也给客户报了价报过运费客户已读不回，今天营销发了公司的视频已读未回', 1758522781),
(3836, 143475, 155, '客户询问了是不是不在亚马逊平台上购买，给他解释了手续费问题，客户已读不回，今天到公司发了公司视频给客户营销，客户未读', 1758522882),
(3837, 144134, 122, '9.22暂未联系上客户，电话不接，信息不回，邮件不回。', 1758523049),
(3838, 145391, 139, '已经向客户发送了邮件，等待客户回复', 1758523051),
(3839, 144245, 122, '9.18客户电话视频未接， 说不方便，只让发信息。确认了需求，已报价和运费。\n9.20客户发了其他的款式，已报价。\n9.22给客户发了动力款，客户很满意。但是客户不确定当地清关是否能过，客户说可能只接受trailer,客户要去咨询一下。已报基础款价格。', 1758523276),
(3840, 144645, 157, '9.20 发送基本信息，未读未回\n9.22 发消息未回，待跟进', 1758523293),
(3841, 144256, 157, '9.19 发送基本信息，对方问了刷卡器如何工作，解答之后问需求，未回\n9.22（晚上打电话）', 1758523454),
(3842, 144213, 154, '之前在威凯买了个小圆拖，想再买一个餐车扩展业务。客户在联系我们之前，就已经得到了威凯的小圆拖报价，客户还在观望，向我们咨询了清风。我们的设备每一台，都比威凯那份报价单贵50美元。威凯给的价格不算高，价格挺有竞争力。客户这次还要把餐车材质改成玻璃纤维，已经给客户报了价，和威凯比价比不过，撑死持平。本以为客户不太懂行，聊完发现，客户已经观望很久了，威凯那份报价单也做了很久了。客户还是想尽可能找到更划算且符合她心里比小圆拖更好看的款式。现在，只能做好本职工作，把咱能给客户的优势展现给她', 1758523659),
(3843, 142978, 157, '9.19晚上收到客户的视频通话，发送了机器信息，暂未回复', 1758524003),
(3844, 141323, 143, '9.22 已经打了视频电话介绍了机器 客户在犹豫价格 持续跟进中', 1758524266),
(3845, 145124, 154, '客户计划要买餐车，观望阶段，不了解行情，也没有很喜欢的车型。我给客户发了三款不同的餐车，客户对方拖比较感兴趣。了解了餐车是怎么行驶的后，就主动结束了聊天。我给客户留言，把咱的餐车优势大概说明了一下，表达未来合作的想法，客户没读', 1758524290),
(3846, 135744, 143, '9.22 客户处于不信任的阶段 一直说要视频介绍公司 客户总是错过视频会议时间 一直在重新约', 1758524376),
(3847, 137035, 143, '9.22 进行了营销 客户已读不回', 1758524424),
(3848, 137073, 143, '9.22 营销被已读 后续跟进疑似被拉黑', 1758524507),
(3849, 145126, 163, 'total：máquinas expendedoras Precio: 2980 USD,Flete marítimo 260 USD =3240USD,   Convertido a Pesos Mexicanos es 59675', 1758524536),
(3850, 144898, 154, '这个客户整体节奏，客户态度都挺好。客户咨询了小圆拖，和家人两个人准备卖香港热卖的华夫饼。客户没有经验，给客户简单报价后，客户也表示满意。客户主动问了想在亚马逊上下单的想法，但是没有很强烈，给客户说明了手续费的问题，进行了对比，在慢慢引导中，客户还没读。后续，客户的需求可能还是会变的，如果设备增加，就顺便告知客户总金额越高，手续费也越高，慢慢引导到阿里巴巴。还是要给客户展现出整个流程很简便，花费不高的印象', 1758524772),
(3851, 144514, 209, '9.17发送资料，客户询问产品目录，给客户报了柴油款和电动款价格', 1758524888),
(3852, 145129, 137, '客户平台已退款，真是报价以报，运费还没提', 1758525004),
(3853, 144843, 137, '客户要求全自动产能，机器大小相对小一点的油炸机。', 1758525060),
(3854, 142744, 172, '9.22号发信息一直未读，打电话拒接了', 1758525222),
(3855, 138336, 237, '觉得太贵了不要了', 1758525236),
(3856, 143082, 121, '上次问跟妻子商量怎么样了，没有回复，然后我就营销了一下上次客户来访的照片，又询问了以一下进度，这个客户一般晚上十点左右，早上八九点上线，我准备今晚给他打个电话，看看能不能推动一下，运费是一个很大的阻碍，利润报的时候已经不是特别高了。', 1758525492),
(3857, 145084, 121, '价格给客户报过去了，三米的基础款式，价格还可以，四千出头，给客户做了报价单，显示已读，但是没有回复我，我问他这个价格还符合预算吗，暂时没有回复，现在我再看能不能再找一些便宜的厂家。', 1758525698),
(3858, 139616, 149, '产品为 1,850 美元。\n\n运费为 220 美元。\n\n韦拉克鲁斯到岸价总计：2,070 美元。还没说支付系统，客户要当地查询海关，还未回复', 1758526106),
(3859, 142519, 156, '一直给客户发消息，客户从9.15到21一直未回我，今天再跟客户进回我在看预算。表示理解后发了机器参数及售后服务，后继续跟进', 1758526237),
(3860, 143360, 161, '客户爱发语音和打电话沟通，增加了32个烤盘，和面机和打蛋机，已做报价单CIF到加纳，客户要跟妻子商量，要下邮件做发票', 1758527219),
(3861, 137886, 145, '9.19号取得联系 12英尺餐车，增加了炸锅，烤炉，冰柜，蒸锅，已报价和海运费，客户又去网站留言询问真实度，已做发票。', 1758527596),
(3862, 145112, 145, '客户的餐馆12月开业 目前很忙 确认了机器人型号 已报付款链接 客户说下周五付款，劝说客户先支付定金，下周五就生产好了。客户还没回复', 1758527966),
(3863, 144649, 146, '9.21客户表明要薯片生产线设备，9.22问客户生产流程和产量，客户让我们给他推荐，说明客户不专业，或者只是想做这个生意的想法，已经发送了报价单', 1758530062),
(3864, 144751, 161, '客户的留言是18x15尺寸的餐车，确认了单位是英尺，换算过来是8.5米长*4.5米宽，运输得用框架柜很贵，不划算，先跟客户推我们常规的尺寸，并跟威凯确认了最宽能做的是2180mm，跟客户确认', 1758530229),
(3865, 145430, 170, '未回复', 1758530451),
(3866, 145429, 170, '未回复', 1758530544),
(3867, 140749, 214, '给客户发邮件和WhatsApp，等待回复', 1758531069),
(3868, 144604, 122, '19.20.21都没联系上\n22发邮件，客户回复并接着在whatsapp沟通，已报价，但客户觉得价格有点贵，继续沟通中', 1758531156),
