(3919, 144667, 157, '9.20 发送基本消息未回复\n9.22 打了途信电话，对方没接。但是在WhatsApp回复了感兴趣的型号。确定了支付配件和地址，对方想送货上门，待查运费和报价。', 1758591302),
(3920, 145559, 121, '这个客户之前应该是跟别的供应商聊过产品了，他一上来就问我运费和通过亚马逊支付的事情，他说美国关税怎么办，我说没关系我们可以为他写低货值，他又问写多少，我说要根据实际情况，然后就直接问我可以通过亚马逊下订单吗，我说我更建议你用阿里巴巴，平台有保障，他还是坚持问，如果用亚马逊会怎么样，我说我理解你可能习惯于用亚马逊平台交易，但是你会支付较高的手续费，然后继续跟他解释，他也没有问我产品的事情，现在不回了，感觉这个客户非常信任亚马逊。', 1758591381),
(3921, 144256, 157, '9.22 打途信未打通 WhatsApp发消息没有回，打电话没接，但是看到凌晨两点他上线过。（继续打电话联系）', 1758591623),
(3922, 145437, 121, '昨天的询盘，我在WhatsApp上打招呼信息一直是单钩，然后电脑上已经显示成为联系人了，手机上可能是信号不好，一直显示该号码没有注册WhatsApp，刚才我看墨西哥时间是晚上7点。就打了电话过去，但是客户不会说英语，我跟他提了WhatsApp， 随后关注一下他是否上线 。', 1758591648),
