(4075, 144862, 150, '9.22 客户发来3600美金其他厂家的报价单，但我们报价5990美金加上到门的运费，运用一些话术，过去了，并营销水单\n9.23 客户询问最终价格为多少，在原来基础上给客户便宜200美金，但是之后客户又发来张4600美金的报价，分析报价单上面的数据，表明我们的优势，还没回复', 1758677855),
