(4081, 144383, 139, '向客户发送了新的报价单，客户表示只接受亚马逊月付，我想客户解释了为什么不能在亚马逊付款，随后我又说可以预付30%的定金帮他推进生产，客户已读未回。', 1758678393),
(4082, 145812, 125, '9.23了解客户需求后，给客户发送报价单，包含运费，客户已读不回，给客户发公司视频活动视频营销客户已读不回；\n24号继续发送机器相关视频，持续跟进中', 1758678434),
(4083, 144534, 150, '9.19 报价棉花糖机5100美金\n9.24看客户已读了，表示在国庆节付款可以便宜100美金', 1758678440),
(4084, 144460, 150, '9.22 看客户已读了但没回复要几米的，营销了一下\n9.23发了西班牙客户水单，并表示国庆节回馈老客户优惠，但客户不感兴趣，已读但不回', 1758678739),
