(4086, 145627, 125, '23了解客户需求后，给客户报价并配备相关设备；给客户打了视频，对面有一位女士和一位男士，了解TT银行付款，客户不信任我们，让客户选择先付40%，客户说让他在中国的朋友给我打电话沟通；晚上和客户的中国朋友打了电话并发送了公司的网站，让他和客户详细解释TT付款和我们公司的优势，客户挺有意向的；$6963+3+1 Sink (with water pump): $650+Refrigerator: $750+ ice maker is $350', 1758678757),
(4087, 144324, 150, '9.21 给客户口头报价5600美金，到莫斯科的仓库价格为700美金，表示能不能将语言设置成俄语。\n9.23 发送水单，与其他俄罗斯客户购买的实例，已读没回', 1758678887),
(4088, 145919, 125, '23号了解客户的需求：分配器、处理器、秤；包装粉末；每分钟40包起；80mm宽的胶片；密封3面，了解完后，客户说我这边已经很晚了，明天继续聊，客户告诉我他来过北京，中国很舒服，还让我加了他的微信，让我们明天在微信继续聊；\n24号确认客户的每袋包装重量，客户还没上线', 1758678937),
