(4096, 145785, 161, '已建档，客户有WhatsApp，取得联系，推荐了两款鲜花机给客户查阅', 1758680045),
(4097, 145571, 125, '23号了解客户需求后给客户报价并报运费，说明我们机器的优势，确认没问题后给客户制作报价单，客户请求给予最近价格，给客户折扣价格并在报价单中体现，给客户发完报价单后，客户已读不回了；\n24号准备发送水单、机器视频图片继续营销', 1758680210),
(4098, 145272, 125, '22号与客户取得联系后，客户问了很多机器的相关问题，一一进行回复，随后确认客户需求后，给客户口头报了机器的价格和运费;一台机器到亚美尼亚埃里温港口的运输费用为 466 美元，总价为 11530 美元+466 美元=11996 美元;客户担心证书问题\n23给客户发送证书并回答客户的其他问题，确认没有问题，答应客户今天为他制作一份正式的报价；\n24号给客户发送正式的报价单', 1758680509),
(4099, 144886, 125, '23晚上客户打语音打电话客户都没接', 1758680538),
(4100, 142664, 125, '23号晚上给客户打电话，没人接', 1758680577),
(4101, 140224, 149, '客户要玻璃塑料两用灌装，六头齿轮泵灌装机，12915 美元。包括一条四米输送机，以及进料泵\n运送至拉各斯港，海运费为 795 美元\n客户没回复 营销 后来发消息 单钩', 1758680817),
(4102, 140772, 149, '客户拒接电话', 1758680929),
(4103, 145437, 121, '这个客户昨天晚上终于回复我了，一上来就说我明白我i还要支付海运费，关税，清关费，以及找起重机卸货的费用，这个费用对我来说太高了，接受不了，他应该是跟其他人聊过了，然后我说你可以把你的需求和预算告诉我，他的预算是15000美元，我来帮助你，然后他发送了地址和餐车的图片，现在计算一下总的价格，', 1758681050),
(4104, 145556, 137, '客户近期在买房，搭建场地。谈好后，在与我们商量产线的问题，会来工厂，引导视频电话看工厂。', 1758681141),
(4105, 144452, 163, '9.24  持续营销，今天客户发送消息，推建4m 报价，客户拿网站价格比较，且倾向亚马逊平台订购，在沟通，准备打电话', 1758681255),
(4106, 144926, 155, '给客户报完价报完运费客户还未读，应该是客户很忙没来得及看消息，昨天和今天营销了公司视频还未读未回。', 1758681326),
(4107, 144270, 155, '联系不上客户，不回复，打电话也不接，还不知道买啥产品', 1758681383),
(4108, 140911, 149, '营销未回 单钩', 1758681465),
(4109, 143475, 155, '昨天晚上终于回复了，说如果要是购买的话会给我打电话，问他还有什么顾虑可以为他解答，客户已读不回。', 1758681474),
(4110, 145228, 155, '联系不上，WhatsApp未读', 1758681515),
(4111, 145126, 163, '9.24   营销水单，大战图片视频，客户说要比较，准备打电话', 1758681657),
(4112, 144882, 163, '9.24 已经做PI ,营销水单，大战图片，客户说这周付款，紧跟，打了电话，是位女士', 1758681812),
(4113, 146086, 134, '已经联系，等待客户回复', 1758681940),
(4114, 141332, 149, '营销，问是否有自己的工厂', 1758681960),
(4115, 145696, 174, '晚上会打客户途信电话', 1758682505),
(4116, 144640, 163, '9.24  营销大战图片视频，问客户的关税咨询怎么样了', 1758682833),
(4117, 144636, 163, '9.24  营销客户大战图片视频，金秋活动，\n订单金额低于5,000美元 → 立减150美元\n\n订单金额超过5,000美元 → 立减300美元', 1758683451),
(4118, 145762, 163, '客户冻干章鱼块，给客户发送了图片视频，也发送了邮件，等客户回复，阿里后台还未读', 1758684435),
(4119, 143336, 116, '跟进客户发送的图片，属于清风系列，已发送报价，后续客户还没有回复，会再继续联系', 1758684592),
(4120, 141363, 149, '一直营销未回，重新报到港价格，给折扣', 1758685168),
(4121, 145491, 140, '发送邮件告知在MIC后台和WhatsApp都发送了照片和视频', 1758685296),
(4122, 141432, 149, '资金不足，265美金不付 要参观工厂，给他要意向金也不给', 1758685354),
(4123, 143873, 126, '9.19客户说需要两个，已给客户报价；询问客户地址，计算运费，客户未读未回', 1758685501),
(4124, 141463, 149, '资金不足，推荐最小的液体灌装机，售价 850 美元，未回复 营销', 1758685699),
(4125, 141658, 149, '打电话未接通', 1758685726),
(4126, 139688, 122, '9.22联系不回\n9.23客户确认细节，找了个中国人联系我，确认了一些工厂的信息。晚上更新了发票。', 1758685792),
(4127, 141887, 149, '阿里未回信息，邮件未回， 重发邮件', 1758685863),
