(4133, 145961, 133, '已报价，提供两种车的报价', 1758686724),
(4134, 141953, 149, '超出客户预算，客户知道当地甘蔗机代理商的价格，后来没回复我', 1758686943),
(4135, 142562, 137, '客户正在办签证，登记我们地址信息，来2个人。', 1758686953),
(4136, 138829, 164, '问网上价格免运费就，解释，售卖咖啡，1个人，预算2千美金，推荐圆拖 报价CIF', 1758687243),
