(4138, 146117, 133, '已发送报价邮件', 1758687401),
(4139, 143052, 149, '客户说刷卡系统每月月租费太贵，硬币系统当地回撬开设备，要他们当地的刷卡器，正在问银行刷卡器接口文档协议，一直不回复', 1758687466),
