(4142, 145892, 127, '9.23已连接上发了价格表和视频供客户选择，昨天和今天的消息还是未读状态', 1758693070),
(4143, 146005, 127, '客户看中平台大的那款，报了实际价格觉得和平台价格相差太大。给他推荐小一点的便宜的圆拖，已读未回。再发消息还是未读状态。晚上等客户苏醒继续跟进。', 1758693209),
(4144, 146026, 127, '早上发了信息还是未读，现在应该刚睡醒，继续链接', 1758693311),
(4145, 146179, 141, '客户要20台外卖机器人。 已报价。', 1758693361),
(4146, 146027, 127, '发了介绍和产品视频，显示未读，还没连接上', 1758693423),
(4147, 144343, 120, '9.22 客户未回复，留言发现变单钩', 1758693566),
