INSERT INTO `crm_comment` (`id`, `leads_id`, `user_id`, `reply_msg`, `create_date`) VALUES
(4151, 145599, 146, '9.23跟客户联系了。客户之后问了一些关于物流，我们可以帮他解决。9.24跟进了问客户采购计划，客户回复，跟进', 1758693998),
(4152, 145592, 146, '9.23客户想要专门用于睫毛的自动售货机，向客户进行了推荐并解答一些问题，最后客户问完支持方式之后下线9.24跟进，客户未回复，晚上打电话看看情况', 1758694177),
(4153, 144729, 133, '已发送报价单', 1758694459),
(4154, 144058, 141, '23号客户问题后 沉默， 去阿里上搜很多产品。 打电话和发信息 说不感兴趣了。', 1758694479),
(4155, 143931, 149, 'ws未回复，电话还是未通', 1758694660),
(4156, 145499, 146, '9.22客户询问价格，给客户说网站价格就是实际价格，然后又问了运费，然后说晚点会联系我。9.23跟进了一下，已读未回，9.24又跟进了，并进行了促销', 1758694799),
(4157, 138829, 164, '需要比价 营销公司工厂', 1758694853),
(4158, 145872, 180, '9.23 客户需要40尺3室 发了相应的照片和彩绘图 ，根据客户需求发了内部测量图 询问供暖系统以及墙板材料、屋顶材料等', 1758695245),
(4159, 67396, 82, '9.24给客户发信息未回', 1758695261),
(4160, 145722, 180, '9.23 发20尺2室和对应照片，询问客户的采购计划，已读不回', 1758695288),
(4161, 145725, 180, '9.23 根据客户需求推荐YG-HY200,并计算运费，口头报价，客户已读不回，询问是否满足客户预算', 1758695317),
(4162, 145414, 180, '9.22 客户是刚开始创业 给客户发了视频照片和砖形图 客户已读不回\n9.23 客户回复消息 跟进客户\n9.24 查询运费', 1758695354),
(4163, 145080, 180, '9.22 客户要照片 给客户发送照片 客户未上线\n9.23 营销客户 已读未回', 1758695411),
(4164, 140183, 180, '法国干冰清洗机\n9.19 询问客户考虑的怎么样了 折扣营销 客户已读不回', 1758695513),
(4165, 140183, 180, '法国 砂浆喷涂机\n9,12 跟进客户 介绍加询问客户需要柴油还是电动\n9.14 用途信给客户打电话 客户没接，用Whatsapp给客户打电话，没接\n9.15 给客户发邮件 Whatsapp上跟进客户\n9.23 询问客户需求，客户未上线', 1758695574),
(4166, 140183, 180, '北爱尔兰 干冰清洗机\n9.12 给客户营销别的客户的发货照片\n9.15 询问客户的采购计划\n9.24 营销放假通知', 1758695638),
(4167, 142859, 180, '9.19 问客户目前的采购计划 ，又发了折扣价的营销，客户已读不回', 1758695681),
(4168, 136773, 180, '9.8 问客户是否收到报价单 客户已读不回\n9.16 给客户营销发货图片 客户已读不回', 1758695934),
(4169, 145881, 180, '9.23 RFQ报价，给客户发照片视频等 客户未读', 1758695977),
(4170, 145085, 146, '9.22客户看了看内部图片，确定了3米拖车，9.23问了问配置和加一个平底煎锅的价格，并提到亚马逊金融选项，并提到要视频通话9.24跟客户表明时间，找个时间给客户视频通话', 1758696008),
(4171, 146165, 161, '已建档，客户在美国，费城开花店，需要一个冷库保存鲜花，核实需求并报价', 1758696183),
(4172, 146033, 164, '已问基本需求，发邮件', 1758696405),
(4173, 146165, 161, 'Cold storage for flowers\nDimension: 20ft * 10ft * 10ft (L*W*H)\nTemperature range: 35-40℉(adjustable)\n跟客户口头报价了，客户说不需要房间，只要机组。经确认客户有房间并含保温，只需要机组，两个厂家只有海特瑞思给了报价，富澜德多次催问没反馈。等厂家技术回复改美国电压费用', 1758696662),
(4174, 146155, 127, '打电话沟通要和他确认细节问题，WhatsApp上的消息还是未读状态，等客户苏醒继续跟进', 1758696764),
(4175, 145472, 163, '客户要汽车美容品自动售货机，给客户发了5个型号，图片视频，等客户回复，\n下午客户上班打电话', 1758696844),
(4176, 144137, 149, '联系不上 重发信息未读未回复', 1758697097),
(4177, 145900, 164, '已发基本信息 已打通电话 5吨产量，不确定是天还是小时，让发信息，未回复 问工厂尺寸', 1758697149),
(4178, 144273, 141, '客户未回应。 各2天给客户发信息 ， 不回应。', 1758697202),
(4179, 143428, 141, '客户说明年采购， 他在明年 6-9月使用餐车', 1758697256),
(4180, 146059, 149, 'ws未回复，已重新发送邮箱', 1758697531),
(4181, 145719, 149, '营销没读没在回复', 1758697746),
(4182, 145693, 149, '未读未回复，', 1758697808),
(4183, 144998, 146, '9.23讨论了支付方式、运费，客户提到想让我们送到点额外的东西，已经承诺送他玉米饼和玉米，意向较强，9.24跟进了一次，暂未回复', 1758697949),
(4184, 144997, 146, '9.24进行了跟进，客户暂未回复，晚上给她打个电话看看', 1758698255),
(4185, 145908, 133, '应该是被拉黑了，WhatsApp刚开始发消息是单钩，客户上线一次之后发消息都是单钩了，打电话没人接', 1758698316),
(4186, 146197, 145, '客户要5米的拖车，纠结价格，解释完之后客户依旧想要5米的，询问一些设备，客户睡觉了。明天继续沟通（9.24）', 1758698367),
(4187, 145901, 134, '给客户报完价格之后，客户想要更便宜的，我给他看了最便宜的 他还是想看别的，我给他推荐速卖通分期付款', 1758698401),
(4188, 145512, 145, '链接四千多美金 客户要3个，报完价格后客户说诈骗，情绪激动，找运营说诈骗，情绪激动，说不想浪费时间，不再回复了（9.22）', 1758698440),
(4189, 145519, 164, '想要成为我们在欧洲的代理，要最高的配置，推荐艾玩冷冻款，报价，想要在欧洲推广，报价CIF， 问易损件，计划10月份购买，计划来看厂，建议先购买一台，生产好后来验货，问设计，约视频看厂，因台风厂家今天休息，计划明天打视频', 1758698453),
(4190, 145654, 145, '客户询问13英尺 ，价格不太接受，想要10尺的，接受价格，还需要一些设备，做了报价单，客户要继续添加一些设备。重新做报价单，等待客户确认（9.24）', 1758698537),
(4191, 145225, 145, '医药类冻干机，客户还未回复邮件（9.22） 隔天继续写邮件跟进', 1758698574),
(4192, 143480, 150, '9.20 客人一直没回复，口头报价三米的价格5000多美金，还没回复', 1758698615),
(4193, 145112, 145, '客户说周五一定付款，但现在要更改地址到墨西哥，已重新报价 客户下线，明天继续沟通（9.24）', 1758698619),
(4194, 144875, 145, '客户要每天生产1吨方形冰块，已报价，客户要门到门，已报价，客户太忙，上线时间短。约好了9.25继续沟通', 1758698664),
(4195, 143480, 150, '9.22 营销客户没回，没上线\n9.24 温馨提示客户国庆订单多等之类的，还没回复', 1758698768),
(4196, 144685, 122, '9.20-24还未联系上，信息不回，电话不接。', 1758698881),
(4197, 145655, 121, '今天下午给这个客户打了电话，这个客户挺好的，我也找到了鑫之源的厂家，厂家很支持，也有很多澳大利亚的案例，非常有利，客户问了运作视频和交期，我发了视频过去，并跟客户确认了一些需求，暂时还没有给客户报价，这个客户还挺好的，打电话声音也特别开朗，接下来客户确认完产品尺寸后，就往下推进', 1758699003),
(4198, 145194, 122, '9.22已发视频参数等供客户参考，客户选型号。\n9.24跟进并报价，客户还未回复。', 1758699053),
(4199, 140315, 150, '9.13 客户需要储存空间，与冰箱，已推荐并报价，加上冰箱的价格为6730美金\n9.15 客户需要滑动窗户，报价滑动窗户需要额外增加200美金\n9.16 邮件回复要滑动与服务窗二者兼得，表示可以\n9.18 客户找到网站价格低，报价与网站价格相差过大，给客户解释网站价格仅供参考。\n9.20 给客户表示抱歉造成误解国庆前订购可以获取200美金优惠', 1758699149),
(4200, 144756, 137, '没有联系上', 1758699406),
(4201, 145091, 160, '个人创业 触摸屏零食饮料售卖机 已发pi 顾客对网站上价格感到疑惑 已解释 并优惠了150美金 视频参观公司 工厂 顾客计划下月底购买', 1758699654),
(4202, 145122, 160, '3米方拖 已报价 顾客可能感觉价格有些贵 已详细解释餐车免费配备的基础设备 尝试给顾客推荐更便宜的款式', 1758699899),
(4203, 145572, 160, '已加WSP但是顾客信息已读不回 已发送照片和视频 正在等顾客确认详细细节', 1758700163),
(4204, 141678, 127, '想通过代理免费买机器卖，我让他先买一台试试，客户说还想再选一选烤箱。', 1758700350),
(4205, 144793, 152, '9.24 途信电话未接通，WhatsApp信息未读', 1758700392),
