(4211, 144985, 136, '客户想要小的方拖，但是想要链接中显示的所有设备，为客户报价三米和四米的价格，以及制作文档报价图片上呈现的设备价格，客户了解了大致需要七千美金，询问餐车内包含的设备，告诉客户基础设施，相应的定制会有相应的价格暂无回复，今天早上再联系，暂无回复', 1758700730),
