(4220, 145785, 161, '需要回复客户的问题，客户说在当地找到了，打电话没有接，强调我们的优势并问客户是否已经在当地购买，消息单钩了', 1758701669),
(4221, 71699, 164, '已发邮件，暂未回复，二次跟进\n我们正在冷冻毛鳞鱼和鲱鱼。理想情况下，我们每小时的冷冻量可达15吨。我们的工厂面积约为6000平方米。然而，由于大部分区域都是雪蟹加工厂，因此空间有限。我们希望尽可能减少占地面积。\n按产量要冷冻库，或者2-3台5-6吨的双螺旋，跟客户确认配置 未回复邮件，再次邮件跟进，电话未打通\nwhatsapp,邮件再次跟进 目前项目暂停，预计2026年重启', 1758701706),
(4222, 143220, 136, '客户还没有回复，打过一次电话，没有接，今晚再打', 1758701924),
