(4228, 143220, 136, '以上跟进信息错误。         \n给客户发送多款信息，客户给老公商量，想要网站链接选择内部设备，引导先选择款式再说设备，选择方拖款式，双窗或者带栅栏的，然后询问做什么生意不来推荐设备，当时联系到的时间较晚，后来客户睡着了，第二天再联系没有回复，后来再联系没有联系上', 1758702465),
