(4464, 142089, 158, '9.23给客户打电话未打通，营销先排单，尽力保证在圣诞节让他前顺利收到货物.\n9.24营销工厂制作中的拖车，问付款是否遇到了问题？\n9.25客户说自己太忙了，但还想购买，要确认这一切的合法性，发了网站和营业执照，发了客户好评。解释了不通过亚马逊的原因。发了自己录的公司视频。客户说明天让银行看看我发的一切的合法性。', 1758790632),
(4465, 146466, 163, '9.25 阿里后台发送图片视频，等回复，客户还未读', 1758790667),
(4466, 146630, 125, '24号了解客户需求后，给客户报价并解决问题，询问客户何时使用，客户说尽快，给客户拟定了阿里付款链接，客户使用信用卡支付。催促客户下单，客户说他收到了其他供应商的报价，比报的低很多，向客户要报价单。客户说考虑一下，明天给我答复，给客户对比分析了我们产品的好处，客户下线了', 1758790853),
(4467, 145080, 180, '9.24  客户一直没上线，给客户打途信电话，客户说他现在上线 ，给客户查询运费，之后发消息没回复', 1758790959),
(4468, 145660, 144, '给客户发送了产品目录，问客户想要哪一款没有回复，还有给客户发送了金秋大战的活动图片，并介绍了活动，目前没有读，等客户回复', 1758791104),
(4469, 145956, 158, '9.24给客户推荐了几款，报过价格后客户就不在回复了。\n9.25未回复，发消息营销。', 1758791167),
(4470, 145172, 144, '问客户一些电压还有一些基础的问题，客户没有回复，所以直接根据产量推荐了一款产品，报了价格和参数，等待客户回复', 1758791172),
(4471, 146689, 125, '25确定客户需求后报餐车运费以及设备的价格，客户计划1个月后使用，向客户解释餐车生产以及海运时间，建议客户尽快购买，客户还未读', 1758791340),
(4472, 145941, 158, '9.23给客户打通了电话。介绍了拖车形状，尺寸。\n9.24问客户3+1水槽选择哪一款？未回复。\n9.25给客户报了拖车+水槽+空调的价格。客户说要求到门，运输代理不提供这项服务，问是否能接受到港?未回复。', 1758791528),
(4473, 144763, 144, '9.22：给客户发送了邮件，回答了客户的问题，问客户想要多少尺寸的披萨客户没有回复', 1758791622),
(4474, 146450, 125, '运送到西雅图的费用为 230 美元。\n价目表：\n总价：7,940 美元 + 750 美元 + 600 美元 + 450 美元 + 650 美元 = 10,390 美元\n3 米餐车：7,940 美元\n发电机：750 美元\n3+1 水箱（包括 100 升饮用水箱和 130 升废水箱）：600 美元\n华盛顿标准抽油烟机：450 美元\n冰箱：650 美元\n25给客户报完价格，客户预算不足，说要筹钱，建议客户可以先交定金，先安排生产，发送水单营销，客户已读不回；明天继续营销跟进，必要时给予折扣', 1758791638),
(4475, 146331, 125, '客户没WhatsApp，给客户发送邮件了，客户未回复，给客户打电话。', 1758791699),
(4476, 146151, 68, '1: 已发图片和视频，问要几个货道 多大尺寸', 1758791791),
(4477, 143411, 144, '给客户发消息，客户不回复，还是单勾，感觉客户把我拉黑了', 1758791814),
(4478, 146331, 125, '打了两个电话，都打不通，再打电话尝试联系', 1758791897),
(4479, 144240, 144, '客户一直没有把报关货代的联系方式发给我，给客户发消息要联系方式已读不回，打算今天晚上打电话', 1758791906),
(4480, 142980, 154, '跟进发邮件没回', 1758791915),
(4481, 146200, 68, '1： 已联系，正常跟进', 1758791922),
(4482, 145988, 123, '0924发邮件推荐客户2.2米款式，发送标配价格；加客户WhatsApp为客户计算运费\n0925报运费，客户想要大一点的，报2.8米圆拖，客户说当地的价格更低，营销质量，推荐2.5米，客户已读未回', 1758791943),
(4483, 143792, 93, '9.17想要初次投资纸杯机以及塑料袋机，介绍纸杯机发送价格，表示要找最低价格\n9.18聊到塑料袋机，发送视频图片以及报价单。客户表示需要在土耳其以及中国继续找一下适合他预算的机器，表示希望之后并在我们这里购买能找到适合他投资的机器', 1758792083),
(4484, 146107, 123, '0924给客户发送了不同款式图片，打电话沟通，客户主要担心拖车能否符合美国标准，营销我们已经出口过很多；给客户发了型号列表供客户选择，暂时未回复\n0925计划问客户喜欢哪个款式', 1758792119),
(4485, 143628, 93, '9.17发送邮件介绍不同储存类型的折叠房未回复\n9.19发送折叠房他给售前同事要求的折叠房安装视频并表示邮件无法发送较大的视频，索要whatsapp,未回复\n没联系上', 1758792129),
(4486, 146165, 161, '给客户发了图片和口头报价后，并告知我们也有鲜花售货机，并发视频。下午根据厂家提供的报价修改报价单发给客户', 1758792173),
(4487, 143904, 93, '9.18发送折叠房图片视频，了解客户需求，客户表示要20尺两卫两卧室，以及安装视频，询问亚马逊标价问题，解释后想要40尺两室两卫，报价后查询到门运费并报价，客户表示想知道我是可以放入多大的床，介绍后客户有发送带有金属雕花板房子链接，重新报价后聊到付款方式，客户想通过亚马逊付款。介绍亚马逊平台手续费建议银行转账或阿里平台支付，发送其他客户水单并进行营销，未回复（客户没钱，想通过亚马逊付款融资）', 1758792173),
(4488, 146644, 161, '初步留言客户要机器的价格，发了半自动的产线视频，问下客户的需求，要产线还是哪些机器的价格，等回复', 1758792204),
(4489, 144027, 93, '9.18介绍折叠房未回复\n9.19回复对两个卧室感兴趣，报价以及查询运费，发送40尺两室平面图以及详细报价单，已读未回\n9.20讨论付款方式，发送其他客户支付水单，询问具体信息为他做形式发票\n9.22营销美国成交客户房子\n9.24营销中秋节团队合照，邀约视频\n9.25视频通话介绍公司，询问采购计划', 1758792248),
(4490, 146764, 161, '问下客户的具体需求，并索要联系方式', 1758792264),
(4491, 144427, 93, '9.19 询问是否可以定制印刷机，回复后平台认定该客户为诈骗钓鱼其账号被平台管控', 1758792280),
(4492, 144881, 158, '9.21给客户打电话打通了，发消息推荐款式不回复\n9.22客户说方形的拖车，问多少人使用者辆车，不回复\n9.24告诉我1个人，给客户推荐尺寸，不回复\n9.25我已经给客户发信息。', 1758792317),
(4493, 144682, 93, '9.20介绍全自动半自动卫生纸机生产线\n9.21回复对半自动感兴趣，介绍切割不同宽幅的机器，推荐1880型号\n9.22发送半自动报价单以及视频，未回复', 1758792318),
(4494, 144684, 93, '9.20发送邮件以及平台回复，发送视频，询问餐车长度及设备要求，未回复', 1758792338),
(4495, 145365, 93, '9.22介绍20尺2室房子，报价DDP13400，客户预算8500USD，他要20尺寸且价格便宜，向他营销公司以及解释价格，未回复，被客户拉黑了', 1758792367),
(4496, 145475, 93, '9.22介绍50米小蓝并报价，客户想要100米的，报价100米\n9.23营销客户小蓝钻反馈\n9.24主动提出折扣，报价3630美元，发送报价单，未回复', 1758792403),
(4497, 145540, 93, '9.22报价30-40T液压剪价格，30000美元，营销厂房，客户价格已经反馈给部门\n9.23营销液压剪运行视频，未回复\n9.24营销公司团队成员照片未回复', 1758792423),
(4498, 140481, 161, '成功跟安徽唯嵩光电取得联系，确认细节推荐机器。厂家提供了机器的图片，视频和口头报价，给客户回复，客户没有说上来就说贵，继续沟通。跟客户交代不同的设备筛选不同的果径范围，超过了就要上两台设备，一台不行，客户还在找一台设备能处理不同果子直径范围的机器。', 1758792434),
(4499, 146341, 93, '9.24 3-5吨液压剪报价用于滑移装载机，又询问2吨价格\n9.25 联系报价运输费用，3-5吨运费150美元，2吨运费100美元，给予免运费优惠，等客户回复', 1758792465),
(4500, 143070, 154, '给客户新找了一款咖啡机，和客户确认咖啡机类型，客户没上线', 1758792641),
(4501, 144926, 155, '昨天给客户在WhatsApp上打了电话，接了打了一分钟，客户在比价商量，跟客户约了看公司明天早上可以给客户发个消息问问有空没', 1758792810),
(4502, 146438, 133, '加客户微信，还未同意', 1758792948),
(4503, 143151, 155, '9.23号给客户打了电话客户接了十几秒就挂了，然后发消息说很忙，忙完会回复，营销了公司活动，客户已读不回到今天', 1758793004),
(4504, 143889, 158, '9.22问有任何进展吗？营销公司搞活动，客户说尚未做决定，有消息会告诉我。\n9.25营销工厂里的拖车在生产中...', 1758793125),
(4505, 143475, 155, '24号上午问了我给他的价格和阿里巴巴的一样吗，我回答了并用金秋大战营销了公司说可以给他打折扣150美金并修改了报价单发过去了，客户昨天晚上已读不回', 1758793168),
(4506, 145228, 155, '刚刚在WhatsApp上打电话客户没接挂断，留言未读未回', 1758793305),
(4507, 143264, 154, '聊到了付款，整体推展进度还行，客户在犹豫ddp，客户交的运费高，cif,客户嫌麻烦又怕清关费用会很高，给客户再次列明了我们为他担心的地方做出的努力，能给的优惠，等回应', 1758793568),
(4508, 143073, 122, '9.24预算不足，客户不再购买。', 1758793604),
(4509, 145600, 155, '已经给客户报了中吉家三款自动售卖机并发了参数和价格，客户询问了最便宜的一款并询问了支付模块的机器，现在是在确认机器价格流程，还没有问客户地址和算运费报价单，客户一般是在法国的下午晚上会回复我上线，咱们这边就是六七点往后了，有几次回复都在凌晨。', 1758793786),
(4510, 145789, 155, '今天才联系上，打电话之后转到WhatsApp上聊之后，报过机器价格后已读不回。', 1758793899),
(4511, 143408, 154, '后续跟进进度：本来约好了电话，客户爽约了。后来发些营销的内容客户突然开始已读不回了。我问她是遇到什么问题了吗，很担忧，客户今天回复说是她的丈夫已经在当地租了一辆餐车先进行测试。如果后续效果好会再买。目前暂停这个项目。我回复客户说我会不定时更新我们的餐车情况和她的餐车做对比，有啥优惠也会及时跟她更新', 1758793911),
(4512, 143408, 154, '后续跟进进度：本来约好了电话，客户爽约了。后来发些营销的内容客户突然开始已读不回了。我问她是遇到什么问题了吗，很担忧，客户今天回复说是她的丈夫已经在当地租了一辆餐车先进行测试。如果后续效果好会再买。目前暂停这个项目。我回复客户说我会不定时更新我们的餐车情况和她的餐车做对比，有啥优惠也会及时跟她更新', 1758793911),
(4513, 143408, 154, '后续跟进进度：本来约好了电话，客户爽约了。后来发些营销的内容客户突然开始已读不回了。我问她是遇到什么问题了吗，很担忧，客户今天回复说是她的丈夫已经在当地租了一辆餐车先进行测试。如果后续效果好会再买。目前暂停这个项目。我回复客户说我会不定时更新我们的餐车情况和她的餐车做对比，有啥优惠也会及时跟她更新', 1758793911),
(4514, 143770, 154, '后续：客户爽约后，再和他约约不上，客户不会说英语，打电话交流不了。我私信问他是遇到了什么问题了吗，客户没读', 1758794086),
(4515, 144018, 154, '后续：打电话未接，发消息未读。进度暂停到运费', 1758794142),
(4516, 139003, 137, '保持联系，客户依旧不确定。', 1758794142),
(4517, 144213, 154, '后续：客户确实在比价，我把咱们的优势发给他后，今天问了我咱们的价格，我给她发了一个详细的报价，客户还没读', 1758794214),
(4518, 139654, 137, '客户说，他们老板决定扩大产业，2026年在确定', 1758794267),
(4519, 144898, 154, '后续：客户不上线，电话没接', 1758794437),
(4520, 145082, 137, '客户已去比价', 1758794561),
(4521, 145124, 154, '后续:没读，但这个还没打电话，可以明天早上大哥电话', 1758794588),
(4522, 70398, 43, '我们正在调查土地、水费、房产税和交通费超出预算的原因。由于现在无法支付，我们将等到有能力支付为止。营销', 1758795186),
(4523, 145944, 155, '昨天打过电话，接通了，聊了三分半，说可以在阿里巴巴上聊天有关内容，给客户留言未读未回，今天下午又打了电话没接', 1758795272),
(4524, 144796, 156, '客户经纪人没有联系我，我直接给客户报了6台的价格，未读\n厂家说了电车不好进欧美，也上不了车牌', 1758795514),
(4525, 125208, 43, '暂时没预算', 1758795545),
(4526, 146482, 155, '今天下午四点半给客户打了电话接通了，客户要我发价格参数给他，发了客户现在未读未回', 1758795557),
(4527, 146444, 156, '给客户发了邮件，报了机器价并回答客户问题，客户未回复，明天继续发', 1758795917),
(4528, 144901, 155, '厂家还是没有发报价，太慢了说是需要细算', 1758795960),
(4529, 146360, 155, '客户说要三辆拖车，并在WhatsApp上发了图片说自己是大厨包括ins、facebook有关图文的截屏，还发了他自己有一辆卡车改造的餐车，给客户已经报了5m便宜款方拖（包括2.5m围栏）的价格，设备的价格还没有报，询问客户设备是否符合他的需求发了个OK就不说话了。', 1758795991),
(4530, 146681, 134, '打电话无人接通，已经邮件联系', 1758796196),
(4531, 139184, 161, '营销金秋活动照片，客户说还在找放置机器的地方，提出下单后需要两个月才能收到，这段时间可以寻找合适的地方', 1758796852),
(4532, 146398, 127, '报了一款便宜的半自动生产线套出客户预算在50000-70000美金之间，在等他发他要做的薯片成品以及包装克重。', 1758797340),
(4533, 146485, 147, '客户做炸鸡，对认证很敏感。但是没有经验，需要确认细节。', 1758797488),
(4534, 146471, 147, '发了消息，目前没有回复。下步打电话', 1758797510),
(4535, 146419, 147, '客户要蛋白粉售货机，但是对蛋白粉更感兴趣', 1758797548),
(4536, 146395, 134, '印度客户，已经给他报价，意向比较强回复积极，已报价，等待客户回复', 1758797592),
(4537, 146396, 147, '客户对亚马逊很信任，已经报了方拖，客户不喜欢，喜欢页面上的款式', 1758797601),
(4538, 146254, 147, '要脱杏核和核桃，给客户推荐了款式，是中间商', 1758797634),
(4539, 145718, 147, '要在亚马逊付款，尝试说服客户', 1758797653),
(4540, 144550, 147, '给客户日常问候', 1758797680),
