(4542, 135695, 147, '给客户协商，让客户重新付款', 1758797777),
(4543, 146077, 139, '昨天晚上打了电话，客户没有接通', 1758798078),
(4544, 146063, 139, '向客户营销发了一些餐车图片和视频，等待客户回复，晚上准备再次打电话', 1758798116),
(4545, 146789, 140, '已发送邮件询问客户需要的餐车长度，可定做从两米到十一米，不确定的话可根据人数推荐长度', 1758798139),
