(4669, 146680, 165, '客户想购买披萨机放到摩尔多瓦，只有20000欧元，但是想一次买很多台，想要分期付款', 1758851862),
(4670, 146413, 126, '9.25已给客户发餐车的照片和视频，告诉客户餐车内部配置，客户未回消息\n9.26客户未读未回，给客户打WHATAPP没人接', 1758851870),
(4671, 139689, 153, '营销两天后发现客户想要的是餐车；目前已营销国庆优惠活动，客户来访以及餐车照片', 1758851912),
(4672, 146795, 163, '给客户发送基本信息，发送半自动生产流程图和视频', 1758851921),
(4673, 144605, 156, '昨晚给客户打了语音电话 直接秒挂，到10月份再继续跟进看看', 1758852009),
(4674, 146179, 141, '客户看到阿里网页最低标价4200美金 ，此价格属于另一款机器人。 客户嫌街道机器人价格贵， 客户反馈说他找到了 真实工厂价格。', 1758852057),
(4675, 138871, 119, '9.10客户说比较了一下机器的价值和带来的收益，说不值当\n9.11回复话术后已读不回了\n9.13营销\n9.17尝试推荐零食饮料自动售货机\n9.18明确表示不需要', 1758852109),
(4676, 146404, 157, '9.26 没有WhatsApp，发送邮件，待回复', 1758852114),
(4677, 143183, 141, '给客户打了视频， 重新给客户发价格 和报价单。 目前还没反馈。', 1758852136),
(4678, 146595, 157, '9.25 发送基本信息，沟通关于机器细节，发了两款，对方还没确认款式（想要放花束，8格或者12格）', 1758852237),
(4679, 144888, 137, '打电话沟通，客户明天给搭档开会商量情况。', 1758853152),
(4680, 144667, 157, '9.24 发送了报价和运费 未回\n9.25 发消息 对方说已经查看了消息，要和团队一起商量（想买两台或两台以上）', 1758853299),
(4681, 145771, 124, '9.24 营销公司金秋大战活动视频，表示欢迎客户来参观\n9.26 营销西班牙客户银行水单，询问客户改装餐车进行的如何', 1758853475),
(4682, 134742, 149, '重新营销客户', 1758853498),
(4683, 146829, 173, '目前一直没联系上', 1758853564),
(4684, 146366, 173, '9.25 回信息了，并且沟通了需求，给客户推荐了方案，给了设计图和报价单。客户表示自己也是匈利亚的中介，需要跟他的客户交谈然后给我反馈', 1758853699),
(4685, 145937, 173, '9.25 客户没有回消息，但是跟客户的货代朋友沟通了，表示客户也是干外贸的，需要跟自己的客户转接，然后这两天反馈情况。', 1758853785),
(4686, 145597, 173, '9.24-25 一直没有回消息 没上线 消息未读，联系不上。', 1758853825),
(4687, 145530, 173, '9.25 给了第二个较大产量的生产线。客户未上线，未读。', 1758853974),
(4688, 143620, 137, '打电话拒绝，客户发消息依旧在了解确认，有消息与我们联系。营销餐车工厂视频，以及其他款式。', 1758854040),
