(4695, 145566, 123, '0925 打电话未接通\n0926 问客户需要的拖车长度', 1758854376),
(4696, 143378, 173, '9.20 进行了一次交谈 客户表示未付款的原因是他想要其他款式，又根据她的需求推荐了其他款式，然后后边的消息客户一直处于已读但不回的状态。', 1758854452),
(4697, 146493, 123, '0925打电话 接通在WhatsApp上沟通，确认需求报价，客户觉得贵，营销产品质量，帮客户免费送到佛山仓库，客户说考虑再联系', 1758854543),
(4698, 143047, 173, '9.25 客户回消息 确定了款式 表示要和团队进行沟通，交流。', 1758854634),
(4699, 143045, 173, '9.20 客户有确定了款式 说只是想先了解一下 还是要跟伙伴商量一下 后边消息一直未读', 1758854875),
(4700, 141715, 173, '9.20-9.26 一直未上线 中间也打过电话 视频 都没有接 消息也没有回过', 1758854946),
