(4702, 139250, 137, '客户一个星期没上线，电话没接。', 1758855009),
(4703, 141609, 173, '目前处于失联状态', 1758855027),
(4704, 141141, 173, '9.19-9.26 有持续跟进 客户未回消息', 1758855059),
(4705, 140907, 173, '9.20-9.26 客户一直在住院', 1758855121),
(4706, 146953, 68, '1: 已发定制款图片和客户反馈图片营销，问喜欢哪个款式', 1758855255),
(4707, 140690, 173, '9.11 表示 需要征求妻子同意\n9.12 表示很忙在搬家\n9.13 表示忙完和妻子商量好会回复我', 1758855320),
(4708, 144971, 123, '0923营销工厂视频\n0926营销客户来访', 1758855479),
(4709, 140670, 173, '9.11 客户又确定了一些款式细节\n9.12 客户表示在申请许可证\n9.13 客户表示确定好一切会下单\n9.14-9.16 我每天给她发消息 都是回复在确定场地\n9.17-9.26 持续跟进 但消息都是已读未回', 1758855498),
(4710, 140303, 173, '9.11 客户又确定价格问题\n9.12 问了22个细节问题 解答后问其付款方式，表示现在只是了解 等资金准备好了会购买', 1758855611),
(4711, 139967, 173, '9.10-9.26 中间持续跟进，一直未回消息', 1758855647),
(4712, 139164, 173, '一直没上线过 失联', 1758855703),
(4713, 138406, 173, '一直联系不上 失联', 1758855797),
(4714, 138313, 173, '9.25客户突然出现表示 买到了十台和我们一台一样的价格 表示不再考虑我们。严重怀疑是托词', 1758855860),
(4715, 137977, 173, '一直未回消息', 1758855945),
(4716, 147018, 68, '没有WhatsApp，已发邮件', 1758856317),
(4717, 143454, 145, '失联  联系到之后客户说在当地购买了', 1758856613),
(4718, 146497, 68, '1: 发了图片和视频，问了卖什么产品', 1758856922),
(4719, 146710, 152, '9.25发送图片以及名片，询问客户想要餐车类型以及几个人使用，得知客户想要用于咖啡售卖，三个人用，向客户推荐了四米长，客户不理解方拖及圆拖，向客户发送了方拖视频以及圆拖图片，询问他想要哪款，客户未读信息。9.26看到客户在线给客户打视频客户未接，后又向客户发送我们正在工作的视频，向他问候。', 1758857042),
(4720, 144331, 153, '营销国庆折扣活动和机器视频', 1758857353),
(4721, 144977, 153, '运费已报价，客户中间找到鑫之源的厂家，给予了更大的折扣，机器1120+刷卡器480+空运399，总计1990美元，价格没优势就着重强调了咱的机器质量和售后，客户接受度挺高，想要一个支付视频也已发送', 1758857616),
(4722, 146954, 68, '2：要按键的额已报便宜款', 1758858215),
(4723, 144793, 152, '9.25向客户发送了公司的营销视频以及告诉他我们开始工作了，询问客户有什么顾虑可以告诉我，我可以帮助他，客户表示他仅仅是有这个计划并在分析这个计划，如果需要会联系我。晚上向客户发送了工厂视频，客户已读未回。', 1758858276),
(4724, 145949, 153, '客户想要双滚筒机器，已推荐了一个一个桶喷油一个桶裹粉的机器，报价4600美元，利润32左右，已发送报价单客户已读不回，准备打视频沟通', 1758858492),
(4725, 146036, 152, '9.24晚上11：40打途信电话未接。9.25早打途信电话未接。9.26早打途信电话未接。', 1758858619),
(4726, 146132, 153, '打视频未接，已营销金秋优惠活动', 1758858654),
(4727, 145764, 156, '报完DDP客户一直没反应，应该是觉得价格高，已建议客户选择到港，价格便宜，我们也会帮助他清关，目前未回复', 1758858686),
(4728, 139244, 152, '9.19发了名片但未回，后发了餐车图片向客户推荐几款餐车询问他的需求，未读。\n9.26，继续跟进客户询问客户是否还需要', 1758858824),
(4729, 146897, 71, '已报价，未反馈', 1758858955),
(4730, 144742, 152, '9.24发邮件想起介绍一款产品表明希望收到他的回信，客户未回。', 1758858986),
(4731, 146887, 156, '客户留言要的是油炸售卖机，编辑好客户3个问题和报价后，客户回复要的是零食售货机（放薯片）\n及时发送图片，价格和参数，并询问客户到门还是到港，客户现在要查询信息', 1758859556),
(4732, 145258, 152, '9.25给客户打途信电话，未接通。在WhatsApp向客户发送餐车图片询问需求，未读。\n9.26向客户营销公司，发送公司视频以及工厂视频，期待客户能看到并回复。', 1758859705),
(4733, 146731, 71, '已报价，全自动生产线，给埃及客户找的，可以从台湾付款', 1758859713),
(4734, 146731, 71, '已报价，全自动生产线，给埃及客户找的，可以从台湾付款', 1758859715),
(4735, 143188, 41, '跟客户沟通了20FT和打包箱，客户一点钱都没有，想让我们先给他一个样品，他想在当时推广', 1758859737),
(4736, 146730, 71, '没钱', 1758859737),
(4737, 143917, 172, '9.26客户一直联系不上，继续发邮件等回复', 1758859778),
(4738, 146837, 156, '联系上客户了，客户在山东有工厂。要了4个500L的发酵罐+12板式蒸馏塔，用于威士忌和朗姆酒，出酒精度客40’，目前在等厂家做报价方案。', 1758859911),
(4739, 146036, 152, '在WhatsApp继续询问客户喜欢的款式，并向他表明可以为她定制。', 1758860081),
(4740, 145689, 133, '客户要的是饼干杯，推荐了一款制作饼干杯的机器，价钱满意，问客户啥时候使用，客户就只是想学习了解一下，暂时没有购买的打算。', 1758860173),
(4741, 146309, 152, '9.24在WhatsApp已向客户发送名片并结合客户需求向其发送一些餐车款式，询问客户需求，比如需要多大尺寸等。客户暂未读信息。9.24晚上11：40打途信电话未接。9.25早打途信电话未接。', 1758860192),
(4742, 146437, 156, '客户只是了解不购买，厂家也说目前机器人语音功能和清洁功能结合不了', 1758860196),
(4743, 146858, 121, '这个客户分过来的时候，我看到他跟赛博说希望给他打个视频电话，所以一到公司我就跟他打了招呼，然后尝试打视频电话，打了两个都没有接通，可能是网络不太好，他可能没收到我发的照片，然后就跟他确认需求，他一直在问，你们还有更多的照片和视频吗，然后我猜想他可能不想要拖车，想要动力款的？我就发了一些动力款的图片，随后他给我发了他想要的餐车，是一个基础款的方拖，我们能做，我夸了一句你眼光真好，他就说所以你们没有这个款式？我赶紧说有的，我感觉他脾气不太好，后来他给我发了一大段要求，什么卫生标准啊啥的，我给他解释说没问题，我们都能满足，也有很多美国的客户什么的，我问他要什么内部设备，他说请发过来供我参考，然后我就做了一个报价单，列出了他可能需要用到的烹饪设备，现在他可能去睡觉了，不回复了。', 1758860251),
(4744, 143082, 121, '这个客户我催了几次，一直说有结果会跟我说。这几天也在营销，把我们公司金秋活动的视频还有团建的视频给他营销了，他今天回了一个nice，我明天再问问他进度', 1758860354),
(4745, 146309, 152, '9.26.向客户发送和金秋大会视频进行营销，表达问候', 1758860385),
(4746, 141029, 121, '这个客户属于是一直没上线了，消息没有读过，也没有回复，打电话也打不通', 1758860411),
(4747, 143484, 133, '客户只回复过一次邮件，她要对比多家，WhatsApp发消息未回复过', 1758860445),
(4748, 145084, 121, '我找了一个稍微便宜的给他报过去，但是他说不喜欢降价这么多的餐车，我解释说款式不一样，他还是说不需要了，谢谢', 1758860496),
(4749, 144788, 124, '9.26 客户询问到门到港区别，以及机器保修证书付款相关问题，邮件回复，建议尽早购买', 1758863740),
(4750, 145437, 121, '我联系了几家货运代理，今天给我回复了，我就赶紧做了报价单给客户发过去，客户还在线，但是他说明天回复，我给他报的所有费用里面不含关税，因为光关税要两千多美金，他说他自己去查关税，希望关税不会成为我们的阻碍，这个客户挺可爱的，他给我发的消息都是翻译过来的繁体中文，我给他发西班牙语，哈哈哈，他还有很多表情包，接着跟进吧，还是有希望的', 1758864216),
(4751, 140967, 124, '9.25 营销公司金秋大战活动视频，展示公司实力，问客户预计什么时候购买', 1758864234),
(4752, 145559, 121, '现在给他营销，打招呼都不回复我了，应该是去找能亚马逊支付的厂家了。。。', 1758864272),
(4753, 142053, 124, '9.25 营销公司金秋活动视频，表示欢迎来中国参观公司', 1758864318),
(4754, 146724, 121, '客户来的时候带的有图，我就给他介绍他想要那款，聊的很快，确认完需求他问价格，正好我都能找到，就给他报价了，7800美元左右，但是这个客户说一般都是六千。我说我可以给你推荐别的款式，现在不回复了，接下来我准备直接给他发一个便宜的报价单让他选择', 1758864447),
(4755, 146765, 121, '给我发了机器的图片，他的机器很难找，问了好几个厂家都没有，我需要再找找', 1758864514),
(4756, 145371, 127, '客户想定制一些东西，问他具体是什么没有回复', 1758865193),
(4757, 142277, 127, '客户也找了其他厂家在做对比，正在让厂家根据他的厂房面积出设计图和性价比最高的方案', 1758865605),
(4758, 146459, 71, '已报价，想要先找地方再买机器，圣诞节前，全客户现在买，圣诞节收到货正好赚钱', 1758865794),
(4759, 143151, 155, '今天上午用水单营销了，客户已读不回', 1758866001),
(4760, 142562, 137, '0924引导客户付定金，到公司可以看到现货车。\n0926客户回应，目前不能直接批准这个项目，需要亲眼看餐车，测量确认，顺利进展的话，批量购买。', 1758866175),
(4761, 146950, 174, '客户想要1000公斤每小时的产线，客户有足够的购买能力，但是期待客户的反馈。', 1758866305),
(4762, 146409, 136, '根据客户需求，以及挪威温度低，找到正确机器，发送机器视频信息，报价，客户暂时表现还可以，询问运费，查询运费中', 1758866325),
(4763, 146860, 174, '客户购买意愿强，但是想要双层复式的，标价5400，客户预算8000，威凯报价12000，正在找更多供应商', 1758866383),
(4764, 146411, 136, '给客户发送多个款式，客户正在询问款式价格，正在沟通中', 1758866430),
(4765, 146401, 136, '给客户打招呼还未回应，马上再次联系', 1758866490),
(4766, 139725, 149, '3米餐车 4500美金 报价后不在回复，营销不在回复，18号没在上线过，电话不接', 1758866529),
(4767, 145570, 136, '与客户沟通，最终客户感兴趣最低价格的彩云卷家的款式，降低成本只安装信用卡机，另外沟通付款方式，速卖通或者俄罗斯代理，沟通分期付款，只支持首尾款两次，客户暂无回复，继续跟进', 1758866645),
(4768, 139815, 149, '3米报价 4500美金，客户要到门DDP，八号回复查询运费，运费太贵不回复，营销', 1758866716),
(4769, 144789, 145, '已报价 客户质疑平台价格 已解释 客户询问支持的型号和数量 询问采购时间 客户说要考虑 正常跟进', 1758866881),
(4770, 139815, 149, '营销客户来访，报到港价格', 1758866884),
(4771, 144983, 152, '9.24试图继续联系，给客户在WhatsApp上继续营销发了名片，后发了餐车图片询问他的需求未读。9.25向他营销公司，发送金秋大会视频', 1758866889),
