INSERT INTO `crm_comment` (`id`, `leads_id`, `user_id`, `reply_msg`, `create_date`) VALUES
(4828, 146857, 75, '已经报价并发送产品信息，客户要等他的 客户下单。', 1758870538),
(4829, 147026, 125, '26号给客户报完价格和运费，客户接受了价格（最终价格为 2,780 美元）。客户要增加3种支付方式，说完就下线了；给客户报了3种支付方式的价格和最终的价格，客户还没上线；', 1758870960),
(4830, 146924, 125, '26号WhatsApp给客户发送视频图片，也发送了邮箱，包括参数和价格，客户都还未回复，准备给客户打电话。', 1758871028),
(4831, 144846, 71, '已报价，300米钻机24000美金，中间商，他的客户正在考虑是否买空压机，近期采购', 1758871630),
(4832, 146724, 121, '推荐了一个便宜的款，我问他打算什么时候要机器，他说从不，太贵了，我说我还可以推荐别的，他说不用了谢谢，太冷漠了这个人', 1758871736),
(4833, 123695, 82, '9.26 发信息未回', 1758871757),
(4834, 147079, 153, '联系上后客户只问了在欧洲开展业务吗，趁机营销公司和客户来访询问客户需求，等回复中，', 1758871779),
(4835, 147006, 180, '9.26 发邮件 附带客户需求的尺寸照片', 1758871824),
(4836, 146502, 180, '9.25 跟进客户 询问尺寸 根据地址报价之后 客户已读不回\n9.26 营销放假通知，客户在找当地的货运代理', 1758871903),
(4837, 145679, 136, '与客户沟通需求，给客户发送机器图片视频，报价，客户暂时满意，客户询问是否可以租赁，回复不便租赁，可以看厂，询问运费，报运费，营销，继续跟进', 1758871908),
(4838, 145872, 180, '9.24 客户询问墙体加厚以及价格 屋顶加厚\n9.25 回复客户问题，发送素材清单\n9.26 跟进客户 营销水单', 1758871946),
(4839, 145725, 180, '9.25 询问客户的采购计划，途信和Whatsapp打电话给客户，客户没接\n9.26 客户想去参观我们南非客户购买的机器，营销客户机器图片视频和好评，已读未回', 1758871979),
(4840, 145722, 180, '9.24 问客户关于房子问题，未回复\n9.26 营销放假通知给客户，未读未回', 1758872026),
(4841, 145414, 180, '9.25 询问客户是否增加模具，已读未回\n9,.26 询问客户是什么时候下单，营销放假通知', 1758872081),
(4842, 145080, 180, '9.25  客户一直没上线，给客户打途信电话，客户说他现在上线 ，给客户查询运费，之后发消息没回复\n9.26 询问客户什么时候下单，营销放假，客户已读未回', 1758872110),
(4843, 143579, 180, '法国干冰清洗机\n9.25  客户一直没上线，给客户打途信电话，客户说他现在上线 ，给客户查询运费，之后发消息没回复\n9.26 询问客户什么时候下单，营销放假，客户已读未回', 1758872298),
(4844, 143579, 180, '碎木机\n9.26 邮件回复客户是否已购买机器，可否知道型号等', 1758872333),
