(4848, 144760, 136, '与客户沟通，向客户发送机器图片视频，报价，客户说考虑，后向客户营销，已读不回，现在利润有空间，大致两万多，打算降一点看看客户反应', 1758872755),
(4849, 145211, 136, '与客户联系上，客户说不做薯条薯片生产线，要做香蕉片生产线，说有，不过现在公司举办活动，发送照片，晚点发送相关信息，再次发送香蕉片生产线视频，客户不回，另外客户是否已读隐藏，打电话，没人接', 1758873013),
