(4864, 144779, 136, '与客户联系，客户想要酥性饼干机，发送图片视频，客户询问是否有搅拌的功能，以及询问烤箱，发送的是语音，然后说了一些什么整体的预算什么什么，听不太清楚，给客户分别发送一个常用的型号的搅拌机，饼干机，和烤箱，报价', 1758874507),
(4865, 146061, 122, '9.26目前还未联系上客户。', 1758874831),
(4866, 141077, 145, '只需要浇注机 对比多家供应商 ，客户目标价是成本价，使用低价话术，客户不接招，营销工厂和公司，无果', 1758874836),
