(4884, 146225, 116, '给客户发送了几个灌装设备视频，嫌机器太大，然后更新了一个很小的机器，给客户更新了报价，等待回复', 1758876744),
(4885, 146430, 148, '9.25 确定型号 已报价\n9.26客户问多久能到，能否在亚马逊付款。以引导银行或阿里，还未回复\n邀请打视频，还未读', 1758876833),
