(4913, 145664, 158, '9.23联系到客户，发现客户需要的是冰块自动售货机，发了一些图片介绍。\n9.24客户计划先购买两台，后续会再购买。给客户推荐了7款机器，告诉客户售后和保修，报了2、3型号的价格。 他不想花太多钱，但喜欢贵的款，让我给老板要折扣，报了折扣价\n9.25给客户报了运费，运费很高，但也真诚的给客户解释过了，客户很理解。能接受价格问付款怎么才能不被骗，发了一些公司客户视频营销。回复我需要去了解一下怎样从港口送到住址。\n9.26问情况，客户说有消息会回复我。催款营销说目前即将假期，提前锁定优惠和生产周期。', 1758879792),
