(5005, 147241, 144, '客户挺有实力的，有自己的厂房，客户想要制作3种不同样式的酥性饼干，产量不小比较大，一小时1500kg，已经确认了形状还有厂房的尺寸，目前还在确认加热方式，厂家建议用气，客户想用电，但是还没有跟客户说，客户就去睡觉了，打算第二天在跟客户确认细节', 1758948586),
