(5008, 146821, 144, '9.27：已经跟客户报了价格加上支付方式总共6544美元，客户觉得价格太贵了，还给我发送了当地的机器价格，才2100美元，让他发送图片，被我发现是二手的产品，但是他还是觉得咱们的产品贵，并且一直说速卖通的价格比较低，跟客户解释了好久才说好，最后我跟客户说我在跟老板商量一下，他说ok，\n\n\n接下来打算再找找厂家，有没有便宜的，也跟厂家问了没有便宜的一款，只有这个', 1758951090),
(5009, 146796, 144, '9.27：跟客户确认了一下细节，客户的整个流程，还有想要制作的饺子花型，客户目前对花型没有回复，打算今天在跟客户问一下', 1758951173),
