(5041, 147081, 153, '客户是采购，想购入12英寸披萨的披萨机，已发送包含披萨机参数和报价的邮件，客户查看中。客户想要的机器报价9513美金，运费分别报了到门156美金和到港1960美金，利估30%，客户想要出具一份1960美元包含运输产生的所有费用的书面证明，已发送，客户说周一再聊', 1759021644),
