(5051, 72120, 82, '9.28 为客户起草阿里巴巴链接', 1759022851),
(5052, 147097, 121, '这个客户还挺好的，她之前就是做饼干的，不过他的机器都是手动的，所以想要全自动的包装机，从称重到包装，都是一体式的机器，但是她想做多种饼干，想要那种能立在桌子上的包装袋，我说这些都可以定制，包装袋的尺寸已经确认了，饼干的尺寸他说下周一再给我回复，我联系了两个厂家，价格差的挺大的，我觉得客户的预算估计不太高，等确认完饼干的尺寸，给她抱报一个便宜的价格', 1759023060),
