(5058, 145655, 121, '给客户推荐了一个很便宜的掉落式的机器，不到三千美金，包含刷卡机的价格，客户说喜欢这个，但是不是还要支付刷卡机的费用，我委婉的说，本来是这样的，但是为了促成我们的合作，我跟老板说，这个客户以后还会买更多台机器，老板不情愿的答应了我的要求，同意赠送一个刷卡机，现在还没有回复，我再问问进度。', 1759023443),
