(5069, 147467, 122, '9.28电话视频，是个老头和老太，确认了细节。5m带露台方拖，觉得价格贵。在考虑，有消息了联系。', 1759026347),
(5070, 146876, 125, '26号，客户打算用餐车售卖大锅菜，向客户确认完设备并报价。\n价目表：\n5 米方拖餐车：6,980 美元\n油炸锅：350 美元\n抽油烟机：350 美元\n冰箱：600 美元\n发电机：720 美元\n烧烤：350 美元\n燃气扒炉：350 美元\n3+1 水槽：500 美元\n插座：免费\n总计：6,980 美元 + 350 美元 + 350 美元 + 600 美元 + 720 美元 + 350 美元 + 350 美元 + 500 美元 = 10,200 美元\n客户想要到门，给客户报运费以及总价，客户下线了；\n28号，客户一直没上线，也没读消息，打算发送水单以及公司视频营销。', 1759026374),
