(5106, 145948, 144, '经过这两天的交流，客户还是打算购买定制款的餐车，用框架箱运输，\n\n目前总共报的价格是21000美元，跟客户说已经给了500美元的折扣\n\n昨天问客户说什么时候购买，客户说星期二，客户开始想在亚马逊购买，我利用这个框架箱跟客户说亚马逊不好运输没我给他买了保险，让他可以在阿里巴巴上付，客户就下载了阿里巴巴，目前就是等待客户的回复，看看是否可以接受这个价格', 1759032450),
(5107, 128619, 82, '9.23客户不信任被拉黑', 1759032633),
(5108, 146433, 157, '9.26 晚上再次发送消息，对方表示收到了邮件，很感兴趣，并提供了地址，让我查询运费。\n9.28 发送报价和运费，解答了相关问题，对方接受tt付款，已发PI，客户说周一会付款。（继续跟进）', 1759032981),
(5109, 147307, 154, '买5米的方拖，资金不够，要分期，给客户报了餐车价格，接受了。运费有点贵，客户还没上线读。这个客户是意大利的，需要coc。但客户没钱，只能先不说coc的事情。餐车加设备加运费（货代报的都是小柜，因为车有5米长，所以走小柜最划算）大概要12000美元，客户上线后，我再跟客户说说运费用小柜的优势，可以接受的话，我再跟客户商量下设备的选择，分期付。这个后期客户可以接受运费的价格，在他预算内，就算意向客户', 1759033051),
