(5168, 147322, 154, '客户准备买一个小圆拖做慈善，预算不够，车加设备加运费6853美元，价格接受了，问了很多细节，问到车供电后没下文了，我跟客户解释了外接电源或者发电机什么情况需要使用，客户应该是去调查了车的供电问题没读我的消息', 1759045786),
(5169, 147307, 154, '后续：客户接受了运费，今天下午把他需要的设备都确认了一遍，给他画了图纸，确认了车内部情况。接下来给客户报价，客户还没回复', 1759045913),
