(5174, 144277, 174, '客户总是已读未回，今天营销了客户来访', 1759046402),
(5175, 145958, 154, '后续：客户说和丈夫商量后，开始已读不回，我只能营销，问客户对餐车遇到了什么问题，客户不回。三种情况：1.丈夫有异议，丈夫不让他买，有些客观情况不能改变。2.她在比价.3. 她当时觉得车还不错只是冲动，冷静下来没有很有必要买，回复我要做决定，有压力。我后续跟进营销的内容是餐车的优势，客户的好评反馈，售后保证。后边隔了一天又问客户对餐车有什么问题，需要我帮忙吗，还是不回，明天打个电话，探探客户意向到底如何', 1759046449),
