(5182, 146697, 71, '已报价，在比价', 1759046720),
(5183, 145027, 144, '9.26：客户有打算只想要150L的酸奶生产线和200L的酸奶生产线，制作好了报价单给客户发送了过去，还有客户还想要吹瓶机，给客户发送了吹瓶机报价单，一个半自动的一个自动的，没有回复', 1759046762),
