(5186, 147462, 130, '今天刚加上客户的联系方式，问了客户准备用来卖什么食物，将会有多少人再餐车上工作。客户回复卖酒，两个人。我为他推荐了三米的方拖，问他需要增添其他的设备吗，目前没有回复', 1759047028),
