(5188, 142370, 135, '一直在发邮件，未收到回复，然后打了电话，没人接', 1759047332),
(5189, 142744, 172, '9.28一直尝试联系客户，昨天客户回复了一句，后来到现在又联系不上了', 1759047340),
(5190, 143264, 154, '后续：今天催款，客户问要交多少定金，我和她协商了一下，交20%。后来问出客户的丈夫说要在明年赶旺季买，我给她写了小作文，劝他现在买。客户松动了，但她有一个重要痛点是车没地方放置，她要花一个月的时间找放车的地方。我回复说先让她交500美元的意向金才能帮她保留这个价格，没回。这个意向金是我随便说的，报的有点高了，客户害怕被骗。明天看客户回不回，不回我就说;“我非常理解您的处境，我们其他客户也有像您这样的突发情况，同时也很想买，他们都是付500美元意向金。那既然您答应了一个月时间来找场地，我相信您是守信用的人，我跟老板申请付200美元的意向金，通过TT支付，我给您保留这个价格一个月”', 1759047467),
(5191, 137477, 149, '一直未回，16号营销，28号营销，均未读未回复', 1759047496),
(5192, 146796, 144, '9.28：跟客户确认了一下油炸机的温度和时间，跟厂家也已经对接了，目前等待厂家做好报价单', 1759047585),
(5193, 146911, 130, '2025.09.26：在WhatsApp上给客户发送各种餐车的图片，问他用餐车来做什么，将会有多少人在里面工作。最终确定为一款BAR系列的双层餐车，后面为他增添了很多设备，然后制作报价单。\n2025.09.28 将报价单发给他后，他说他只想要一个餐车不需要其他的设备了。感觉客户的意向还是很大的，看明天的回复了', 1759047775),
