(5386, 144512, 178, '给客户多次发邮件未回联系不上客户。/隔几天继续给客户发邮件', 1759110462),
(5387, 145704, 178, '这个客户要的是折叠房。他买一个20feet的给他女儿住。和他视频通话，沟通了一些细节之后，发送了报价单。隔了一天他给我发了地址，计算运费，但是运费算完之后，他说他没有钱，放弃购买。我推荐他先付定金，他没有回复我。//今天尝试再次联系', 1759110621),
(5388, 140966, 71, '已报价，中间商，觉得贵，和他客户沟通去了,视频通话看机器，换了小的，做了发票，她的客户没反馈', 1759110706),
(5389, 144845, 178, '这个客户很在意运输问题。他发现泳池需要吊机卸货之后，意愿基本没有了。他说在当地很少有吊机，就算找到吊机，其花费的费用就可以再买一个泳池了，他暂时没有这个能力去找到地方安置泳池.隔几天，再去找他问这个这问题', 1759110764),
