(5419, 141608, 170, '9.29：客户跟进和营销都未回复', 1759113499),
(5420, 138783, 170, '9.28：客户说销售额完成了90%，建议在国庆姐付款，客户未回复。\n           继续跟进', 1759113561),
(5421, 146000, 160, '到门运费太贵 推荐顾客运输至港口 顾客目前正在征询旅游公司同意来放置他的机器 如果顺利 下周会购买', 1759113654),
(5422, 145580, 148, '9.28 客户觉得价格贵，问运费贵还是餐车贵，未读\n9.29问其预算，给他推荐合适的型号。他告诉我只有2.5墨西哥比索（1360美金）。 预算不足', 1759115554),
(5423, 146910, 126, '9.26已给客户发邮件\n9.27客户回复邮件问是否在后周或者波兰有经销商\n9.28回复客户没有经销商，但可以让他做经销商，并且询问客户电话联系方式', 1759115573),
(5424, 147138, 126, '9.26给客户报了2.2米圆拖餐车的价格\n9.27并且告诉客户冰箱的价格，客户说他在工作，完成工作回复我', 1759115799),
(5425, 147883, 146, '9.29跟客户进行沟通，客户想要在那边做我们的代理商，在那边进行宣传，然后吸引那边的客户，达成合作。', 1759115892),
(5426, 147701, 126, '9.28已给客户报3米方拖的价格，客户询问关税和运费（向客户解释我们只收取运费和餐车费用，关税由他的国家收取），询问客户地址，帮他计算运费，客户已读不回', 1759116089),
(5427, 147748, 126, '9.28给客户报价，并向客户解释亚马逊的价格是定金，餐车是定制款，根据他的需求定制价格\n客户说他不想支付关税，也不想支付运费，亚马逊的价格是虚假广告，运用话术向客户解释；客户说他之前2500美元买过餐车，跟客户解释原因，价格上的差异是质量上的差异，而且给客户发送了我们之前客户的水单，告诉他我们有1年的免费质保，终生维修服务，客户已读不回，时间有点晚了。下午继续跟进', 1759116506),
(5428, 147863, 125, '29号，美国客户，客户可能会购买多台。确定客户需求后，给客户报价包括运费，客户担心关税太高，给客户报了到门的运费。\n价目表：\n冷冻披萨机：11,420 美元\n读卡器：560 美元\n变压器：380 美元\n运费：1,700 美元\n总成本：11,420 美元 + 560 美元 + 380 美元 + 1,700 美元 = 14,060 美元\n客户觉得有点贵，给客户营销爱尔兰客户来访，和客户约打视频，客户说太晚了，她要睡觉了，明天继续聊；持续跟进中', 1759116743),
(5429, 147706, 125, '28号给客户发送邮箱，客户未回复，29号给客户打电话', 1759116799),
(5430, 147633, 125, '28号给客户发消息，客户未回复\n29号给客户打电话，没人接，联系不上，继续尝试打电话联系', 1759116861),
(5431, 147026, 125, '29号客户没上线，给客户打电话，没人接，继续尝试联系', 1759116925),
