(5434, 147414, 163, '营销客户来访付钱，打电话未接', 1759117522),
(5435, 146798, 133, '客户想要亚马逊分期付款，现在没有那么多钱，问分期付款大概需要多少钱。还要与合伙人商量。给客户推荐了阿里巴巴付一些定金，做了一个付款链接给客户看，客户暂未回复。', 1759117824),
