(5439, 147129, 119, '一台941USD，不包含刷卡机啥的。\n一上来就想视频，虽然不会法语，还是硬着头皮打了。\n这个客户像是个经销商，我跟他说这个价格最低5台起售，他也同意了。\n目前就是这样.', 1759119647),
