(5444, 147394, 119, '冷藏蔬菜，推荐售价 2,220 美元的一体式型号。到印第安纳波利斯的运费为 365 美元。\n已做报价单\n9.29通话，（黑人妈妈，有个5岁的小男孩）明天付款，计划今晚让她付', 1759125958),
(5445, 145411, 125, '9.22跟客户取得联系后给客户报价，客户说网站上的价格比我报的低，给客户解释网站上的价格是不包含运费和支付方式的，制作报价单发送给客户，客户说没有问题，说银行账户在报价单中，可以直接进行支付；后续一直催单，给客户每天打一次途信，也打语言，客户都没进，今天再给客户打语音，被客户拉黑了。', 1759126604),
