(5476, 147869, 153, '客户是个人卖家，想要小屏幕的，推了艾玩家32英寸屏幕12英寸披萨的披萨机，报价11344美元，利估29，和还有支付模块分别报价了，到港运费210美元，折扣后总价共计1321美元，说了50%定金+50%尾款的付款模式，让客户了解了机器的运行规则，制作报价单后客户说稍后联系', 1759136515),
(5477, 147970, 127, '一番交谈后客户应该比较在意亚马逊上的价格和实际的不一样，用几个话术夹杂着墨西哥成交客户营销向他解释了，还是纠结价格，最后发的解释已读未回。晚上再跟进看看', 1759136571),
