(5495, 147508, 93, '9.28询问对柴油还是电动感兴趣，要报价未回复\n9.29询问是否还有购买计划未回复', 1759139058),
(5496, 147309, 156, '客户要饮料和油炸机一体的售卖机，找到了新厂家，可以做，给客户提供3个方案\n1. 做成分体的，饮料、薯条两台机放一块。 共用一套支付系统 。2. 一体方案：2台售货机并成1台 3.做成售货亭\n客户目前想要机器可以做杯装饮料，这很麻烦要30万开发费，还在确定客户要哪种形式售货机', 1759139611),
