(5532, 148085, 124, '9.29联系客户，发送炸薯条机照片和视频。客户为自己购买。问网站标价，是不是机器价格，话术解释。询问客户支付模块需求。', 1759198934),
(5533, 147574, 124, '9.28 初步联系， 发送照片客户参考，客户感兴趣503和301。503报价6200usd，301报价5800usd。问港口包运费，客户没说，参考曼萨尼约港报价200usd\n9.29打招呼，询问客户对于运费有什么疑问，客户表示没有，提出打电话，未读。\n9.30 营销公司中秋节祝福，提出国庆中秋节折扣活动，200美元折扣，为客户预留', 1759199755),
(5534, 147574, 124, '9.28 初步联系， 发送照片客户参考，客户感兴趣503和301。503报价6200usd，301报价5800usd。问港口包运费，客户没说，参考曼萨尼约港报价200usd\n9.29打招呼，询问客户对于运费有什么疑问，客户表示没有，提出打电话，未读。\n9.30 营销公司中秋节祝福，提出国庆中秋节折扣活动，200美元折扣，为客户预留', 1759199756),
