CREATE TABLE `crm_contacts` (
  `id` int(11) NOT NULL COMMENT 'ID',
  `leads_id` int(11) DEFAULT NULL COMMENT '线索ID',
  `contact_type` tinyint(1) DEFAULT '1' COMMENT '联系方式类型（1-主电话，3-辅助电话）',
  `contact_extra` varchar(100) DEFAULT '' COMMENT 'extra',
  `contact_value` char(11) DEFAULT NULL COMMENT '联系方式值',
  `vdigits` varchar(255) DEFAULT '' COMMENT '纯数字',
  `is_delete` tinyint(1) DEFAULT '0' COMMENT '0-正常/1-删除',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户联系方式关系表' ROW_FORMAT=DYNAMIC;

