--
-- 表的结构 `crm_operation_shops`
--

CREATE TABLE `crm_operation_shops` (
  `id` int(11) NOT NULL COMMENT 'ID',
  `shop_name` varchar(100) NOT NULL COMMENT '店铺名称',
  `channel` varchar(50) NOT NULL COMMENT '所属渠道（对应crm_client_status表的status_name字段，如：c端、抖音、SEM等）',
  `is_active` tinyint(2) NOT NULL DEFAULT '1' COMMENT '是否启用 1=启用 0=禁用',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `add_time` int(11) NOT NULL COMMENT '添加时间',
  `edit_time` int(11) DEFAULT NULL COMMENT '编辑时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='运营店铺表' ROW_FORMAT=DYNAMIC;

