--
-- 表的结构 `crm_order_item`
--

CREATE TABLE `crm_order_item` (
  `id` int(11) NOT NULL COMMENT '明细主键',
  `order_id` int(11) NOT NULL COMMENT '关联订单头ID = crm_client_order.id',
  `line_no` int(11) NOT NULL DEFAULT '1' COMMENT '行号，1,2,3...',
  `product_id` varchar(255) DEFAULT NULL COMMENT '产品ID（可选）',
  `product_name` varchar(200) DEFAULT NULL COMMENT '产品名称（必填）',
  `product_manager` varchar(255) DEFAULT NULL COMMENT '产品经理',
  `manager_id` varchar(255) DEFAULT NULL COMMENT '产品经理id',
  `spec_model` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `supplier_id` varchar(255) DEFAULT NULL COMMENT '供应商ID（可选）',
  `supplier_name` varchar(200) DEFAULT NULL COMMENT '供应商名称（冗余保存）',
  `unit` varchar(50) DEFAULT NULL COMMENT '单位，如台/套/件',
  `qty` int(11) DEFAULT NULL COMMENT '数量',
  `unit_price` varchar(255) DEFAULT NULL COMMENT '销售单价',
  `total_price` varchar(255) DEFAULT NULL COMMENT '售价合计',
  `purchase_price` varchar(255) DEFAULT NULL COMMENT '进价合计',
  `sub_profit` varchar(255) DEFAULT NULL COMMENT '子项利润',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '行备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单明细表（多产品行）';

