-- --------------------------------------------------------

--
-- 表的结构 `crm_order_notifications`
--

CREATE TABLE `crm_order_notifications` (
  `id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL COMMENT '订单ID',
  `order_no` varchar(50) NOT NULL COMMENT '订单编号',
  `contact` varchar(50) NOT NULL COMMENT '联系方式',
  `type` tinyint(1) NOT NULL COMMENT '通知类型：1=审核通过，2=审核拒绝',
  `message` varchar(255) NOT NULL COMMENT '通知消息',
  `target_user` varchar(50) DEFAULT NULL COMMENT '目标用户（订单负责人）',
  `is_read` tinyint(1) DEFAULT '0' COMMENT '是否已读：0=未读，1=已读',
  `auto_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否系统自动归档已读：0=否，1=是',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  `deleted_time` datetime DEFAULT NULL COMMENT '软删除时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='订单审核通知表';

