--
-- 表的结构 `crm_products`
--

CREATE TABLE `crm_products` (
  `id` int(11) NOT NULL,
  `product_name` varchar(255) DEFAULT NULL COMMENT '产品名称',
  `org` varchar(10) DEFAULT '' COMMENT '所属组织(admin,1s,2s,3s)',
  `category_id` int(11) DEFAULT '0' COMMENT '产品分类id',
  `status` tinyint(1) DEFAULT '0' COMMENT '软删除',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '软删除：0=正常 1=删除',
  `deleted_time` datetime DEFAULT NULL COMMENT '删除时间',
  `deleted_by` int(11) DEFAULT NULL COMMENT '删除人ID',
  `add_time` bigint(20) NOT NULL COMMENT '添加时间',
  `edit_time` bigint(20) NOT NULL COMMENT '编辑时间',
  `submit_person` varchar(100) DEFAULT NULL COMMENT '提交人'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品表';

