--
-- 表的结构 `crm_receive_account`
--

CREATE TABLE `crm_receive_account` (
  `id` int(11) NOT NULL COMMENT 'ID',
  `account` varchar(255) CHARACTER SET utf8mb4 NOT NULL COMMENT '收款账户',
  `receiver` varchar(255) CHARACTER SET utf8mb4 NOT NULL COMMENT '创建人',
  `create_time` bigint(20) NOT NULL COMMENT '创建时间',
  `update_time` bigint(20) NOT NULL COMMENT '修改时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除 0=否 1=是',
  `deleted_time` datetime DEFAULT NULL COMMENT '删除时间',
  `deleted_by` int(11) DEFAULT NULL COMMENT '删除人ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='收款账户表';

