--
-- 表的结构 `crm_table_column_order`
--

CREATE TABLE `crm_table_column_order` (
  `id` int(10) UNSIGNED NOT NULL,
  `admin_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID',
  `page_key` varchar(100) NOT NULL COMMENT '页面标识，例如 pending_order',
  `table_key` varchar(100) NOT NULL COMMENT '表格标识，例如 main_table / item_table',
  `column_order` text NOT NULL COMMENT '字段顺序JSON数组，例如 ["order_sn","customer_name"]',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `update_time` int(10) UNSIGNED NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='表格列顺序配置表';

