--
-- 表的结构 `crm_table_col_config`
--

CREATE TABLE `crm_table_col_config` (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT '主键',
  `uid` int(10) UNSIGNED NOT NULL COMMENT '用户ID（对应你系统的登录用户表主键）',
  `page_key` varchar(100) NOT NULL COMMENT '页面/表格唯一标识（例如: order_pending / 待审核订单）',
  `config_json` mediumtext NOT NULL COMMENT '列配置JSON：每列的显示/隐藏等（如 {cols:{field:{hide:0}}} ）',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '创建时间(时间戳)',
  `ut_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '更新时间(时间戳)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='表格列显示/隐藏配置(按用户+页面记忆)';

