  `addtime` varchar(15) DEFAULT NULL COMMENT '添加时间',
  `feast_date` varchar(20) DEFAULT '' COMMENT '节日日期',
  `type` int(1) DEFAULT '1' COMMENT '1阳历 2农历'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='节日列表' ROW_FORMAT=DYNAMIC;

