--
-- 表的结构 `oauth`
--

CREATE TABLE `oauth` (
  `id` int(11) NOT NULL,
  `uid` int(11) DEFAULT NULL COMMENT '用户id',
  `type` varchar(50) DEFAULT NULL COMMENT '账号类型',
  `openid` varchar(120) DEFAULT NULL COMMENT '第三方唯一标示'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- 表的结构 `page`
--

CREATE TABLE `page` (
  `id` int(11) UNSIGNED NOT NULL,
  `title` varchar(80) NOT NULL DEFAULT '',
  `title_style` varchar(225) NOT NULL DEFAULT '',
  `thumb` varchar(225) NOT NULL DEFAULT '',
  `hits` int(11) UNSIGNED NOT NULL DEFAULT '0',
  `status` varchar(255) NOT NULL DEFAULT '1',
  `userid` int(8) UNSIGNED NOT NULL DEFAULT '0',
  `username` varchar(40) NOT NULL DEFAULT '',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `createtime` int(11) UNSIGNED NOT NULL DEFAULT '0',
  `updatetime` int(11) UNSIGNED NOT NULL DEFAULT '0',
  `lang` tinyint(1) UNSIGNED NOT NULL DEFAULT '0',
  `content` text COMMENT '内容',
  `template` varchar(50) DEFAULT ''
) ENGINE=MyISAM DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

--
-- 转存表中的数据 `page`
--

INSERT INTO `page` (`id`, `title`, `title_style`, `thumb`, `hits`, `status`, `userid`, `username`, `sort`, `createtime`, `updatetime`, `lang`, `content`, `template`) VALUES
(2, '发过火', 'color:rgb(95, 184, 120);font-weight:normal;', '/uploads/20180611/b78388d0d1b123e06d900c4d1a1d88ba.jpg', 40, '1', 0, '', 0, 1504251653, 0, 0, '<p style=\"font-size:14px;font-family:;\">\n	<a href=\"http://www.cltphp.com/\" target=\"_blank\"><span style=\"color:#92D050;\">CLTPHP内容管理系统</span></a>，包含系统设置，权限管理，模型管理，数据库管理，栏目管理，会员管理，网站功能，模版管理，微信管理等相关模块。基于ThinkPHP5开发，后台采用Layui框架完全自适应，数据交互采用更高效简洁的angularjs实现，。\n</p>\n<p style=\"font-size:14px;font-family:\'Microsoft yahei\', Arial, Tahoma, Verdana;vertical-align:baseline;color:#979797;background-color:#FFFFFF;\">\n	  <a target=\"_blank\" href=\"http://www.cltphp.com/\"><span style=\"color:#92D050;\">CLTPHP</span></a>采用ThinkPHP开发，ThinkPHP5采用全新的架构思想，引入了很多的PHP新特性，优化了核心，减少了依赖，实现了真正的惰性加载。正因为ThinkPHP的这些新特性，从而使得CLTPHP的执行速度成倍提高。\n</p>\n<p style=\"font-size:14px;\">\n	  UI方面，<a target=\"_blank\" href=\"http://www.cltphp.com/\"><span style=\"color:#92D050;\">CLTPHP</span></a>采用了最受欢迎的Layui，Layui用于开发响应式布局、移动设备优先的 WEB 项目。简洁、直观、强悍的前端开发框架，让CLTPHP的后台界面更加美观，开发更迅速、简单。</p><p><br></p>', '0'),
(8, '联系我们', 'color:;font-weight:normal;', '', 12, '1', 0, '', 0, 1499765407, 0, 0, '<p>您的支持是我们一往无前的无限动力，非常荣幸在<a target=\"_self\" href=\"http://www.cltphp.com/\">CLTPHP</a>成长的道路上有您的陪伴！！！</p><p><img style=\"max-width:100%;\" src=\"http://api.map.baidu.com/staticimage?center=108.946465,34.347269&zoom=11&amp;width=478&amp;height=258&amp;markers=108.951945,34.324907\"><br></p><p><br></p>', '0');

