--
-- 表的结构 `role_user`
--

CREATE TABLE `role_user` (
  `role_id` mediumint(9) UNSIGNED DEFAULT '0',
  `user_id` char(32) DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8 ROW_FORMAT=FIXED;

